.sidebar-category-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 9px 4px;
}

.sidebar-category-head strong {
  color: #a49791;
  font-size: 11px;
  font-weight: 850;
  letter-spacing: .055em;
}

.sidebar-category-head span {
  color: #756963;
  font-size: 10px;
}

.sidebar-category-links {
  display: grid;
  gap: 2px;
}

.nav-section-label {
  font-size: 10px;
  letter-spacing: .09em;
}

.global-page-link {
  min-height: 38px;
  gap: 9px;
}

.sidebar-page-icon {
  width: 25px;
  height: 25px;
  flex: 0 0 25px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(var(--gold-rgb),.08);
  border-radius: 8px;
  background: rgba(var(--gold-rgb),.035);
  font-size: 13px;
}

.global-page-link:hover .sidebar-page-icon,
.global-page-link.is-current .sidebar-page-icon {
  border-color: rgba(var(--accent-rgb),.18);
  background: rgba(var(--accent-rgb),.075);
}

.global-page-link.is-current {
  background: linear-gradient(90deg, rgba(var(--accent-rgb),.16), rgba(var(--accent-rgb),.055));
  color: #f4a198;
  box-shadow:
    inset 3px 0 0 rgba(var(--accent-rgb),.92),
    inset 0 0 0 1px rgba(var(--accent-rgb),.1),
    0 5px 18px rgba(0,0,0,.08);
}

.global-page-link.is-current .global-page-copy strong {
  color: #fff1ed;
  font-weight: 850;
}

.sidebar-edge-toggle {
  display: none;
}

.article-toc {
  width: 220px;
  padding-left: 18px;
}

.article-toc-label {
  font-size: 11px;
}

.article-toc-item {
  padding-block: 7px;
  font-size: 12px;
  line-height: 1.5;
}

.article-progress {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 7px;
  color: #786b66;
  font-size: 11px;
}

.article-progress strong {
  color: #b99b73;
  font-size: 11px;
}

.article-progress-track {
  position: absolute;
  left: -1px;
  top: 15px;
  bottom: 15px;
  width: 2px;
  overflow: hidden;
  border-radius: 99px;
  background: rgba(var(--gold-rgb),.08);
}

.article-progress-track span {
  display: block;
  width: 100%;
  min-height: 2px;
  border-radius: inherit;
  background: linear-gradient(180deg, #d7aa62, #d95447);
  transition: height .16s ease-out;
}

.recent-update-card {
  min-height: 116px;
  align-content: start;
}

.recent-update-date {
  color: #a4938c;
  font-size: 11px;
}

.recent-update-card strong {
  font-size: 14px;
  line-height: 1.4;
}

.recent-update-summary {
  display: -webkit-box;
  padding-right: 18px;
  overflow: hidden;
  color: #a99a93;
  font-size: 12px;
  line-height: 1.55;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.related-doc-image {
  overflow: hidden;
  background: linear-gradient(135deg, rgba(var(--accent-rgb),.1), rgba(var(--gold-rgb),.08));
}

.search-result-card.is-selected {
  background: rgba(var(--accent-rgb),.11);
  box-shadow: inset 2px 0 0 rgba(var(--accent-rgb),.72);
}

.search-result-category {
  width: max-content;
  padding: 2px 6px;
  border: 1px solid rgba(var(--gold-rgb),.14);
  border-radius: 999px;
  background: rgba(var(--gold-rgb),.045);
  color: #b18e63;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .05em;
}

.search-result-card[data-category="주요 콘텐츠"] .search-result-category {
  border-color: rgba(var(--accent-rgb),.18);
  background: rgba(var(--accent-rgb),.055);
  color: #d87b71;
}

.search-result-card[data-category="성장 · 경제"] .search-result-category {
  border-color: rgba(194,126,56,.18);
  background: rgba(194,126,56,.055);
  color: #c8945e;
}

.draft-notice {
  width: min(100%, var(--content-max));
  margin: 0 auto;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  border: 1px dashed rgba(var(--gold-rgb),.22);
  border-radius: 14px;
  background: rgba(var(--gold-rgb),.035);
}

.draft-notice > span {
  padding: 4px 8px;
  border-radius: 999px;
  background: rgba(var(--gold-rgb),.08);
  color: #c7a169;
  font-size: 10px;
  font-weight: 850;
}

.draft-notice > div {
  display: grid;
  gap: 3px;
}

.draft-notice strong {
  font-size: 13px;
}

.draft-notice small {
  color: #8e817b;
  font-size: 11px;
}

.status-services {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.status-services article {
  min-height: 118px;
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) auto;
  align-items: center;
  gap: 13px;
  padding: 17px;
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 15px;
  background: rgba(15,20,28,.82);
}

.status-service-icon {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border-radius: 12px;
  background: rgba(var(--gold-rgb),.07);
  color: #d6a85f;
  font-size: 18px;
}

.status-services article > div {
  display: grid;
  gap: 4px;
}

.status-services small,
.status-services a {
  font-size: 9px;
}

.status-services small {
  color: #746762;
}

.status-services strong {
  font-size: 14px;
}

.status-services span {
  color: #8a7c76;
  font-size: 10px;
}

.status-services a {
  color: #96877f;
  text-decoration: none;
}

.status-services article[data-tone="success"] {
  border-color: rgba(111,185,131,.18);
}

.status-services article[data-tone="warning"] {
  border-color: rgba(var(--accent-rgb),.3);
}

.status-services article[data-tone="working"] {
  border-color: rgba(var(--gold-rgb),.2);
}

.status-dot.is-warning {
  background: #df6b5f;
  box-shadow: 0 0 14px rgba(223,107,95,.55);
}

.status-asset-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  overflow: hidden;
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 15px;
  background: rgba(15,20,28,.72);
}

.status-asset-metrics > div {
  min-height: 90px;
  padding: 16px;
  display: grid;
  align-content: center;
  gap: 5px;
}

.status-asset-metrics > div + div {
  border-left: 1px solid rgba(255,255,255,.06);
}

.status-asset-metrics small {
  color: #746762;
  font-size: 9px;
}

.status-asset-metrics strong {
  font-size: 18px;
}

.status-recent-list a > span:first-child {
  display: grid;
  gap: 4px;
}

.status-recent-list small {
  max-width: 700px;
  overflow: hidden;
  color: #7f716b;
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.wiki-directory,
.recent-updates,
.related-docs {
  content-visibility: auto;
  contain-intrinsic-size: auto 760px;
}

.directory-group {
  content-visibility: auto;
  contain-intrinsic-size: auto 430px;
}

.starter-step:focus-visible,
.directory-card:focus-visible,
.recent-update-card:focus-visible,
.related-doc-card:focus-visible,
.sidebar-edge-toggle:focus-visible {
  outline: 2px solid rgba(var(--gold-rgb),.7);
  outline-offset: 2px;
}

@media (min-width: 981px) {
  .starter-step,
  .starter-step:nth-child(4),
  .starter-step:nth-child(5) {
    min-height: 142px;
  }

  .recent-update-list {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 11px;
  }

  .sidebar-edge-toggle {
    position: fixed;
    z-index: 36;
    top: calc(var(--topbar) + 19px);
    left: calc(var(--sidebar) - 14px);
    width: 29px;
    height: 44px;
    display: grid;
    place-items: center;
    padding: 0;
    border: 1px solid rgba(var(--gold-rgb),.15);
    border-radius: 0 11px 11px 0;
    background: rgba(15,12,13,.97);
    color: #b5a7a0;
    cursor: pointer;
    box-shadow: 5px 8px 20px rgba(0,0,0,.18);
    transition: left .24s cubic-bezier(.2,.75,.25,1), width .18s ease, border-radius .18s ease, color .18s ease, background .18s ease;
  }

  .sidebar-edge-toggle:hover {
    border-color: rgba(var(--gold-rgb),.3);
    background: rgba(var(--gold-rgb),.075);
    color: #e5c487;
  }

  .sidebar-toggle-expanded {
    font-size: 22px;
    line-height: 1;
  }

  .sidebar-toggle-collapsed {
    display: none;
    align-items: center;
    gap: 6px;
  }

  .sidebar-toggle-collapsed b {
    font-size: 14px;
  }

  .sidebar-toggle-collapsed em {
    font-size: 10px;
    font-style: normal;
    font-weight: 800;
  }

  .wiki-sidebar {
    transition: transform .24s cubic-bezier(.2,.75,.25,1), opacity .18s ease;
  }

  .wiki-main {
    transition: padding-left .24s cubic-bezier(.2,.75,.25,1), padding-right .24s cubic-bezier(.2,.75,.25,1);
  }

  html[data-sidebar="collapsed"] .wiki-sidebar,
  .wiki-shell.is-sidebar-collapsed .wiki-sidebar {
    transform: translateX(calc(-100% - 8px));
    opacity: 0;
    pointer-events: none;
  }

  html[data-sidebar="collapsed"] .wiki-main,
  .wiki-shell.is-sidebar-collapsed .wiki-main {
    padding-left: 32px;
  }

  html[data-sidebar="collapsed"] .wiki-main.has-article-toc,
  .wiki-shell.is-sidebar-collapsed .wiki-main.has-article-toc {
    padding-left: 250px;
    padding-right: 250px;
  }

  html[data-sidebar="collapsed"] .sidebar-edge-toggle,
  .wiki-shell.is-sidebar-collapsed .sidebar-edge-toggle {
    left: 14px;
    width: 70px;
    border-radius: 11px;
  }

  html[data-sidebar="collapsed"] .sidebar-toggle-expanded,
  .wiki-shell.is-sidebar-collapsed .sidebar-toggle-expanded {
    display: none;
  }

  html[data-sidebar="collapsed"] .sidebar-toggle-collapsed,
  .wiki-shell.is-sidebar-collapsed .sidebar-toggle-collapsed {
    display: inline-flex;
  }
}

@media (min-width: 1320px) {
  .starter-steps {
    position: relative;
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }

  .starter-step,
  .starter-step:nth-child(4),
  .starter-step:nth-child(5),
  .starter-step:last-child {
    grid-column: auto;
    min-height: 146px;
  }

  .starter-step:not(:last-child)::after {
    content: "›";
    position: absolute;
    z-index: 4;
    top: 50%;
    right: -10px;
    transform: translateY(-50%);
    color: rgba(var(--gold-rgb),.46);
    font-size: 18px;
    pointer-events: none;
  }
}

@media (max-width: 1279px) {
  .article-toc {
    display: none;
  }

  .mobile-current-toc {
    display: grid;
  }
}

@media (max-width: 1180px) {
  .directory-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 980px) {
  .wiki-topbar,
  .wiki-sidebar,
  .hero-badge,
  .hero-search-cta,
  .search-modal-backdrop {
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
  }

  .wiki-topbar {
    background: rgba(10,9,10,.97);
  }

  .wiki-sidebar {
    background: rgba(13,11,12,.985);
  }

  .wiki-hero.has-hero-image.is-home {
    min-height: 315px;
  }

  .wiki-hero.is-article {
    padding: 17px 20px;
  }

  .starter-guide,
  .wiki-directory,
  .recent-updates,
  .related-docs,
  .document-card {
    box-shadow: none !important;
  }

  .starter-steps {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .starter-step,
  .starter-step:nth-child(4),
  .starter-step:nth-child(5) {
    grid-column: auto;
  }

  .starter-step:last-child {
    grid-column: span 2;
  }
}

@media (max-width: 760px) {
  .directory-grid,
  .status-services,
  .status-asset-metrics {
    grid-template-columns: 1fr;
  }

  .directory-card {
    grid-template-columns: 72px minmax(0, 1fr) 20px;
    min-height: 104px;
    padding: 14px;
  }

  .directory-media {
    width: 72px;
    height: 72px;
  }

  .directory-title-row strong {
    font-size: 14px;
  }

  .status-asset-metrics > div + div {
    border-left: 0;
    border-top: 1px solid rgba(255,255,255,.06);
  }
}

@media (max-width: 620px) {
  .wiki-topbar {
    min-height: var(--topbar);
  }

  .menu-button,
  .header-search-button,
  .theme-toggle {
    min-width: 44px;
    width: 44px;
    min-height: 44px;
    height: 44px;
    display: grid;
    place-items: center;
  }

  .menu-button {
    padding: 0;
  }

  .top-actions {
    gap: 6px;
  }

  .wiki-main {
    gap: 16px;
  }

  .wiki-hero.has-hero-image.is-home {
    min-height: 300px;
    padding: 18px;
  }

  .hero-copy h1 {
    font-size: 29px;
  }

  .hero-copy > p:last-of-type {
    font-size: 12px;
    line-height: 1.6;
  }

  .hero-search-cta {
    min-height: 46px;
    margin-top: 14px;
  }

  .wiki-hero.is-article {
    padding: 14px 16px;
    border-radius: 15px;
  }

  .wiki-hero.is-article .hero-copy h1 {
    font-size: 26px;
  }

  .starter-guide {
    padding: 15px;
  }

  .starter-guide-head {
    margin-bottom: 11px;
  }

  .starter-steps {
    grid-template-columns: 1fr;
    gap: 7px;
  }

  .starter-step,
  .starter-step:last-child {
    min-height: 72px;
    grid-column: auto;
    grid-template-columns: 34px minmax(0, 1fr) 18px;
    grid-template-rows: auto auto;
    column-gap: 10px;
    row-gap: 2px;
    padding: 10px 11px;
  }

  .starter-number {
    grid-column: 1;
    grid-row: 1 / 3;
    align-self: center;
    font-size: 12px;
  }

  .starter-icon {
    display: none;
  }

  .starter-copy {
    grid-column: 2;
    grid-row: 1;
    align-content: end;
    padding: 0;
  }

  .starter-copy strong {
    font-size: 14px;
  }

  .starter-copy small {
    display: none;
  }

  .starter-target {
    grid-column: 2;
    grid-row: 2;
    align-self: start;
    font-size: 11px;
  }

  .starter-target em {
    font-size: 7px;
  }

  .starter-arrow {
    grid-column: 3;
    grid-row: 1 / 3;
    align-self: center;
    justify-self: end;
    font-size: 15px;
  }

  .recent-update-card {
    min-height: 104px;
  }

  .recent-update-date {
    font-size: 11px;
  }

  .recent-update-card strong {
    font-size: 14px;
  }

  .recent-update-summary {
    font-size: 12px;
  }

  .draft-notice {
    grid-template-columns: 1fr;
    gap: 8px;
  }
}

@media (max-width: 520px) {
  .directory-heading > div > span {
    font-size: 10px;
  }

  .directory-card {
    grid-template-columns: 66px minmax(0, 1fr) 18px;
    min-height: 96px;
  }

  .directory-media {
    width: 66px;
    height: 66px;
  }

  .status-services article {
    grid-template-columns: 38px minmax(0, 1fr);
  }

  .status-services article > a {
    grid-column: 2;
  }
}

html[data-theme="light"] .directory-card.is-featured {
  border-color: rgba(184,61,52,.2);
  background:
    linear-gradient(135deg, rgba(184,61,52,.065), rgba(149,107,47,.025) 62%, transparent 84%),
    rgba(255,255,255,.58);
  box-shadow: inset 3px 0 0 rgba(184,61,52,.5), 0 8px 24px rgba(74,48,33,.06);
}

html[data-theme="light"] .directory-card.is-featured .directory-title-row strong {
  color: #4a302b;
}

html[data-theme="light"] .directory-card.is-draft {
  border-color: rgba(118,84,55,.14);
  background: rgba(255,255,255,.36);
}

html[data-theme="light"] .directory-title-row em {
  border-color: rgba(149,107,47,.2);
  background: rgba(149,107,47,.07);
  color: #80571f;
}

html[data-theme="light"] .global-page-link.is-current {
  background: linear-gradient(90deg, rgba(184,61,52,.12), rgba(184,61,52,.035));
  color: #9f3029;
  box-shadow: inset 3px 0 0 rgba(184,61,52,.72), inset 0 0 0 1px rgba(184,61,52,.07);
}

html[data-theme="light"] .global-page-link.is-current .global-page-copy strong {
  color: #76251f;
}

html[data-theme="light"] .sidebar-page-icon,
html[data-theme="light"] .starter-icon {
  border-color: rgba(149,107,47,.15);
  background: rgba(149,107,47,.06);
}

html[data-theme="light"] .sidebar-category-head strong {
  color: #776862;
}

html[data-theme="light"] .search-result-card.is-selected {
  background: rgba(184,61,52,.08);
  box-shadow: inset 2px 0 0 rgba(184,61,52,.6);
}

html[data-theme="light"] .status-services article,
html[data-theme="light"] .status-asset-metrics,
html[data-theme="light"] .draft-notice {
  border-color: rgba(118,84,55,.14);
  background: rgba(255,250,243,.84);
}

html[data-theme="light"] .sidebar-edge-toggle {
  border-color: rgba(95,68,51,.14);
  background: rgba(250,246,239,.98);
  color: #6e5c54;
}

html[data-theme="light"] .notion-simple-table,
html[data-theme="light"] .notion-table,
html[data-theme="light"] .notion-bookmark,
html[data-theme="light"] .notion-callout,
html[data-theme="light"] .notion-toggle {
  border-color: rgba(118,84,55,.15) !important;
}

html[data-theme="light"] .notion-callout {
  background: rgba(184,61,52,.035) !important;
}

html[data-theme="light"] .notion-toggle:hover {
  background: rgba(149,107,47,.035) !important;
}

html[data-theme="light"] .notion-bookmark:hover {
  border-color: rgba(184,61,52,.2) !important;
}

@media (prefers-reduced-motion: reduce) {
  .wiki-sidebar,
  .wiki-main,
  .sidebar-edge-toggle {
    transition: none !important;
  }
}



/* === Reader UX pass 2026-09-25 === */
.directory-group {
  scroll-margin-top: calc(var(--topbar) + 20px);
}

.search-result-meta-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
}

.search-draft-badge {
  padding: 2px 6px;
  border: 1px dashed rgba(160,147,140,.22);
  border-radius: 999px;
  color: #a99a93;
  font-size: 9px;
  font-style: normal;
  font-weight: 800;
}

.document-card .notion-table,
.document-card .notion-simple-table {
  max-width: 100%;
  overflow-x: auto !important;
  overflow-y: hidden;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
  scrollbar-color: rgba(var(--gold-rgb),.28) transparent;
}

.document-card .notion-table::-webkit-scrollbar,
.document-card .notion-simple-table::-webkit-scrollbar {
  height: 6px;
}

.document-card .notion-table::-webkit-scrollbar-thumb,
.document-card .notion-simple-table::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: rgba(var(--gold-rgb),.25);
}

.mobile-reading-tools {
  display: none;
}

.state-card {
  display: grid;
  justify-items: center;
  gap: 10px;
}

.state-icon {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border: 1px solid rgba(var(--accent-rgb),.24);
  border-radius: 50%;
  background: rgba(var(--accent-rgb),.08);
  color: #e48378;
  font-weight: 900;
}

.state-actions {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 6px;
}

.state-actions a,
.state-actions button {
  min-height: 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 15px;
  border-radius: 10px;
  text-decoration: none;
  cursor: pointer;
}

.state-actions a {
  border: 1px solid rgba(var(--gold-rgb),.18);
  background: rgba(var(--gold-rgb),.055);
  color: #cbb189;
}

.loading-wiki-shell {
  min-height: 100vh;
  background: var(--bg);
  color: var(--text);
}

.loading-topbar {
  position: fixed;
  z-index: 40;
  inset: 0 0 auto 0;
  height: var(--topbar);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 22px;
  border-bottom: 1px solid rgba(255,255,255,.06);
  background: rgba(9,9,10,.96);
}

.loading-logo,
.loading-line,
.loading-search,
.loading-nav-item,
.loading-block {
  display: block;
  overflow: hidden;
  background: rgba(255,255,255,.055);
  position: relative;
}

.loading-logo::after,
.loading-line::after,
.loading-search::after,
.loading-nav-item::after,
.loading-block::after {
  content: "";
  position: absolute;
  inset: 0;
  transform: translateX(-100%);
  background: linear-gradient(90deg, transparent, rgba(255,255,255,.06), transparent);
  animation: wikiSkeleton 1.5s ease-in-out infinite;
}

.loading-logo {
  width: 46px;
  height: 46px;
  border-radius: 12px;
}

.loading-line {
  height: 11px;
  border-radius: 999px;
}

.loading-line.is-brand { width: 190px; }
.loading-line.is-title { width: 92px; margin-bottom: 14px; }
.loading-line.is-kicker { width: 120px; }
.loading-line.is-heading { width: min(65%, 520px); height: 36px; }
.loading-line.is-wide { width: 92%; }
.loading-line.is-medium { width: 64%; }

.loading-search {
  width: 220px;
  height: 38px;
  margin-left: auto;
  border-radius: 11px;
}

.loading-sidebar {
  position: fixed;
  top: var(--topbar);
  bottom: 0;
  left: 0;
  width: var(--sidebar);
  padding: 25px 20px;
  border-right: 1px solid rgba(255,255,255,.05);
  background: rgba(13,11,12,.96);
}

.loading-nav-item {
  width: 100%;
  height: 38px;
  margin: 6px 0;
  border-radius: 9px;
}

.loading-main {
  min-height: 100vh;
  padding: calc(var(--topbar) + 28px) 32px 72px calc(var(--sidebar) + 32px);
  display: grid;
  align-content: start;
  gap: 20px;
}

.loading-hero,
.loading-document {
  width: min(100%, var(--content-max));
  margin: 0 auto;
  display: grid;
  gap: 16px;
  border: 1px solid rgba(255,255,255,.055);
  background: rgba(255,255,255,.018);
}

.loading-hero {
  min-height: 138px;
  align-content: center;
  padding: 26px;
  border-radius: 20px;
}

.loading-document {
  min-height: 360px;
  align-content: start;
  padding: 34px;
  border-radius: 18px;
}

.loading-block {
  width: 100%;
  height: 150px;
  margin-top: 8px;
  border-radius: 14px;
}

@keyframes wikiSkeleton {
  100% { transform: translateX(100%); }
}

@media (max-width: 1279px) {
  .toc-list {
    display: flex;
    flex-direction: column;
  }

  .mobile-current-toc {
    order: -1;
    margin-bottom: 10px;
    padding-bottom: 12px;
    border-bottom: 1px solid rgba(var(--gold-rgb),.08);
  }

  .mobile-current-toc .nav-section-label::after {
    content: " · 현재 문서";
  }
}

@media (max-width: 980px) {
  .global-page-link,
  .toc-item {
    min-height: 46px;
  }

  .global-page-link {
    align-items: center;
  }

  .loading-sidebar {
    display: none;
  }

  .loading-main {
    padding: calc(var(--topbar) + 18px) 14px 56px;
  }

  .loading-search {
    width: 44px;
  }

  .mobile-reading-tools {
    position: fixed;
    z-index: 35;
    right: 14px;
    bottom: max(16px, env(safe-area-inset-bottom));
    display: flex;
    gap: 7px;
    opacity: 0;
    transform: translateY(10px);
    pointer-events: none;
    transition: opacity .18s ease, transform .18s ease;
  }

  .mobile-reading-tools.is-visible {
    opacity: 1;
    transform: translateY(0);
    pointer-events: auto;
  }

  .mobile-reading-tools button {
    min-height: 44px;
    display: inline-flex;
    align-items: center;
    gap: 5px;
    padding: 0 12px;
    border: 1px solid rgba(var(--gold-rgb),.2);
    border-radius: 999px;
    background: rgba(15,12,13,.94);
    color: #d6c3b8;
    box-shadow: 0 8px 28px rgba(0,0,0,.28);
    cursor: pointer;
  }

  .mobile-reading-tools button span {
    font-size: 10px;
    font-weight: 800;
  }
}

@media (max-width: 620px) {
  .page-updated,
  .page-siblings small,
  .status-services small,
  .status-services span {
    font-size: 11px;
  }

  .breadcrumbs {
    font-size: 12px;
    line-height: 1.55;
    flex-wrap: wrap;
  }

  .search-result-category,
  .search-draft-badge {
    font-size: 10px;
  }

  .loading-topbar {
    padding: 0 12px;
  }

  .loading-line.is-brand {
    width: 120px;
  }

  .loading-main {
    gap: 14px;
  }

  .loading-hero {
    min-height: 110px;
    padding: 20px;
  }

  .loading-document {
    padding: 22px 18px;
  }
}

html[data-theme="light"] .mobile-reading-tools button,
html[data-theme="light"] .state-actions a {
  border-color: rgba(118,84,55,.16);
  background: rgba(255,250,243,.96);
  color: #665149;
}

@media (prefers-reduced-motion: reduce) {
  .loading-logo::after,
  .loading-line::after,
  .loading-search::after,
  .loading-nav-item::after,
  .loading-block::after {
    animation: none;
  }
}


/* === Content maturity, recent history and mobile navigation === */
.directory-card.is-brief {
  border-color: rgba(var(--gold-rgb),.14);
  background:
    linear-gradient(135deg, rgba(var(--gold-rgb),.045), transparent 68%),
    rgba(255,255,255,.015);
}

.directory-card.is-brief .directory-title-row em {
  border-color: rgba(var(--gold-rgb),.18);
  background: rgba(var(--gold-rgb),.055);
  color: #c7a169;
}

.directory-drafts {
  margin-top: 12px;
  border-top: 1px dashed rgba(var(--gold-rgb),.12);
}

.directory-drafts > summary {
  min-height: 46px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 4px 8px;
  color: #9b8d87;
  cursor: pointer;
  list-style: none;
  user-select: none;
}

.directory-drafts > summary::-webkit-details-marker {
  display: none;
}

.directory-drafts > summary::after {
  content: "⌄";
  margin-left: auto;
  color: #8f817b;
  transition: transform .18s ease;
}

.directory-drafts[open] > summary::after {
  transform: rotate(180deg);
}

.directory-drafts > summary span {
  font-size: 11px;
  font-weight: 800;
}

.directory-drafts > summary small {
  margin-left: auto;
  color: #776b66;
  font-size: 10px;
}

.directory-grid.is-drafts {
  padding-top: 4px;
  padding-bottom: 4px;
}

.sidebar-category-head {
  width: 100%;
  border: 0;
  background: transparent;
  font: inherit;
  text-align: left;
}

.sidebar-category-meta {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.sidebar-category-meta b {
  display: none;
  color: #887a74;
  font-size: 12px;
  font-weight: 700;
  transition: transform .16s ease;
}

.recent-viewed {
  width: min(100%, var(--content-max));
  margin: 0 auto;
  padding: 16px 18px;
  border: 1px solid rgba(255,255,255,.05);
  border-radius: 16px;
  background: rgba(255,255,255,.014);
}

.recent-viewed-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 10px;
}

.recent-viewed-head p {
  margin: 0 0 3px;
  color: #ad8957;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: .12em;
}

.recent-viewed-head h2 {
  margin: 0;
  font-size: 16px;
}

.recent-viewed-head > small {
  color: var(--text-subtle);
  font-size: 10px;
}

.recent-viewed-list {
  display: grid;
  grid-template-columns: repeat(5, minmax(0,1fr));
  gap: 8px;
}

.recent-viewed-card {
  min-width: 0;
  min-height: 48px;
  display: grid;
  grid-template-columns: 24px minmax(0,1fr) 16px;
  align-items: center;
  gap: 7px;
  padding: 9px 10px;
  border: 1px solid rgba(255,255,255,.05);
  border-radius: 11px;
  background: rgba(255,255,255,.018);
  color: inherit;
  text-decoration: none;
}

.recent-viewed-card > span {
  display: grid;
  place-items: center;
  font-size: 14px;
}

.recent-viewed-card strong {
  min-width: 0;
  overflow: hidden;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.recent-viewed-card b {
  color: #71655f;
  font-size: 11px;
}

.recent-viewed-card:hover {
  border-color: rgba(var(--gold-rgb),.18);
  background: rgba(var(--gold-rgb),.035);
}

.recent-update-date {
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.recent-update-date > small {
  color: var(--text-subtle);
  font-size: 10px;
}

.search-loading-list {
  display: grid;
  gap: 4px;
  padding: 4px;
}

.search-loading-row {
  min-height: 70px;
  display: grid;
  grid-template-columns: 40px minmax(0,1fr) 46px;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border-radius: 12px;
  background: rgba(255,255,255,.012);
}

.search-loading-row > * {
  display: block;
  overflow: hidden;
  position: relative;
  border-radius: 7px;
  background: rgba(255,255,255,.055);
}

.search-loading-row > *::after {
  content: "";
  position: absolute;
  inset: 0;
  transform: translateX(-100%);
  background: linear-gradient(90deg, transparent, rgba(255,255,255,.055), transparent);
  animation: wikiSkeleton 1.4s ease-in-out infinite;
}

.search-loading-row i {
  width: 40px;
  height: 40px;
  border-radius: 10px;
}

.search-loading-row b {
  width: 62%;
  height: 12px;
}

.search-loading-row em {
  width: 40px;
  height: 9px;
}

.mobile-toc-backdrop {
  display: none;
}

@media (max-width: 1180px) {
  .recent-viewed-list {
    grid-template-columns: repeat(3, minmax(0,1fr));
  }
}

@media (max-width: 980px) {
  .sidebar-category-head {
    min-height: 44px;
    padding-block: 7px;
    cursor: pointer;
  }

  .sidebar-category-meta b {
    display: inline-block;
  }

  .sidebar-category.is-mobile-open .sidebar-category-meta b {
    transform: rotate(180deg);
  }

  .sidebar-category-links {
    display: none;
  }

  .sidebar-category.is-mobile-open .sidebar-category-links {
    display: grid;
  }

  .mobile-toc-backdrop {
    position: fixed;
    z-index: 70;
    inset: 0;
    display: flex;
    align-items: flex-end;
    justify-content: stretch;
    background: rgba(0,0,0,.58);
  }

  .mobile-toc-sheet {
    width: 100%;
    max-height: min(76vh, 720px);
    display: grid;
    grid-template-rows: auto auto auto minmax(0,1fr);
    padding: 8px 14px max(14px, env(safe-area-inset-bottom));
    overflow: hidden;
    border: 1px solid rgba(var(--gold-rgb),.16);
    border-bottom: 0;
    border-radius: 20px 20px 0 0;
    background: rgba(14,12,13,.985);
    box-shadow: 0 -18px 60px rgba(0,0,0,.32);
  }

  .mobile-toc-handle {
    width: 42px;
    height: 4px;
    margin: 0 auto 8px;
    border-radius: 99px;
    background: rgba(255,255,255,.16);
  }

  .mobile-toc-sheet > header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 4px 2px 10px;
  }

  .mobile-toc-sheet > header > div {
    display: grid;
    gap: 2px;
  }

  .mobile-toc-sheet > header small {
    color: #857871;
    font-size: 9px;
  }

  .mobile-toc-sheet > header strong {
    font-size: 18px;
  }

  .mobile-toc-sheet > header button {
    width: 42px;
    height: 42px;
    border: 1px solid rgba(255,255,255,.08);
    border-radius: 12px;
    background: rgba(255,255,255,.025);
    color: #b9aaa3;
    font-size: 22px;
    cursor: pointer;
  }

  .mobile-toc-progress {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 8px 2px;
    border-top: 1px solid rgba(255,255,255,.05);
    border-bottom: 1px solid rgba(255,255,255,.05);
    color: #8d807a;
    font-size: 10px;
  }

  .mobile-toc-progress b {
    color: #c6a46f;
  }

  .mobile-toc-sheet nav {
    min-height: 0;
    display: grid;
    align-content: start;
    gap: 3px;
    padding-top: 8px;
    overflow: auto;
    overscroll-behavior: contain;
  }

  .mobile-toc-item {
    min-height: 46px;
    display: grid;
    grid-template-columns: 26px minmax(0,1fr);
    align-items: center;
    gap: 8px;
    padding: 8px 10px;
    border: 0;
    border-radius: 10px;
    background: transparent;
    color: #b8aaa3;
    text-align: left;
    cursor: pointer;
  }

  .mobile-toc-item.level-2 {
    padding-left: 18px;
  }

  .mobile-toc-item.level-3 {
    padding-left: 28px;
  }

  .mobile-toc-item.is-active {
    background: rgba(var(--accent-rgb),.095);
    color: #f0b4ac;
    box-shadow: inset 3px 0 0 rgba(var(--accent-rgb),.72);
  }

  .mobile-toc-item strong {
    min-width: 0;
    font-size: 12px;
    line-height: 1.45;
  }
}

@media (max-width: 620px) {
  .recent-viewed {
    padding: 14px;
  }

  .recent-viewed-head > small {
    display: none;
  }

  .recent-viewed-list {
    grid-template-columns: 1fr;
    gap: 5px;
  }

  .recent-viewed-card {
    min-height: 46px;
  }

  .directory-drafts > summary small {
    display: none;
  }

  .recent-update-date {
    flex-wrap: wrap;
  }
}

html[data-theme="light"] .directory-card.is-brief,
html[data-theme="light"] .recent-viewed,
html[data-theme="light"] .recent-viewed-card {
  border-color: rgba(118,84,55,.12);
  background: rgba(255,255,255,.42);
}

html[data-theme="light"] .mobile-toc-sheet {
  border-color: rgba(118,84,55,.16);
  background: rgba(250,246,239,.99);
  color: #3c2e29;
}

html[data-theme="light"] .mobile-toc-item {
  color: #66564f;
}

html[data-theme="light"] .mobile-toc-item.is-active {
  background: rgba(184,61,52,.075);
  color: #8e312b;
}

@media (prefers-reduced-motion: reduce) {
  .search-loading-row > *::after {
    animation: none;
  }
}


.search-brief-badge {
  padding: 2px 6px;
  border: 1px solid rgba(var(--gold-rgb),.2);
  border-radius: 999px;
  background: rgba(var(--gold-rgb),.055);
  color: #c7a169;
  font-size: 9px;
  font-style: normal;
  font-weight: 800;
}

.brief-notice {
  width: min(100%, var(--content-max));
  margin: 0 auto;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  border: 1px solid rgba(var(--gold-rgb),.17);
  border-radius: 14px;
  background: rgba(var(--gold-rgb),.028);
}

.brief-notice > span {
  padding: 4px 8px;
  border-radius: 999px;
  background: rgba(var(--gold-rgb),.08);
  color: #c9a56e;
  font-size: 10px;
  font-weight: 850;
}

.brief-notice > div {
  display: grid;
  gap: 3px;
}

.brief-notice strong {
  font-size: 13px;
}

.brief-notice small {
  color: #8e817b;
  font-size: 11px;
}

@media (max-width: 620px) {
  .search-brief-badge {
    font-size: 10px;
  }

  .brief-notice {
    grid-template-columns: 1fr;
    gap: 8px;
  }
}

html[data-theme="light"] .brief-notice {
  border-color: rgba(149,107,47,.15);
  background: rgba(149,107,47,.035);
}


/* === Remaining reader polish === */
.search-empty-state {
  display: grid;
  justify-items: center;
  gap: 12px;
  padding: 20px 10px 10px;
}

.search-empty-state .search-empty {
  margin: 0;
}

.search-fallback {
  width: min(100%, 620px);
  display: grid;
  gap: 8px;
}

.search-fallback > span {
  color: #81736d;
  font-size: 10px;
  text-align: center;
}

.search-fallback > div {
  display: grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  gap: 7px;
}

.search-fallback a {
  min-width: 0;
  min-height: 48px;
  display: grid;
  grid-template-columns: 24px minmax(0,1fr) 14px;
  align-items: center;
  gap: 7px;
  padding: 9px 10px;
  border: 1px solid rgba(var(--gold-rgb),.11);
  border-radius: 10px;
  background: rgba(var(--gold-rgb),.025);
  color: #bca99e;
  text-decoration: none;
}

.search-fallback a:hover,
.search-fallback a:focus-visible {
  border-color: rgba(var(--gold-rgb),.24);
  background: rgba(var(--gold-rgb),.055);
  color: #e2c795;
}

.search-fallback a strong {
  min-width: 0;
  overflow: hidden;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.search-fallback a b {
  color: #786b65;
  font-size: 10px;
}

.status-content-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  overflow: hidden;
  border: 1px solid rgba(255,255,255,.06);
  border-radius: 15px;
  background: rgba(15,20,28,.66);
}

.status-content-metrics article {
  min-height: 96px;
  display: grid;
  align-content: center;
  gap: 4px;
  padding: 16px;
}

.status-content-metrics article + article {
  border-left: 1px solid rgba(255,255,255,.055);
}

.status-content-metrics small {
  color: #80736d;
  font-size: 9px;
}

.status-content-metrics strong {
  font-size: 19px;
}

.status-content-metrics span {
  color: #8c7f78;
  font-size: 10px;
}

.status-content-metrics article[data-status="detailed"] strong {
  color: #79b68a;
}

.status-content-metrics article[data-status="brief"] strong {
  color: #d1aa6b;
}

.status-content-metrics article[data-status="draft"] strong {
  color: #9b8d87;
}

@media (max-width: 760px) {
  .status-content-metrics,
  .search-fallback > div {
    grid-template-columns: 1fr;
  }

  .status-content-metrics article + article {
    border-left: 0;
    border-top: 1px solid rgba(255,255,255,.055);
  }
}

html[data-theme="light"] .search-fallback a,
html[data-theme="light"] .status-content-metrics {
  border-color: rgba(118,84,55,.13);
  background: rgba(255,250,243,.7);
}

html[data-theme="light"] .status-content-metrics article + article {
  border-color: rgba(118,84,55,.1);
}


/* === Stable heading links and compact article layout === */
.notion-page-content :is(h1, h2, h3)[data-wiki-heading="true"] {
  scroll-margin-top: calc(var(--topbar) + 24px);
}

.heading-anchor-copy {
  min-width: 28px;
  min-height: 28px;
  margin-left: 8px;
  padding: 0 6px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--text-faint);
  font-size: .62em;
  font-weight: 800;
  line-height: 1;
  vertical-align: middle;
  opacity: 0;
  cursor: pointer;
  transition: opacity .14s ease, color .14s ease, background .14s ease;
}

.notion-page-content :is(h1, h2, h3):hover > .heading-anchor-copy,
.heading-anchor-copy:focus-visible,
.heading-anchor-copy[data-copied="true"] {
  opacity: 1;
}

.heading-anchor-copy:hover,
.heading-anchor-copy[data-copied="true"] {
  background: rgba(var(--gold-rgb),.08);
  color: var(--gold);
}

:where(
  .directory-heading > div > span,
  .directory-copy small,
  .recent-update-date,
  .recent-update-date > small,
  .page-updated,
  .page-siblings small,
  .brief-notice small,
  .draft-notice small,
  .search-fallback > span,
  .recent-viewed-head > small,
  .status-services small,
  .status-services span,
  .status-content-metrics small,
  .status-content-metrics span
) {
  color: var(--text-subtle);
}

:where(
  .directory-title-row em,
  .search-result-category,
  .search-draft-badge,
  .search-brief-badge,
  .nav-section-label,
  .sidebar-category-head strong,
  .recent-viewed-head p,
  .recent-update-date > small,
  .status-content-metrics small
) {
  font-size: max(10px, .625rem);
}

:where(
  .directory-copy small,
  .brief-notice small,
  .draft-notice small,
  .page-siblings small,
  .status-services small,
  .status-services span,
  .status-content-metrics span
) {
  font-size: max(11px, .6875rem);
  line-height: 1.5;
}

.wiki-shell[data-content-status="brief"] .wiki-main {
  gap: 14px;
}

.wiki-shell[data-content-status="brief"] .wiki-hero.is-article {
  padding: 12px 20px;
  border-radius: 14px;
}

.wiki-shell[data-content-status="brief"] .wiki-hero.is-article .hero-kicker {
  margin-bottom: 4px;
}

.wiki-shell[data-content-status="brief"] .wiki-hero.is-article .hero-copy h1 {
  font-size: clamp(24px, 2.7vw, 31px);
}

.wiki-shell[data-content-status="brief"] .brief-notice {
  padding-block: 11px;
}

.wiki-shell[data-content-status="brief"] .document-card .notion-page {
  padding-top: 24px !important;
  padding-bottom: 44px !important;
}

.wiki-shell[data-content-status="brief"] .document-card .notion-h1 {
  margin-top: 1.55em !important;
}

.wiki-shell[data-content-status="brief"] .document-card .notion-h2 {
  margin-top: 1.4em !important;
}

@media (max-width: 620px) {
  .heading-anchor-copy {
    min-width: 32px;
    min-height: 32px;
    margin-left: 4px;
    opacity: .55;
  }

  .wiki-shell[data-content-status="brief"] .wiki-hero.is-article {
    padding: 11px 14px;
  }

  .wiki-shell[data-content-status="brief"] .document-card .notion-page {
    padding-top: 18px !important;
    padding-bottom: 36px !important;
  }
}


/* === Sidebar interaction and stable recent history === */
.sidebar-category-head-toggle {
  display: none;
}

.recent-viewed {
  min-height: 116px;
}

.recent-viewed-actions {
  display: flex;
  align-items: center;
  gap: 9px;
}

.recent-viewed-actions > small {
  color: var(--text-subtle);
  font-size: 10px;
}

.recent-viewed-actions > button {
  min-height: 32px;
  padding: 0 9px;
  border: 1px solid rgba(var(--gold-rgb),.13);
  border-radius: 8px;
  background: transparent;
  color: var(--text-faint);
  font-size: 10px;
  cursor: pointer;
}

.recent-viewed-actions > button:hover,
.recent-viewed-actions > button:focus-visible {
  border-color: rgba(var(--gold-rgb),.25);
  color: var(--gold);
  background: rgba(var(--gold-rgb),.045);
}

.recent-viewed-empty {
  min-height: 48px;
  display: flex;
  align-items: center;
  margin: 0;
  padding: 9px 10px;
  border: 1px dashed rgba(var(--gold-rgb),.11);
  border-radius: 11px;
  color: var(--text-subtle);
  font-size: 11px;
  line-height: 1.55;
}

.recent-viewed-loading {
  grid-template-columns: repeat(3, minmax(0,1fr));
}

.recent-viewed-skeleton {
  min-height: 48px;
  overflow: hidden;
  position: relative;
  border-radius: 11px;
  background: rgba(255,255,255,.035);
}

.recent-viewed-skeleton::after {
  content: "";
  position: absolute;
  inset: 0;
  transform: translateX(-100%);
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255,255,255,.055),
    transparent
  );
  animation: wikiSkeleton 1.4s ease-in-out infinite;
}

@media (max-width: 980px) {
  .sidebar-category-head-static {
    display: none;
  }

  .sidebar-category-head-toggle {
    display: flex;
  }
}

@media (max-width: 620px) {
  .recent-viewed {
    min-height: 124px;
  }

  .recent-viewed-head {
    align-items: flex-start;
  }

  .recent-viewed-actions > small {
    display: none;
  }

  .recent-viewed-loading {
    grid-template-columns: 1fr;
  }

  .recent-viewed-loading .recent-viewed-skeleton:nth-child(n + 2) {
    display: none;
  }
}

html[data-theme="light"] .recent-viewed-actions > button,
html[data-theme="light"] .recent-viewed-empty {
  border-color: rgba(118,84,55,.13);
}

@media (prefers-reduced-motion: reduce) {
  .recent-viewed-skeleton::after {
    animation: none;
  }
}


/* === Document feedback === */
.document-feedback {
  width: min(100%, var(--content-max));
  margin: 0 auto;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(360px, .9fr);
  gap: 18px;
  align-items: center;
  padding: 18px 20px;
  border: 1px solid var(--border-soft);
  border-radius: 16px;
  background: var(--surface-soft);
}

.document-feedback > div:first-child {
  display: grid;
  gap: 4px;
}

.document-feedback p {
  margin: 0;
  color: var(--gold);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: .11em;
}

.document-feedback h2 {
  margin: 0;
  font-size: 17px;
}

.document-feedback > div:first-child > span {
  color: var(--text-subtle);
  font-size: 11px;
  line-height: 1.55;
}

.document-feedback-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0,1fr));
  gap: 8px;
}

.document-feedback-actions a {
  min-width: 0;
  min-height: 66px;
  display: grid;
  grid-template-columns: minmax(0,1fr) 16px;
  grid-template-rows: auto auto;
  column-gap: 8px;
  align-content: center;
  padding: 10px 12px;
  border: 1px solid rgba(var(--gold-rgb),.12);
  border-radius: 11px;
  background: rgba(var(--gold-rgb),.025);
  color: inherit;
  text-decoration: none;
}

.document-feedback-actions a:hover,
.document-feedback-actions a:focus-visible {
  border-color: rgba(var(--gold-rgb),.24);
  background: rgba(var(--gold-rgb),.05);
}

.document-feedback-actions strong {
  grid-column: 1;
  font-size: 12px;
}

.document-feedback-actions small {
  grid-column: 1;
  color: var(--text-subtle);
  font-size: 10px;
  line-height: 1.45;
}

.document-feedback-actions b {
  grid-column: 2;
  grid-row: 1 / 3;
  align-self: center;
  color: var(--gold);
  font-size: 11px;
}

@media (max-width: 760px) {
  .document-feedback {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 520px) {
  .document-feedback {
    padding: 14px;
  }

  .document-feedback-actions {
    grid-template-columns: 1fr;
  }
}


/* === UX pass: draft states, sidebar maturity and actionable hero badges === */
.hero-badge-link {
  color: inherit;
  text-decoration: none;
  cursor: pointer;
  transition: border-color .16s ease, background .16s ease, transform .16s ease;
}

.hero-badge-link:hover,
.hero-badge-link:focus-visible {
  transform: translateY(-1px);
  border-color: rgba(var(--gold-rgb), .3);
  background: rgba(var(--gold-rgb), .11);
  outline: none;
}

.global-page-link.is-draft {
  opacity: .72;
}

.global-page-link.is-draft:hover,
.global-page-link.is-draft:focus-visible {
  opacity: .92;
}

.global-page-link.is-draft .sidebar-page-icon {
  filter: saturate(.55);
}

.global-page-copy {
  min-width: 0;
}

.sidebar-draft-badge {
  width: fit-content;
  margin-top: 2px;
  padding: 1px 5px;
  border: 1px solid rgba(160,147,140,.16);
  border-radius: 999px;
  color: var(--text-subtle);
  font-size: 9px;
  font-style: normal;
  font-weight: 800;
  line-height: 1.4;
}

.draft-state {
  width: min(100%, var(--content-max));
  min-height: 280px;
  margin: 0 auto;
  display: grid;
  justify-items: center;
  align-content: center;
  gap: 8px;
  padding: 34px 24px;
  border: 1px dashed rgba(var(--gold-rgb), .18);
  border-radius: 18px;
  background:
    radial-gradient(circle at 50% 0%, rgba(var(--gold-rgb), .07), transparent 42%),
    var(--surface-soft);
  text-align: center;
}

.draft-state-icon {
  width: 58px;
  height: 58px;
  display: grid;
  place-items: center;
  margin-bottom: 4px;
  border: 1px solid rgba(var(--gold-rgb), .16);
  border-radius: 18px;
  background: rgba(var(--gold-rgb), .05);
  font-size: 27px;
}

.draft-state > p {
  margin: 0;
  color: var(--gold);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: .12em;
}

.draft-state > h2 {
  margin: 0;
  font-size: clamp(20px, 2.4vw, 27px);
}

.draft-state > span {
  max-width: 620px;
  color: var(--text-subtle);
  font-size: 12px;
  line-height: 1.7;
}

.draft-state .state-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin-top: 10px;
}

.draft-state .state-actions a {
  min-height: 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 13px;
  border: 1px solid rgba(var(--gold-rgb), .16);
  border-radius: 10px;
  background: rgba(var(--gold-rgb), .035);
  color: inherit;
  font-size: 11px;
  font-weight: 800;
  text-decoration: none;
}

.draft-state .state-actions a:hover,
.draft-state .state-actions a:focus-visible {
  border-color: rgba(var(--gold-rgb), .28);
  background: rgba(var(--gold-rgb), .07);
}

html[data-theme="light"] .draft-state {
  border-color: rgba(118,84,55,.16);
  background:
    radial-gradient(circle at 50% 0%, rgba(149,107,47,.07), transparent 42%),
    rgba(255,250,243,.7);
}

@media (max-width: 620px) {
  .draft-state {
    min-height: 240px;
    padding: 28px 16px;
  }

  .draft-state .state-actions {
    width: 100%;
    display: grid;
  }

  .draft-state .state-actions a {
    width: 100%;
  }

  .sidebar-draft-badge {
    font-size: 10px;
  }
}


/* === Home information hierarchy === */
.wiki-main.is-home-main > .wiki-hero {
  order: 0;
}

.wiki-main.is-home-main > .recent-viewed {
  order: 1;
}

.wiki-main.is-home-main > .starter-guide {
  order: 2;
}

.wiki-main.is-home-main > .wiki-directory {
  order: 3;
}

.wiki-main.is-home-main > .recent-updates {
  order: 4;
}

.wiki-main.is-home-main > .home-playground {
  order: 5;
}

.wiki-main.is-home-main > .wiki-footer {
  order: 10;
}


/* === Wiki Play Zone === */
.wiki-fun-zone {
  width: min(100%, var(--content-max));
  margin: 0 auto;
  padding: 24px;
  border: 1px solid rgba(var(--gold-rgb),.12);
  border-radius: 20px;
  background:
    radial-gradient(circle at 12% 0%, rgba(var(--accent-rgb),.09), transparent 32%),
    radial-gradient(circle at 88% 0%, rgba(var(--gold-rgb),.08), transparent 28%),
    rgba(16,14,15,.9);
  box-shadow: 0 18px 56px rgba(0,0,0,.16);
}

.fun-zone-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 18px;
}

.fun-zone-head > div {
  min-width: 0;
}

.fun-zone-head p,
.fun-modal-kicker {
  margin: 0 0 5px;
  color: #c69755;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .14em;
}

.fun-zone-head h2,
.fun-modal-content > h2 {
  margin: 0;
  color: #f2e8e3;
  font-size: 21px;
  letter-spacing: -.025em;
}

.fun-zone-head span {
  display: block;
  margin-top: 6px;
  color: #8f817b;
  font-size: 11px;
  line-height: 1.55;
}

.fun-zone-head > strong {
  flex: 0 0 auto;
  padding: 6px 9px;
  border: 1px solid rgba(var(--gold-rgb),.15);
  border-radius: 999px;
  color: #aa906b;
  font-size: 9px;
  letter-spacing: .09em;
}

.fun-zone-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  gap: 11px;
}

.fun-card {
  position: relative;
  min-width: 0;
  min-height: 162px;
  display: grid;
  grid-template-columns: 48px minmax(0,1fr);
  grid-template-rows: 1fr auto;
  align-items: start;
  gap: 12px;
  padding: 17px;
  overflow: hidden;
  border: 1px solid rgba(255,255,255,.06);
  border-radius: 17px;
  background: rgba(255,255,255,.02);
  color: inherit;
  text-align: left;
  cursor: pointer;
  box-shadow: 0 8px 24px rgba(0,0,0,.09);
  transition:
    transform .18s ease,
    border-color .18s ease,
    background .18s ease,
    box-shadow .18s ease;
}

.fun-card::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: .62;
}

.fun-card.is-fortune::before {
  background: radial-gradient(circle at 0% 0%, rgba(126,86,174,.18), transparent 48%);
}

.fun-card.is-quiz::before {
  background: radial-gradient(circle at 0% 0%, rgba(var(--accent-rgb),.15), transparent 48%);
}

.fun-card.is-progress::before {
  background: radial-gradient(circle at 0% 0%, rgba(var(--gold-rgb),.15), transparent 48%);
}

.fun-card:hover {
  transform: translateY(-2px);
  border-color: rgba(var(--gold-rgb),.23);
  background: rgba(255,255,255,.032);
  box-shadow: 0 13px 30px rgba(0,0,0,.14);
}

.fun-card:focus-visible,
.fun-modal button:focus-visible,
.exploration-list a:focus-visible {
  outline: 2px solid rgba(var(--gold-rgb),.68);
  outline-offset: 2px;
}

.fun-card-icon {
  position: relative;
  z-index: 1;
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(var(--gold-rgb),.11);
  border-radius: 14px;
  background: rgba(255,255,255,.035);
  font-size: 23px;
}

.fun-card-copy {
  position: relative;
  z-index: 1;
  min-width: 0;
  display: grid;
  align-content: start;
  gap: 4px;
}

.fun-card-copy > small {
  color: #a18461;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: .04em;
}

.fun-card-copy > strong {
  color: #f2e8e3;
  font-size: 15px;
}

.fun-card-copy > em {
  color: #93857f;
  font-size: 11px;
  font-style: normal;
  line-height: 1.55;
}

.fun-card-action {
  position: relative;
  z-index: 1;
  grid-column: 1 / -1;
  align-self: end;
  color: #bda37c;
  font-size: 10px;
  font-weight: 800;
}

.fun-progress-track,
.quiz-progress-track {
  display: block;
  height: 5px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255,255,255,.055);
}

.fun-progress-track {
  margin-top: 7px;
}

.fun-progress-track > span,
.quiz-progress-track > span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #c69755, #d85d51);
  transition: width .3s ease;
}

.fun-modal-backdrop {
  position: fixed;
  z-index: 90;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 22px;
  background: rgba(4,4,5,.72);
  backdrop-filter: blur(10px);
  animation: funBackdropIn .16s ease-out;
}

.fun-modal {
  position: relative;
  width: min(100%, 620px);
  max-height: min(88vh, 780px);
  overflow: auto;
  overscroll-behavior: contain;
  border: 1px solid rgba(var(--gold-rgb),.18);
  border-radius: 22px;
  background:
    radial-gradient(circle at 85% 0%, rgba(var(--accent-rgb),.12), transparent 35%),
    radial-gradient(circle at 10% 0%, rgba(var(--gold-rgb),.08), transparent 32%),
    #111012;
  box-shadow: 0 28px 90px rgba(0,0,0,.48);
  animation: funModalIn .2s cubic-bezier(.2,.78,.25,1);
}

.fun-modal-content {
  padding: 30px;
}

.fun-modal-close {
  position: sticky;
  z-index: 2;
  top: 12px;
  float: right;
  width: 36px;
  height: 36px;
  margin: 12px 12px -48px 0;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 50%;
  background: rgba(15,14,15,.86);
  color: #b6aaa4;
  font-size: 22px;
  line-height: 1;
  cursor: pointer;
  backdrop-filter: blur(10px);
}

.fun-modal-close:hover {
  color: #fff;
  border-color: rgba(var(--gold-rgb),.24);
}

.fortune-ready,
.fortune-result,
.quiz-result {
  margin-top: 24px;
  display: grid;
  justify-items: center;
  text-align: center;
}

.fortune-ready > span,
.fortune-result-icon,
.quiz-result-icon {
  width: 82px;
  height: 82px;
  display: grid;
  place-items: center;
  margin-bottom: 14px;
  border: 1px solid rgba(var(--gold-rgb),.16);
  border-radius: 24px;
  background:
    radial-gradient(circle at 32% 26%, rgba(var(--accent-rgb),.18), transparent 45%),
    rgba(var(--gold-rgb),.05);
  box-shadow:
    inset 0 0 22px rgba(var(--gold-rgb),.04),
    0 15px 40px rgba(0,0,0,.16);
  font-size: 38px;
}

.fortune-ready > strong {
  color: #f1e5df;
  font-size: 17px;
}

.fortune-ready > small {
  max-width: 430px;
  margin-top: 8px;
  color: #8f817b;
  font-size: 11px;
  line-height: 1.6;
}

.fortune-ready > button {
  min-height: 44px;
  margin-top: 19px;
  padding: 0 18px;
  border: 1px solid rgba(var(--accent-rgb),.34);
  border-radius: 12px;
  background: rgba(var(--accent-rgb),.13);
  color: #f2b2aa;
  font-weight: 850;
  cursor: pointer;
}

.fortune-result > p,
.quiz-result > p {
  margin: 0 0 6px;
  color: #ad8957;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: .08em;
}

.fortune-result > h3,
.quiz-result > h3 {
  margin: 0;
  color: #fff0ea;
  font-size: 26px;
  letter-spacing: -.03em;
}

.fortune-result > strong,
.quiz-result > strong {
  max-width: 470px;
  margin-top: 10px;
  color: #d9cbc4;
  font-size: 13px;
  line-height: 1.65;
}

.fortune-result > small {
  max-width: 470px;
  margin-top: 13px;
  padding: 12px 14px;
  border: 1px solid rgba(var(--gold-rgb),.1);
  border-radius: 12px;
  background: rgba(var(--gold-rgb),.035);
  color: #a99578;
  font-size: 11px;
  line-height: 1.55;
}

.quiz-result > span:not(.quiz-result-icon) {
  max-width: 480px;
  margin-top: 12px;
  color: #9b8d87;
  font-size: 12px;
  line-height: 1.7;
}

.quiz-result > small {
  margin-top: 14px;
  padding: 6px 9px;
  border-radius: 999px;
  background: rgba(var(--gold-rgb),.06);
  color: #b79b71;
  font-size: 10px;
}

.fun-result-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 19px;
}

.fun-result-actions button {
  min-height: 40px;
  padding: 0 14px;
  border: 1px solid rgba(var(--gold-rgb),.14);
  border-radius: 10px;
  background: rgba(var(--gold-rgb),.055);
  color: #c6ae89;
  font-weight: 800;
  cursor: pointer;
}

.fun-result-actions button:first-child {
  border-color: rgba(var(--accent-rgb),.2);
  background: rgba(var(--accent-rgb),.08);
  color: #e39289;
}

.fun-result-actions > span {
  width: 100%;
  color: #8e817b;
  font-size: 10px;
}

.quiz-progress-row {
  margin-top: 24px;
  display: grid;
  grid-template-columns: 42px minmax(0,1fr);
  align-items: center;
  gap: 10px;
}

.quiz-progress-row > span:first-child {
  color: #a89270;
  font-size: 10px;
  font-weight: 850;
}

.quiz-question {
  margin-top: 22px;
}

.quiz-question > h3 {
  margin: 0 0 16px;
  color: #f0e5df;
  font-size: 19px;
  line-height: 1.45;
}

.quiz-answers {
  display: grid;
  gap: 8px;
}

.quiz-answers button {
  min-height: 52px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 0 15px;
  border: 1px solid rgba(255,255,255,.065);
  border-radius: 12px;
  background: rgba(255,255,255,.02);
  color: #cfc2bc;
  text-align: left;
  cursor: pointer;
  transition: border-color .16s ease, background .16s ease, transform .16s ease;
}

.quiz-answers button:hover {
  transform: translateX(2px);
  border-color: rgba(var(--gold-rgb),.2);
  background: rgba(var(--gold-rgb),.045);
  color: #f0e2db;
}

.quiz-answers button span {
  color: #997e5c;
}

.exploration-summary {
  margin-top: 22px;
  display: grid;
  grid-template-columns: 92px minmax(0,1fr);
  align-items: center;
  gap: 17px;
  padding: 16px;
  border: 1px solid rgba(var(--gold-rgb),.11);
  border-radius: 15px;
  background: rgba(var(--gold-rgb),.035);
}

.exploration-summary > div {
  display: grid;
  justify-items: center;
}

.exploration-summary > div strong {
  color: #dfb973;
  font-size: 29px;
  line-height: 1;
}

.exploration-summary > div small {
  margin-top: 5px;
  color: #8e817b;
  font-size: 9px;
}

.exploration-summary > p {
  margin: 0;
  color: #9d8f89;
  font-size: 12px;
  line-height: 1.65;
}

.exploration-summary > p strong {
  color: #ded0c8;
}

.exploration-list {
  margin-top: 13px;
  display: grid;
  grid-template-columns: repeat(2, minmax(0,1fr));
  gap: 7px;
}

.exploration-list a {
  min-width: 0;
  min-height: 48px;
  display: grid;
  grid-template-columns: 24px minmax(0,1fr) auto;
  align-items: center;
  gap: 7px;
  padding: 8px 10px;
  border: 1px solid rgba(255,255,255,.055);
  border-radius: 11px;
  background: rgba(255,255,255,.018);
  color: #aa9c95;
  text-decoration: none;
}

.exploration-list a:hover {
  border-color: rgba(var(--gold-rgb),.18);
  background: rgba(var(--gold-rgb),.035);
}

.exploration-list a.is-visited {
  border-color: rgba(111,185,131,.13);
  background: rgba(111,185,131,.035);
}

.exploration-list a > span {
