  font-size: 11px;
  line-height: 1.55;
  text-align: center;
}

@keyframes funBackdropIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes funModalIn {
  from { opacity: 0; transform: translateY(8px) scale(.985); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

html[data-theme="light"] .wiki-fun-zone {
