}

@media (max-width: 900px) {
  .fun-zone-grid {
    grid-template-columns: 1fr;
  }

  .fun-card {
    min-height: 116px;
    grid-template-columns: 44px minmax(0,1fr) auto;
    grid-template-rows: 1fr;
    align-items: center;
  }

  .fun-card-icon {
    width: 44px;
    height: 44px;
    font-size: 21px;
  }

  .fun-card-action {
    grid-column: 3;
    align-self: center;
    white-space: nowrap;
  }

  .fun-progress-track {
