    border-radius: 17px;
  }

  .fun-zone-head {
    align-items: flex-start;
    margin-bottom: 12px;
  }

  .fun-zone-head h2 {
    font-size: 18px;
  }

  .fun-zone-head > strong {
    display: none;
  }

  .fun-card {
    min-height: 104px;
