  }

  .fun-card-icon {
    width: 42px;
    height: 42px;
    border-radius: 12px;
  }

  .fun-card-copy > strong {
    font-size: 14px;
  }

  .fun-card-copy > em {
    font-size: 10px;
  }

  .fun-card-action {
    grid-column: 1 / -1;
