    font-size: 9px;
  }

  .fun-modal-backdrop {
    align-items: end;
    padding: 0;
  }

  .fun-modal {
    width: 100%;
    max-height: 91dvh;
    border-radius: 21px 21px 0 0;
    border-bottom: 0;
  }

  .fun-modal-content {
    padding: 25px 16px 28px;
  }

  .fun-modal-close {
    top: 9px;
    margin: 9px 9px -45px 0;
  }

  .fortune-ready > span,
  .fortune-result-icon,
  .quiz-result-icon {
    width: 72px;
    height: 72px;
    border-radius: 21px;
    font-size: 33px;
  }

  .fortune-result > h3,
  .quiz-result > h3 {
