  color: #7c706b;
  font-size: 8px;
  font-weight: 850;
}

.survival-panel > header > b.is-complete {
  background: rgba(111,185,131,.08);
  color: #7fc091;
}

.mission-list {
  display: grid;
  gap: 7px;
}

.mission-list > div {
  min-height: 54px;
  display: grid;
  grid-template-columns: 32px minmax(0,1fr) auto;
  align-items: center;
  gap: 9px;
  padding: 8px 9px;
  border: 1px solid rgba(255,255,255,.045);
  border-radius: 11px;
  background: rgba(255,255,255,.012);
}

.mission-list > div.is-done {
  border-color: rgba(111,185,131,.12);
  background: rgba(111,185,131,.025);
}

.mission-list > div > span {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: rgba(var(--gold-rgb),.045);
  font-size: 16px;
}

.mission-list > div > div {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.mission-list strong {
  color: #cec2bc;
  font-size: 10px;
}

.mission-list small {
  color: #746964;
  font-size: 8px;
  line-height: 1.45;
}

.mission-list > div > b {
  color: #887b75;
  font-size: 9px;
}

.mission-list > div.is-done > b {
  color: #78b58a;
}

.mission-list i {
  height: 3px;
