  background: rgba(255,255,255,.045);
}

.mission-list i > i {
  height: 100%;
  display: block;
  border-radius: inherit;
  background: linear-gradient(90deg,#78ad85,#c5a366);
}

.collection-list {
  display: grid;
  gap: 10px;
}

.collection-list > div {
  display: grid;
  gap: 5px;
}

.collection-list > div > span {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.collection-list strong {
  color: #cfc3bc;
  font-size: 10px;
}

.collection-list small {
  color: #776a64;
  font-size: 9px;
}

.collection-list i {
  height: 6px;
  display: block;
  overflow: hidden;
  border-radius: 99px;
  background: rgba(255,255,255,.045);
}

.collection-list i > i {
  height: 100%;
  display: block;
  border-radius: inherit;
  background: linear-gradient(90deg,#c49b5d,#d65d52);
}

.treasure-slots {
  display: grid;
  grid-template-columns: repeat(4,minmax(0,1fr));
  gap: 7px;
}

.treasure-slots > span {
  aspect-ratio: 1.25;
  display: grid;
  place-items: center;
  border: 1px dashed rgba(var(--gold-rgb),.11);
  border-radius: 11px;
  background: rgba(var(--gold-rgb),.018);
  color: #5f5551;
  font-size: 17px;
  font-weight: 900;
}

.treasure-slots > span.is-found {
  border-style: solid;
  border-color: rgba(var(--gold-rgb),.2);
  background:
    radial-gradient(circle at 50% 30%, rgba(var(--gold-rgb),.13), transparent 62%),
    rgba(var(--gold-rgb),.035);
  color: #ddba7b;
}

.treasure-panel > p {
  margin: 10px 0 0;
  color: #746964;
  font-size: 9px;
  line-height: 1.55;
}

.survival-tip {
  margin-top: 11px;
  display: grid;
  grid-template-columns: 34px minmax(0,1fr);
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border: 1px solid rgba(93,135,187,.1);
  border-radius: 12px;
  background: rgba(93,135,187,.025);
}

.survival-tip > span {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: rgba(93,135,187,.06);
}

.survival-tip > div {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.survival-tip small {
  color: #7890ad;
  font-size: 8px;
  font-weight: 850;
  letter-spacing: .08em;
}

.survival-tip strong {
  color: #aebdce;
  font-size: 10px;
  line-height: 1.5;
}

.random-roulette-wrap {
  position: relative;
  width: 190px;
  height: 190px;
  margin: 22px auto 12px;
  display: grid;
  place-items: center;
}

.random-roulette-pointer {
  position: absolute;
  z-index: 3;
  top: -8px;
  left: 50%;
  transform: translateX(-50%);
  color: #e7b766;
  font-size: 20px;
  filter: drop-shadow(0 3px 7px rgba(0,0,0,.35));
}

.random-roulette {
  position: relative;
  width: 172px;
  height: 172px;
  display: grid;
  place-items: center;
  border: 5px solid rgba(var(--gold-rgb),.2);
  border-radius: 50%;
  background:
    radial-gradient(circle at center, #1a1718 0 23%, transparent 24%),
    repeating-conic-gradient(
      from -22.5deg,
      rgba(198,151,85,.17) 0deg 45deg,
      rgba(111,75,121,.14) 45deg 90deg
    );
  box-shadow:
    inset 0 0 0 2px rgba(255,255,255,.035),
    0 14px 38px rgba(0,0,0,.2);
  transition: transform .92s cubic-bezier(.13,.69,.13,1);
}

.random-roulette::before {
  content: "";
  position: absolute;
  inset: 22px;
  border: 1px solid rgba(var(--gold-rgb),.11);
  border-radius: 50%;
}

.random-roulette > span {
  position: absolute;
  left: calc(50% - 11px);
  top: calc(50% - 11px);
  width: 22px;
  height: 22px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: rgba(14,12,13,.78);
  color: #ccb07f;
  font-size: 8px;
  font-weight: 900;
}

.random-roulette > b {
  position: relative;
  z-index: 2;
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(var(--gold-rgb),.18);
  border-radius: 50%;
  background: #171415;
  font-size: 19px;
}

.random-roulette.is-spinning > span,
.random-roulette.is-spinning > b {
  filter: blur(.15px);
}

.random-ready.is-roulette-ready,
.random-result.is-roulette-result {
  margin-top: 8px;
}

.random-ready.is-roulette-ready > span,
.random-result.is-roulette-result .random-result-dice {
  display: none;
}

.wiki-treasure-find {
  position: fixed;
  z-index: 34;
  right: 24px;
  bottom: 88px;
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(var(--gold-rgb),.1);
  border-radius: 50%;
  background: rgba(16,14,15,.72);
  color: rgba(221,186,123,.55);
  cursor: pointer;
  box-shadow: 0 8px 24px rgba(0,0,0,.15);
  backdrop-filter: blur(8px);
  animation: treasureGlint 2.8s ease-in-out infinite;
}

.wiki-treasure-find:hover,
.wiki-treasure-find:focus-visible {
  border-color: rgba(var(--gold-rgb),.28);
  color: #e8c37f;
  background: rgba(var(--gold-rgb),.07);
}

.wiki-treasure-toast,
.wiki-achievement-toast {
  position: fixed;
  z-index: 125;
  left: 50%;
  transform: translateX(-50%);
  border: 1px solid rgba(var(--gold-rgb),.2);
  background: rgba(17,14,15,.96);
  color: #dcc08d;
  box-shadow: 0 18px 50px rgba(0,0,0,.32);
  backdrop-filter: blur(12px);
}

.wiki-treasure-toast {
  bottom: max(24px,env(safe-area-inset-bottom));
  padding: 10px 14px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 850;
}

.wiki-achievement-toast {
  top: calc(var(--topbar) + 18px);
  min-width: min(90vw,320px);
  display: grid;
  grid-template-columns: 42px minmax(0,1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 11px 13px;
  border-radius: 14px;
  animation: achievementUnlockIn .34s cubic-bezier(.17,.8,.24,1);
  overflow: hidden;
}

.wiki-achievement-toast::after {
  content: "";
  position: absolute;
  inset: 0;
  transform: translateX(-130%);
  background: linear-gradient(110deg,transparent,rgba(255,255,255,.08),transparent);
  animation: achievementShine 1.25s ease .15s 1;
  pointer-events: none;
}

.wiki-achievement-toast > span {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: rgba(var(--gold-rgb),.08);
  font-size: 21px;
}

.wiki-achievement-toast > div {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.wiki-achievement-toast small {
  color: #9e835d;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .11em;
}

.wiki-achievement-toast strong {
  color: #ecd29e;
  font-size: 12px;
}

.wiki-achievement-toast > b {
  color: #e6bd73;
  font-size: 16px;
}

@keyframes treasureGlint {
  0%, 72%, 100% { transform: scale(1); box-shadow: 0 8px 24px rgba(0,0,0,.15); }
  82% { transform: scale(1.08); box-shadow: 0 0 18px rgba(220,180,105,.22); }
}

@keyframes achievementUnlockIn {
  from { opacity: 0; transform: translate(-50%,-12px) scale(.96); }
  to { opacity: 1; transform: translate(-50%,0) scale(1); }
}

@keyframes achievementShine {
  from { transform: translateX(-130%); }
  to { transform: translateX(130%); }
}

html[data-theme="light"] .wiki-survival-log {
  border-color: rgba(118,84,55,.12);
  background:
    radial-gradient(circle at 92% 0%, rgba(84,127,94,.055), transparent 30%),
    radial-gradient(circle at 6% 0%, rgba(149,107,47,.05), transparent 32%),
    rgba(255,250,243,.78);
}

html[data-theme="light"] .survival-log-head h2,
html[data-theme="light"] .survival-profile-metrics strong,
html[data-theme="light"] .survival-panel > header strong,
html[data-theme="light"] .mission-list strong,
html[data-theme="light"] .collection-list strong {
  color: #523a33;
}

html[data-theme="light"] .survival-profile-card,
html[data-theme="light"] .survival-panel {
  border-color: rgba(118,84,55,.1);
  background: rgba(255,255,255,.47);
}

html[data-theme="light"] .wiki-treasure-find {
  border-color: rgba(149,107,47,.13);
  background: rgba(255,250,243,.8);
  color: rgba(126,88,37,.62);
}

html[data-theme="light"] .wiki-treasure-toast,
html[data-theme="light"] .wiki-achievement-toast {
  border-color: rgba(149,107,47,.17);
  background: rgba(255,250,243,.97);
  color: #76562f;
  box-shadow: 0 16px 44px rgba(74,48,33,.16);
}

html[data-theme="light"] .wiki-achievement-toast strong {
  color: #6f4a1e;
}

@media (max-width: 900px) {
  .survival-profile-card {
    grid-template-columns: 1fr;
  }

  .survival-profile-card > button {
    width: 100%;
  }

  .survival-dashboard-grid {
    grid-template-columns: 1fr;
  }

  .survival-panel {
    min-height: 0;
  }
}

@media (max-width: 620px) {
  .wiki-survival-log {
    padding: 15px;
    border-radius: 17px;
  }

  .survival-log-head {
    align-items: flex-start;
    margin-bottom: 12px;
  }

  .survival-log-head h2 {
    font-size: 18px;
  }

  .survival-log-head > div > span {
    font-size: 10px;
  }

  .survival-streak-badge {
    padding: 5px 7px;
    font-size: 8px;
  }

  .survival-profile-card {
    padding: 13px;
    gap: 12px;
  }

  .survival-profile-title > strong {
    font-size: 19px;
  }

  .survival-profile-metrics {
    grid-template-columns: repeat(2,minmax(0,1fr));
  }

  .survival-profile-metrics > div:nth-child(3) {
    border-left: 0;
    border-top: 1px solid rgba(255,255,255,.045);
  }

  .survival-profile-metrics > div:nth-child(4) {
    border-top: 1px solid rgba(255,255,255,.045);
  }

  .survival-panel {
    padding: 12px;
  }

  .treasure-slots {
    grid-template-columns: repeat(4,minmax(0,1fr));
  }

  .random-roulette-wrap {
    width: 176px;
    height: 176px;
  }

  .random-roulette {
    width: 160px;
    height: 160px;
  }

  .random-roulette > span {
    transform-origin: 11px 11px;
  }

  .wiki-treasure-find {
    right: 14px;
    bottom: 72px;
    width: 32px;
    height: 32px;
  }

  .wiki-achievement-toast {
    top: calc(var(--topbar) + 10px);
    min-width: min(92vw,320px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .wiki-treasure-find,
  .wiki-achievement-toast,
  .wiki-achievement-toast::after {
    animation: none;
  }

  .random-roulette {
    transition: none;
  }
}


/* === Reading-driven exploration loop === */
.wiki-reading-explorer,
.reading-quiz-card,
.next-exploration {
  width: min(100%, var(--content-max));
  margin: 0 auto;
  border: 1px solid rgba(255,255,255,.055);
  border-radius: 20px;
  background: rgba(16,14,15,.88);
  box-shadow: 0 14px 40px rgba(0,0,0,.13);
}

.wiki-reading-explorer {
  padding: 24px;
  background:
    radial-gradient(circle at 8% 0%, rgba(94,131,177,.08), transparent 30%),
    radial-gradient(circle at 92% 0%, rgba(112,161,121,.07), transparent 30%),
    rgba(16,14,15,.88);
}

.reading-explorer-head,
.next-exploration-head,
.reading-quiz-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 16px;
}

.reading-explorer-head {
  margin-bottom: 16px;
}

.reading-explorer-head p,
.next-exploration-head p,
.reading-quiz-head p {
  margin: 0 0 5px;
  color: #7d9fc2;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .14em;
}

.reading-explorer-head h2,
.next-exploration-head h2,
.reading-quiz-head h2 {
  margin: 0;
  color: #f0e7e2;
  font-size: 20px;
  letter-spacing: -.025em;
}

.reading-explorer-head > div > span,
.next-exploration-head > div > span,
.reading-quiz-head > div > span {
  display: block;
  margin-top: 6px;
  color: #897d77;
  font-size: 10px;
  line-height: 1.55;
}

.reading-explorer-head > b,
.reading-quiz-head > b {
  flex: 0 0 auto;
  padding: 6px 9px;
  border: 1px solid rgba(106,151,190,.14);
  border-radius: 999px;
  background: rgba(106,151,190,.045);
  color: #91abc5;
  font-size: 9px;
}

.reading-explorer-top {
  display: grid;
  grid-template-columns: minmax(0,1.25fr) minmax(280px,.75fr);
  gap: 10px;
}

.reading-daily-quest,
.reading-unread-card,
.reading-collection-sets > article,
.reading-map {
  border: 1px solid rgba(255,255,255,.05);
  border-radius: 15px;
  background: rgba(255,255,255,.014);
}

.reading-daily-quest,
.reading-unread-card {
  padding: 15px;
}

.reading-daily-quest.is-complete {
  border-color: rgba(112,178,128,.15);
  background: rgba(112,178,128,.025);
}

.reading-daily-quest > header {
  display: grid;
  grid-template-columns: 40px minmax(0,1fr) auto;
  align-items: start;
  gap: 10px;
  margin-bottom: 11px;
}

.reading-daily-quest > header > span {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(126,161,196,.12);
  border-radius: 11px;
  background: rgba(126,161,196,.045);
  font-size: 20px;
}

.reading-daily-quest header small,
.reading-unread-card header small,
.reading-map header small,
.reading-collection-sets small {
  color: #758da6;
  font-size: 8px;
  font-weight: 850;
  letter-spacing: .08em;
}

.reading-daily-quest header strong,
.reading-unread-card header strong,
.reading-map header strong,
.reading-collection-sets strong {
  color: #d8cec8;
}

.reading-daily-quest header p {
  margin: 3px 0 0;
  color: #766b66;
  font-size: 9px;
  line-height: 1.45;
}

.reading-daily-quest > header > b,
.reading-unread-card header > b {
  padding: 4px 7px;
  border-radius: 999px;
  background: rgba(255,255,255,.035);
  color: #827670;
  font-size: 8px;
}

.reading-daily-quest.is-complete > header > b {
  color: #82b88d;
  background: rgba(112,178,128,.06);
}

.reading-quest-steps,
.reading-unread-list {
  display: grid;
  gap: 6px;
}

.reading-quest-steps > a,
.reading-unread-list > a {
  min-width: 0;
  min-height: 48px;
  display: grid;
  grid-template-columns: 30px minmax(0,1fr) auto;
  align-items: center;
  gap: 9px;
  padding: 8px 9px;
  border: 1px solid rgba(255,255,255,.045);
  border-radius: 10px;
  background: rgba(255,255,255,.012);
  text-decoration: none;
  transition: border-color .16s ease, background .16s ease, transform .16s ease;
}

.reading-quest-steps > a:hover,
.reading-unread-list > a:hover,
.reading-map-nodes > a:hover,
.next-exploration-grid > a:hover {
  transform: translateY(-1px);
  border-color: rgba(126,161,196,.18);
  background: rgba(126,161,196,.025);
}

.reading-quest-steps > a > span,
.reading-unread-list > a > span {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: rgba(255,255,255,.03);
  color: #927f70;
  font-size: 12px;
  font-weight: 900;
}

.reading-quest-steps > a.is-complete > span {
  background: rgba(112,178,128,.07);
  color: #7fba8c;
}

.reading-quest-steps a div,
.reading-unread-list a div {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.reading-quest-steps a small,
.reading-unread-list a small {
  color: #726762;
  font-size: 8px;
}

.reading-quest-steps a strong,
.reading-unread-list a strong {
  overflow: hidden;
  color: #cfc4be;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.reading-quest-steps a > b,
.reading-unread-list a > b {
  color: #806f62;
  font-size: 9px;
}

.reading-unread-card > header {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 11px;
}

.reading-unread-card > header > div {
  display: grid;
  gap: 3px;
}

.reading-unread-complete {
  min-height: 156px;
  display: grid;
  place-items: center;
  padding: 16px;
  color: #91b49a;
  font-size: 11px;
  text-align: center;
}

.reading-collection-sets {
  margin-top: 10px;
  display: grid;
  grid-template-columns: repeat(3,minmax(0,1fr));
  gap: 9px;
}

.reading-collection-sets > article {
  display: grid;
  grid-template-columns: 38px minmax(0,1fr);
  gap: 10px;
  padding: 13px;
}

.reading-collection-sets > article.is-complete {
  border-color: rgba(214,171,95,.16);
  background:
    radial-gradient(circle at 0 0, rgba(214,171,95,.07), transparent 48%),
    rgba(255,255,255,.014);
}

.reading-set-icon {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 11px;
  background: rgba(var(--gold-rgb),.045);
  font-size: 18px;
}

.reading-collection-sets article > div {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.reading-collection-sets p {
  margin: 0;
  color: #716762;
  font-size: 8px;
  line-height: 1.4;
}

.reading-collection-sets i {
  height: 4px;
  display: block;
  overflow: hidden;
  border-radius: 99px;
  background: rgba(255,255,255,.045);
}

.reading-collection-sets i > i {
  height: 100%;
  display: block;
  border-radius: inherit;
  background: linear-gradient(90deg,#769fc4,#c9a363);
}

.reading-collection-sets em {
  color: #83756e;
  font-size: 8px;
  font-style: normal;
}

.reading-collection-sets article.is-complete em {
  color: #c7a867;
}

.reading-map {
  margin-top: 10px;
  padding: 15px;
}

.reading-map > header {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}

.reading-map > header > div {
  display: grid;
  gap: 3px;
}

.reading-map > header > span {
  color: #716762;
  font-size: 8px;
}

.reading-map-routes {
  display: grid;
  gap: 9px;
}

.reading-map-route {
  display: grid;
  grid-template-columns: 120px minmax(0,1fr);
  align-items: center;
  gap: 10px;
}

.reading-map-category {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #9b8a80;
  font-size: 9px;
}

.reading-map-category > span {
  width: 24px;
  height: 24px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255,255,255,.055);
  border-radius: 50%;
  background: rgba(255,255,255,.02);
  color: #776b66;
  font-size: 8px;
}

.reading-map-nodes {
  position: relative;
  display: flex;
  gap: 6px;
  overflow-x: auto;
  padding: 3px 0;
  scrollbar-width: thin;
}

.reading-map-nodes::before {
  content: "";
  position: absolute;
  top: 20px;
  left: 8px;
  right: 8px;
  height: 1px;
  background: rgba(255,255,255,.045);
  pointer-events: none;
}

.reading-map-nodes > a {
  position: relative;
  z-index: 1;
  flex: 0 0 auto;
  min-width: 86px;
  max-width: 126px;
  display: grid;
  justify-items: center;
  gap: 5px;
  padding: 7px;
  border: 1px solid rgba(255,255,255,.05);
  border-radius: 10px;
  background: #151314;
  color: #756a65;
  text-decoration: none;
}

.reading-map-nodes > a > span {
  width: 26px;
  height: 26px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: rgba(255,255,255,.035);
  font-size: 12px;
}

.reading-map-nodes > a > strong {
  width: 100%;
  overflow: hidden;
  font-size: 8px;
  text-align: center;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.reading-map-nodes > a.is-complete {
  border-color: rgba(112,178,128,.14);
  background: rgba(112,178,128,.025);
  color: #89b795;
}

.reading-map-nodes > a.is-complete > span {
  background: rgba(112,178,128,.075);
}

.reading-quiz-card {
  padding: 18px;
  background:
    radial-gradient(circle at 94% 0, rgba(126,161,196,.07), transparent 32%),
    rgba(16,14,15,.88);
}

.reading-quiz-card.is-complete {
  border-color: rgba(112,178,128,.15);
}

.reading-quiz-locked {
  margin-top: 12px;
  display: grid;
  grid-template-columns: 38px minmax(0,1fr);
  align-items: center;
  gap: 10px;
  padding: 12px;
  border: 1px dashed rgba(255,255,255,.06);
  border-radius: 12px;
  background: rgba(255,255,255,.012);
}

.reading-quiz-locked > span {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: rgba(255,255,255,.025);
}

.reading-quiz-locked > div {
  display: grid;
  gap: 3px;
}

.reading-quiz-locked strong {
  color: #aa9e98;
  font-size: 10px;
}

.reading-quiz-locked small {
  color: #716762;
  font-size: 8px;
  line-height: 1.45;
}

.reading-quiz-question {
  display: block;
  margin-top: 14px;
  color: #cfc4be;
  font-size: 12px;
}

.reading-quiz-options {
  margin-top: 8px;
  display: grid;
  grid-template-columns: repeat(3,minmax(0,1fr));
  gap: 7px;
}

.reading-quiz-options > button {
  min-height: 46px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 9px 11px;
  border: 1px solid rgba(255,255,255,.055);
  border-radius: 10px;
  background: rgba(255,255,255,.014);
  color: #a99d97;
  font: inherit;
  font-size: 9px;
  cursor: pointer;
}

.reading-quiz-options > button:hover:not(:disabled),
.reading-quiz-options > button.is-selected {
  border-color: rgba(126,161,196,.18);
  background: rgba(126,161,196,.035);
}

.reading-quiz-options > button.is-correct {
  border-color: rgba(112,178,128,.18);
  background: rgba(112,178,128,.04);
  color: #91bb9b;
}

.reading-quiz-message {
  margin: 8px 0 0;
  color: #a18a78;
  font-size: 9px;
}

.reading-quiz-message.is-success {
  color: #83b18e;
}

.next-exploration {
  padding: 18px;
}

.next-exploration-head {
  margin-bottom: 12px;
}

.next-exploration-grid {
  display: grid;
  grid-template-columns: repeat(3,minmax(0,1fr));
  gap: 9px;
}

.next-exploration-grid > a {
  min-width: 0;
  display: grid;
  grid-template-columns: 28px 76px minmax(0,1fr);
  align-items: center;
  gap: 9px;
  padding: 9px;
  border: 1px solid rgba(255,255,255,.05);
  border-radius: 12px;
  background: rgba(255,255,255,.014);
  text-decoration: none;
  transition: transform .16s ease, border-color .16s ease, background .16s ease;
}

.next-exploration-index {
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: rgba(126,161,196,.055);
  color: #87a0b8;
  font-size: 9px;
  font-weight: 900;
}

.next-exploration-image {
  width: 76px;
  aspect-ratio: 16/9;
  overflow: hidden;
  border-radius: 8px;
  background: rgba(255,255,255,.025);
}

.next-exploration-image img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
}

.next-exploration-copy {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.next-exploration-copy small {
  color: #756a65;
  font-size: 8px;
}

.next-exploration-copy strong {
  overflow: hidden;
  color: #cfc4be;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.next-exploration-copy em {
  color: #829caf;
  font-size: 8px;
  font-style: normal;
}

.next-exploration-grid > a.is-complete {
  opacity: .66;
}

.wiki-inline-treasure {
  width: fit-content;
  max-width: 100%;
  margin: 10px 0 14px auto;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 5px 8px;
  border: 1px dashed rgba(var(--gold-rgb),.16);
  border-radius: 999px;
  background: rgba(var(--gold-rgb),.025);
  color: #9e8257;
  font: inherit;
  cursor: pointer;
  animation: inlineTreasureGlint 2.9s ease-in-out infinite;
}

.wiki-inline-treasure > span {
  font-size: 12px;
}

.wiki-inline-treasure > small {
  font-size: 8px;
  font-weight: 750;
}

.wiki-inline-treasure:hover,
.wiki-inline-treasure:focus-visible {
  border-color: rgba(var(--gold-rgb),.32);
  color: #d7b16d;
  background: rgba(var(--gold-rgb),.055);
}

@keyframes inlineTreasureGlint {
  0%, 70%, 100% { opacity: .58; transform: translateY(0); }
  82% { opacity: 1; transform: translateY(-1px); }
}

html[data-theme="light"] .wiki-reading-explorer,
html[data-theme="light"] .reading-quiz-card,
html[data-theme="light"] .next-exploration {
  border-color: rgba(118,84,55,.1);
  background:
    radial-gradient(circle at 8% 0%, rgba(94,131,177,.045), transparent 30%),
    rgba(255,250,243,.78);
}

html[data-theme="light"] .reading-explorer-head h2,
html[data-theme="light"] .next-exploration-head h2,
html[data-theme="light"] .reading-quiz-head h2,
html[data-theme="light"] .reading-daily-quest header strong,
html[data-theme="light"] .reading-unread-card header strong,
html[data-theme="light"] .reading-collection-sets strong,
html[data-theme="light"] .reading-map header strong,
html[data-theme="light"] .reading-quest-steps a strong,
html[data-theme="light"] .reading-unread-list a strong,
html[data-theme="light"] .next-exploration-copy strong,
html[data-theme="light"] .reading-quiz-question {
  color: #523a33;
}

html[data-theme="light"] .reading-daily-quest,
html[data-theme="light"] .reading-unread-card,
html[data-theme="light"] .reading-collection-sets > article,
html[data-theme="light"] .reading-map,
html[data-theme="light"] .reading-quiz-locked,
html[data-theme="light"] .reading-quiz-options > button,
html[data-theme="light"] .next-exploration-grid > a {
  border-color: rgba(118,84,55,.09);
  background: rgba(255,255,255,.44);
}

html[data-theme="light"] .reading-map-nodes > a {
  border-color: rgba(118,84,55,.09);
  background: #fffaf3;
}

html[data-theme="light"] .wiki-inline-treasure {
  border-color: rgba(149,107,47,.16);
  background: rgba(149,107,47,.035);
  color: #805d2d;
}

@media (max-width: 900px) {
  .reading-explorer-top {
    grid-template-columns: 1fr;
  }

  .reading-collection-sets,
  .next-exploration-grid {
    grid-template-columns: 1fr;
  }

  .reading-map-route {
    grid-template-columns: 1fr;
  }

  .reading-map-category {
    margin-bottom: 1px;
  }

  .reading-quiz-options {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 620px) {
  .wiki-reading-explorer,
  .reading-quiz-card,
  .next-exploration {
    padding: 14px;
    border-radius: 16px;
  }

  .reading-explorer-head,
  .next-exploration-head,
  .reading-quiz-head {
    align-items: flex-start;
  }

  .reading-explorer-head h2,
  .next-exploration-head h2,
  .reading-quiz-head h2 {
    font-size: 17px;
  }

  .reading-explorer-head > b,
  .reading-quiz-head > b {
    padding: 5px 7px;
    font-size: 8px;
  }

  .reading-daily-quest > header {
    grid-template-columns: 36px minmax(0,1fr);
  }

  .reading-daily-quest > header > b {
    grid-column: 2;
    justify-self: start;
  }

  .reading-daily-quest > header > span {
    width: 36px;
    height: 36px;
  }

  .reading-map > header {
    align-items: flex-start;
    flex-direction: column;
  }

  .next-exploration-grid > a {
    grid-template-columns: 28px 64px minmax(0,1fr);
  }

  .next-exploration-image {
    width: 64px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .wiki-inline-treasure {
    animation: none;
  }

  .reading-quest-steps > a,
  .reading-unread-list > a,
  .reading-map-nodes > a,
  .next-exploration-grid > a {
    transition: none;
  }
}


/* === Survival Adventure Hub === */
.wiki-adventure-hub {
  width: min(100%, var(--content-max));
  margin: 0 auto;
  padding: 24px;
  border: 1px solid rgba(255,255,255,.055);
  border-radius: 20px;
  background:
    radial-gradient(circle at 8% 0%, rgba(204,158,82,.08), transparent 30%),
    radial-gradient(circle at 94% 0%, rgba(105,132,173,.07), transparent 28%),
    rgba(16,14,15,.9);
  box-shadow: 0 16px 48px rgba(0,0,0,.14);
}

.adventure-hub-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 16px;
}

.adventure-hub-head p {
  margin: 0 0 5px;
  color: #c89d62;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .14em;
}

.adventure-hub-head h2 {
  margin: 0;
  color: #f1e7e2;
  font-size: 21px;
  letter-spacing: -.025em;
}

.adventure-hub-head span {
  display: block;
  margin-top: 6px;
  color: #8b7e78;
  font-size: 10px;
  line-height: 1.55;
}

.adventure-hub-head > strong {
  flex: 0 0 auto;
  padding: 6px 10px;
  border: 1px solid rgba(var(--gold-rgb),.16);
  border-radius: 999px;
  background: rgba(var(--gold-rgb),.045);
  color: #b79a70;
  font-size: 9px;
}

.adventure-tabs {
  display: grid;
  grid-template-columns: repeat(4,minmax(0,1fr));
  gap: 7px;
  margin-bottom: 10px;
}

.adventure-tabs button {
  min-width: 0;
  min-height: 58px;
  display: grid;
  grid-template-columns: 30px minmax(0,1fr);
  grid-template-rows: auto auto;
  align-items: center;
  column-gap: 8px;
  padding: 9px 11px;
  border: 1px solid rgba(255,255,255,.05);
  border-radius: 12px;
  background: rgba(255,255,255,.012);
  color: inherit;
  text-align: left;
  cursor: pointer;
  transition: transform .16s ease, border-color .16s ease, background .16s ease;
}

.adventure-tabs button:hover {
  transform: translateY(-1px);
  border-color: rgba(var(--gold-rgb),.14);
  background: rgba(var(--gold-rgb),.022);
}

.adventure-tabs button.is-active {
  border-color: rgba(var(--gold-rgb),.2);
  background:
    radial-gradient(circle at 0 0, rgba(var(--gold-rgb),.09), transparent 58%),
    rgba(255,255,255,.02);
  box-shadow: inset 0 -2px 0 rgba(var(--gold-rgb),.42);
}

.adventure-tabs button > span {
  grid-row: 1 / 3;
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: rgba(255,255,255,.028);
  font-size: 15px;
}

.adventure-tabs small {
  color: #766c67;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .1em;
}

.adventure-tabs strong {
  overflow: hidden;
  color: #aaa09a;
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.adventure-tabs button.is-active small {
  color: #b28e5b;
}

.adventure-tabs button.is-active strong {
  color: #e0d5cf;
}

.adventure-stage {
  min-height: 330px;
  padding: 16px;
  border: 1px solid rgba(255,255,255,.045);
  border-radius: 16px;
  background: rgba(255,255,255,.01);
}

.adventure-story-intro {
  display: grid;
  grid-template-columns: 54px minmax(0,1fr);
  align-items: center;
  gap: 12px;
  margin-bottom: 14px;
  padding: 13px;
  border: 1px solid rgba(var(--gold-rgb),.08);
  border-radius: 13px;
  background:
    linear-gradient(100deg, rgba(var(--gold-rgb),.045), transparent 58%);
}

.adventure-story-intro > span {
  width: 54px;
  height: 54px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(var(--gold-rgb),.13);
  border-radius: 50%;
  background: rgba(var(--gold-rgb),.045);
  font-size: 26px;
}

.adventure-story-intro > div {
  display: grid;
  gap: 3px;
}

.adventure-story-intro small,
.story-chapter-copy > small,
.passport-cover small,
.passport-pages header small,
.survival-build-head small,
.boss-visual small,
.boss-hp-row small {
  color: #9b7d54;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .09em;
}

.adventure-story-intro strong,
.story-chapter-copy > strong,
.passport-pages header strong,
.survival-build-head strong,
.boss-visual strong {
  color: #d9cec8;
}

.adventure-story-intro p,
.story-chapter-copy > p,
.survival-build-head p,
.boss-visual p {
  margin: 0;
  color: #766c67;
  font-size: 9px;
  line-height: 1.5;
}

.story-chapter-list {
  display: grid;
  gap: 0;
}

.story-chapter-list > article {
  display: grid;
  grid-template-columns: 42px minmax(0,1fr);
  gap: 10px;
}

.story-chapter-marker {
  position: relative;
  display: grid;
  justify-items: center;
}

.story-chapter-marker > span {
  position: relative;
  z-index: 1;
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255,255,255,.055);
  border-radius: 50%;
  background: #151314;
  color: #81746d;
  font-size: 14px;
}

.story-chapter-marker > i {
  position: absolute;
  top: 34px;
  bottom: 0;
  width: 1px;
  background: rgba(255,255,255,.055);
}

.story-chapter-list article.is-complete .story-chapter-marker > span {
  border-color: rgba(112,178,128,.17);
  background: rgba(112,178,128,.06);
  color: #8abe95;
}

.story-chapter-list article.is-locked .story-chapter-marker > span {
  opacity: .48;
  filter: grayscale(.5);
}

.story-chapter-copy {
  min-width: 0;
  padding: 2px 0 16px;
}

.story-chapter-copy > strong {
  display: block;
  margin-top: 2px;
  font-size: 11px;
}

.story-chapter-copy > p {
  margin-top: 3px;
}

.story-choice-grid {
  display: grid;
  grid-template-columns: repeat(2,minmax(0,1fr));
  gap: 6px;
  margin-top: 8px;
}

.story-choice-grid > a {
  min-width: 0;
  display: grid;
  grid-template-columns: 32px minmax(0,1fr) auto;
  align-items: center;
  gap: 8px;
  padding: 8px;
  border: 1px solid rgba(255,255,255,.045);
  border-radius: 10px;
  background: rgba(255,255,255,.012);
  text-decoration: none;
  transition: transform .16s ease, border-color .16s ease, background .16s ease;
}

.story-choice-grid > a:hover {
  transform: translateY(-1px);
  border-color: rgba(var(--gold-rgb),.16);
  background: rgba(var(--gold-rgb),.025);
}

.story-choice-grid > a.is-complete {
  border-color: rgba(112,178,128,.13);
  background: rgba(112,178,128,.022);
}

.story-choice-grid > a > span {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: rgba(255,255,255,.03);
  font-size: 14px;
}

.story-choice-grid > a > div {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.story-choice-grid small {
  color: #746963;
  font-size: 7px;
}

.story-choice-grid strong {
  overflow: hidden;
  color: #c8bdb7;
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.story-choice-grid b {
  color: #9c805c;
  font-size: 8px;
}

.story-choice-grid .is-complete b {
  color: #7fb08a;
}

.story-locked-copy {
  margin-top: 7px;
  padding: 9px 10px;
  border: 1px dashed rgba(255,255,255,.045);
  border-radius: 9px;
  color: #695f5a;
  font-size: 8px;
}

.adventure-passport {
  display: grid;
  grid-template-columns: 220px minmax(0,1fr);
  gap: 12px;
}

.passport-cover {
  min-height: 310px;
  display: grid;
  align-content: center;
  justify-items: center;
  gap: 8px;
  padding: 20px;
  border: 1px solid rgba(var(--gold-rgb),.16);
  border-radius: 15px;
  background:
    radial-gradient(circle at 50% 18%, rgba(var(--gold-rgb),.1), transparent 35%),
    linear-gradient(155deg, rgba(104,66,42,.22), rgba(48,30,26,.2)),
    rgba(255,255,255,.016);
  text-align: center;
  box-shadow: inset 0 0 0 4px rgba(var(--gold-rgb),.025);
}

.passport-emblem {
  width: 72px;
  height: 72px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(var(--gold-rgb),.24);
  border-radius: 50%;
  background: rgba(var(--gold-rgb),.055);
  font-size: 34px;
}

.passport-cover > strong {
  color: #dfccb0;
  font-size: 17px;
}

.passport-cover > span {
  padding: 5px 8px;
  border: 1px solid rgba(var(--gold-rgb),.12);
  border-radius: 999px;
  color: #a68a65;
  font-size: 8px;
  letter-spacing: .08em;
}

.passport-pages {
  display: grid;
  gap: 8px;
}

.passport-pages > article {
  padding: 11px;
  border: 1px solid rgba(255,255,255,.045);
  border-radius: 12px;
  background: rgba(255,255,255,.012);
}

.passport-pages > article.is-complete {
  border-color: rgba(var(--gold-rgb),.14);
  background: rgba(var(--gold-rgb),.018);
}

.passport-pages header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}

.passport-pages header > div {
  display: grid;
  gap: 2px;
}

.passport-pages header b {
  color: #917b62;
  font-size: 8px;
}

.passport-pages article.is-complete header b {
  color: #c5a46c;
}

.passport-stamps {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.passport-stamps > a {
  width: 70px;
  min-height: 70px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 2px;
  padding: 5px;
  border: 1px dashed rgba(255,255,255,.055);
  border-radius: 50%;
  color: #695f5a;
  text-decoration: none;
  text-align: center;
  opacity: .55;
}

.passport-stamps > a.is-stamped {
  border-style: solid;
  border-color: rgba(var(--gold-rgb),.19);
  background: rgba(var(--gold-rgb),.025);
  color: #b18f5f;
  opacity: 1;
  transform: rotate(-2deg);
}

.passport-stamps span {
  font-size: 18px;
}

.passport-stamps strong {
  width: 56px;
  overflow: hidden;
  font-size: 7px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.passport-stamps small {
  font-size: 6px;
  letter-spacing: .06em;
}

.survival-build-head {
  display: grid;
  grid-template-columns: 50px minmax(0,1fr) auto;
  align-items: center;
  gap: 12px;
  padding: 12px;
  border: 1px solid rgba(118,153,192,.09);
  border-radius: 12px;
  background: rgba(118,153,192,.02);
}

.survival-build-head > span {
  width: 50px;
  height: 50px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  background: rgba(118,153,192,.055);
  font-size: 23px;
}

.survival-build-head > div {
  display: grid;
  gap: 2px;
}

.survival-build-head > b {
  padding: 5px 8px;
  border-radius: 999px;
  background: rgba(118,153,192,.05);
  color: #8ea6bd;
  font-size: 9px;
}

.build-personalize-note,
.build-complete-banner {
  margin-top: 8px;
  padding: 8px 10px;
  border-radius: 9px;
  font-size: 8px;
  line-height: 1.45;
}

.build-personalize-note {
  border: 1px dashed rgba(118,153,192,.11);
  color: #7e8994;
}

.build-complete-banner {
  border: 1px solid rgba(112,178,128,.12);
  background: rgba(112,178,128,.025);
  color: #8db497;
  text-align: center;
}

.survival-build-route {
  display: grid;
  grid-template-columns: repeat(5,minmax(0,1fr));
  gap: 7px;
  margin-top: 10px;
}

.survival-build-route > a {
  position: relative;
  min-width: 0;
  min-height: 122px;
  display: grid;
  justify-items: center;
  align-content: start;
  gap: 5px;
  padding: 10px 8px;
  border: 1px solid rgba(255,255,255,.045);
  border-radius: 11px;
  background: rgba(255,255,255,.012);
  text-decoration: none;
}

.survival-build-route > a.is-complete {
  border-color: rgba(112,178,128,.13);
  background: rgba(112,178,128,.022);
}

.build-step-number {
  position: absolute;
  top: 7px;
  left: 7px;
  width: 20px;
  height: 20px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: rgba(255,255,255,.035);
  color: #766a65;
  font-size: 7px;
  font-weight: 900;
}

.survival-build-route .is-complete .build-step-number {
  color: #7fae89;
  background: rgba(112,178,128,.06);
}

.build-step-icon {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  margin-top: 8px;
  border-radius: 12px;
  background: rgba(118,153,192,.045);
  font-size: 19px;
}

.survival-build-route > a > div {
  width: 100%;
  min-width: 0;
  display: grid;
  justify-items: center;
  gap: 2px;
  text-align: center;
}

.survival-build-route small {
  color: #6e6560;
  font-size: 7px;
}

.survival-build-route strong {
  width: 100%;
  overflow: hidden;
  color: #c4b9b3;
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.survival-build-route em {
  color: #8195a7;
  font-size: 7px;
  font-style: normal;
}

.build-route-line {
  position: absolute;
  top: 37px;
  right: -8px;
  width: 8px;
  height: 1px;
  background: rgba(255,255,255,.07);
}

.weekly-boss-card {
  display: grid;
  grid-template-columns: minmax(190px,.65fr) minmax(0,1.35fr);
  gap: 12px;
}

.boss-visual,
.boss-battle {
  border: 1px solid rgba(255,255,255,.045);
  border-radius: 13px;
  background: rgba(255,255,255,.012);
}

.boss-visual {
  position: relative;
  min-height: 270px;
  display: grid;
  align-content: center;
  justify-items: center;
  gap: 5px;
  padding: 18px;
  text-align: center;
  background:
    radial-gradient(circle at 50% 42%, rgba(181,84,72,.08), transparent 35%),
    rgba(255,255,255,.012);
}

.boss-week-label {
  position: absolute;
  align-self: start;
  justify-self: end;
  padding: 4px 6px;
  border-radius: 999px;
  background: rgba(255,255,255,.025);
  color: #716762;
  font-size: 7px;
}

.boss-icon {
  width: 82px;
  height: 82px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(181,84,72,.14);
  border-radius: 50%;
  background: rgba(181,84,72,.035);
  font-size: 42px;
}

.weekly-boss-card.is-defeated .boss-icon {
  border-color: rgba(var(--gold-rgb),.18);
  background: rgba(var(--gold-rgb),.04);
}

.boss-visual strong {
  font-size: 14px;
}

.boss-battle {
  padding: 15px;
}

.boss-hp-row {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 10px;
}

.boss-hp-row > span {
  display: grid;
  gap: 2px;
}

.boss-hp-row strong {
  color: #ded3cd;
  font-size: 18px;
}

.boss-hp-row > b {
  color: #ba746a;
  font-size: 8px;
}

.weekly-boss-card.is-defeated .boss-hp-row > b {
  color: #b99a66;
}

.boss-hp-track {
  height: 9px;
  margin-top: 7px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255,255,255,.045);
}

.boss-hp-track > i {
  height: 100%;
  display: block;
  border-radius: inherit;
  background: linear-gradient(90deg,#8d4d48,#c78e5a);
  transition: width .35s ease;
}

.weekly-boss-card.is-defeated .boss-hp-track > i {
  background: linear-gradient(90deg,#8a9d6a,#c9a45f);
}

.boss-damage-grid {
  display: grid;
  grid-template-columns: repeat(4,minmax(0,1fr));
  gap: 6px;
  margin-top: 12px;
}

.boss-damage-grid > div {
  display: grid;
  justify-items: center;
  gap: 2px;
  padding: 9px 5px;
  border: 1px solid rgba(255,255,255,.04);
  border-radius: 10px;
  background: rgba(255,255,255,.012);
}

.boss-damage-grid span {
  font-size: 16px;
}

.boss-damage-grid strong {
  color: #c9bdb7;
  font-size: 13px;
}

.boss-damage-grid small,
.boss-damage-grid em {
  color: #716762;
  font-size: 7px;
  font-style: normal;
}

.boss-help {
  margin: 10px 0 0;
  padding: 9px;
  border-top: 1px solid rgba(255,255,255,.04);
  color: #716762;
  font-size: 8px;
  line-height: 1.55;
}

html[data-theme="light"] .wiki-adventure-hub {
  border-color: rgba(118,84,55,.1);
  background:
    radial-gradient(circle at 8% 0%, rgba(149,107,47,.05), transparent 30%),
    rgba(255,250,243,.8);
}

html[data-theme="light"] .adventure-hub-head h2,
html[data-theme="light"] .adventure-tabs button.is-active strong,
html[data-theme="light"] .adventure-story-intro strong,
html[data-theme="light"] .story-chapter-copy > strong,
html[data-theme="light"] .story-choice-grid strong,
html[data-theme="light"] .passport-pages header strong,
html[data-theme="light"] .survival-build-head strong,
html[data-theme="light"] .survival-build-route strong,
html[data-theme="light"] .boss-visual strong,
html[data-theme="light"] .boss-hp-row strong {
  color: #513832;
}

html[data-theme="light"] .adventure-stage,
html[data-theme="light"] .adventure-tabs button,
html[data-theme="light"] .adventure-story-intro,
html[data-theme="light"] .story-choice-grid > a,
html[data-theme="light"] .passport-pages > article,
html[data-theme="light"] .survival-build-head,
html[data-theme="light"] .survival-build-route > a,
html[data-theme="light"] .boss-visual,
html[data-theme="light"] .boss-battle,
html[data-theme="light"] .boss-damage-grid > div {
  border-color: rgba(118,84,55,.08);
  background-color: rgba(255,255,255,.42);
}

html[data-theme="light"] .story-chapter-marker > span {
  background: #fffaf3;
  border-color: rgba(118,84,55,.09);
}

html[data-theme="light"] .passport-cover {
  background:
    radial-gradient(circle at 50% 18%, rgba(149,107,47,.08), transparent 35%),
    linear-gradient(155deg, rgba(164,116,77,.11), rgba(255,250,243,.6));
}

@media (max-width: 900px) {
  .adventure-passport,
  .weekly-boss-card {
    grid-template-columns: 1fr;
  }

  .passport-cover {
    min-height: 190px;
  }

  .survival-build-route {
    grid-template-columns: repeat(3,minmax(0,1fr));
  }

  .build-route-line {
    display: none;
  }
}

@media (max-width: 620px) {
  .wiki-adventure-hub {
    padding: 14px;
    border-radius: 16px;
  }

  .adventure-hub-head {
    align-items: flex-start;
  }

  .adventure-hub-head h2 {
    font-size: 17px;
  }

  .adventure-tabs {
    display: flex;
    overflow-x: auto;
    padding-bottom: 2px;
    scrollbar-width: none;
  }

  .adventure-tabs::-webkit-scrollbar {
    display: none;
  }

  .adventure-tabs button {
    flex: 0 0 138px;
  }

  .adventure-stage {
    min-height: 300px;
    padding: 11px;
  }

  .story-choice-grid {
    grid-template-columns: 1fr;
  }

  .adventure-story-intro {
    grid-template-columns: 42px minmax(0,1fr);
  }

  .adventure-story-intro > span {
    width: 42px;
    height: 42px;
    font-size: 20px;
  }

  .story-chapter-list > article {
    grid-template-columns: 34px minmax(0,1fr);
  }

  .story-chapter-marker > span {
    width: 29px;
    height: 29px;
    font-size: 12px;
  }

  .story-chapter-marker > i {
    top: 29px;
  }

  .passport-stamps > a {
    width: 64px;
    min-height: 64px;
  }

  .survival-build-head {
    grid-template-columns: 42px minmax(0,1fr);
  }

  .survival-build-head > span {
    width: 42px;
    height: 42px;
  }

  .survival-build-head > b {
    grid-column: 2;
    justify-self: start;
  }

  .survival-build-route {
    grid-template-columns: repeat(2,minmax(0,1fr));
  }

  .boss-damage-grid {
    grid-template-columns: repeat(2,minmax(0,1fr));
  }
}

@media (prefers-reduced-motion: reduce) {
  .adventure-tabs button,
  .story-choice-grid > a,
  .boss-hp-track > i {
    transition: none;
  }
}


/* === Survival Adventure polish pass === */
.adventure-overview {
  display: grid;
  grid-template-columns: repeat(4,minmax(0,1fr));
  gap: 7px;
  margin-bottom: 9px;
}

.adventure-overview > span {
  min-width: 0;
  display: grid;
  gap: 2px;
  padding: 8px 10px;
  border: 1px solid rgba(255,255,255,.045);
  border-radius: 10px;
  background: rgba(255,255,255,.012);
}

.adventure-overview small {
  color: #6f6560;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .08em;
}

.adventure-overview strong {
  overflow: hidden;
  color: #aaa09a;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.adventure-overview > span.is-complete {
  border-color: rgba(112,178,128,.12);
  background: rgba(112,178,128,.022);
}

.adventure-overview > span.is-complete strong {
  color: #88b792;
}

.adventure-continue-card {
  min-height: 62px;
  display: grid;
  grid-template-columns: 34px minmax(0,1fr) auto;
  align-items: center;
  gap: 10px;
  margin-bottom: 9px;
  padding: 10px 12px;
  border: 1px solid rgba(var(--gold-rgb),.12);
  border-radius: 13px;
  background:
    linear-gradient(105deg, rgba(var(--gold-rgb),.05), transparent 64%),
    rgba(255,255,255,.012);
  text-decoration: none;
  transition: transform .16s ease, border-color .16s ease, background .16s ease;
}

.adventure-continue-card:hover,
.adventure-continue-card:focus-visible {
  transform: translateY(-1px);
  border-color: rgba(var(--gold-rgb),.23);
  background:
    linear-gradient(105deg, rgba(var(--gold-rgb),.075), transparent 64%),
    rgba(255,255,255,.016);
}

.adventure-continue-icon {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(var(--gold-rgb),.13);
  border-radius: 10px;
  background: rgba(var(--gold-rgb),.045);
  color: #c59e65;
  font-size: 10px;
}

.adventure-continue-copy {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.adventure-continue-copy small {
  color: #9d7d52;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .09em;
}

.adventure-continue-copy strong {
  overflow: hidden;
  color: #d9cec8;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.adventure-continue-copy em {
  overflow: hidden;
  color: #776c66;
  font-size: 8px;
  font-style: normal;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.adventure-continue-card > b {
  color: #ad8c60;
  font-size: 8px;
  white-space: nowrap;
}

.adventure-stage > [role="tabpanel"] {
  animation: adventurePanelIn .2s ease-out;
}

.story-progress-strip {
  display: grid;
  grid-template-columns: auto minmax(0,1fr) auto;
  align-items: center;
  gap: 9px;
  margin: 0 0 13px 44px;
  padding: 8px 10px;
  border: 1px solid rgba(255,255,255,.04);
  border-radius: 10px;
  background: rgba(255,255,255,.01);
}

.story-progress-strip > span {
  display: flex;
  align-items: baseline;
  gap: 4px;
}

.story-progress-strip strong,
.story-progress-strip > b {
  color: #b99767;
  font-size: 9px;
}

.story-progress-strip small {
  color: #6d625d;
  font-size: 6px;
  font-weight: 900;
  letter-spacing: .08em;
}

.story-progress-strip > i {
  height: 4px;
  display: block;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255,255,255,.045);
}

.story-progress-strip > i > i {
  height: 100%;
  display: block;
  border-radius: inherit;
  background: linear-gradient(90deg,#8aa076,#c79d5e);
  transition: width .35s ease;
}

.story-chapter-list > article.is-current .story-chapter-marker > span {
  border-color: rgba(var(--gold-rgb),.25);
  color: #d0ab70;
  background:
    radial-gradient(circle, rgba(var(--gold-rgb),.09), rgba(var(--gold-rgb),.025));
  box-shadow: 0 0 0 4px rgba(var(--gold-rgb),.025);
}

.story-chapter-list > article.is-current .story-chapter-copy {
  position: relative;
}

.story-chapter-list > article.is-current .story-chapter-copy::before {
  content: "NOW";
  position: absolute;
  top: 0;
  right: 0;
  padding: 2px 5px;
  border: 1px solid rgba(var(--gold-rgb),.12);
  border-radius: 999px;
  color: #9f8055;
  font-size: 6px;
  font-weight: 900;
  letter-spacing: .08em;
}

.passport-pages > article {
  position: relative;
  overflow: hidden;
}

.passport-special-seal {
  position: absolute;
  right: 10px;
  bottom: 8px;
  width: 54px;
  height: 54px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 0;
  border: 2px solid rgba(157,108,65,.22);
  border-radius: 50%;
  color: rgba(172,118,66,.62);
  transform: rotate(-11deg);
  pointer-events: none;
}

.passport-special-seal::before,
.passport-special-seal::after {
  content: "";
  position: absolute;
  border-radius: 50%;
}

.passport-special-seal::before {
  inset: 4px;
  border: 1px dashed currentColor;
}

.passport-special-seal::after {
  inset: 9px;
  border: 1px solid rgba(157,108,65,.12);
}

.passport-special-seal b,
.passport-special-seal em {
  position: relative;
  z-index: 1;
  font-style: normal;
  line-height: 1;
}

.passport-special-seal b {
  font-size: 6px;
  letter-spacing: .08em;
}

.passport-special-seal em {
  margin-top: 2px;
  font-size: 14px;
}

.passport-stamps > a {
  position: relative;
}

.passport-stamps > a.is-stamped::before,
.passport-stamps > a.is-stamped::after {
  content: "";
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
}

.passport-stamps > a.is-stamped::before {
  inset: 4px;
  border: 1px dashed rgba(var(--gold-rgb),.17);
}

.passport-stamps > a.is-stamped::after {
  width: 7px;
  height: 7px;
  right: 7px;
  top: 9px;
  background: rgba(var(--gold-rgb),.16);
  box-shadow:
    -30px 34px 0 rgba(var(--gold-rgb),.09),
    -3px 41px 0 rgba(var(--gold-rgb),.08);
}

.boss-defeat-seal {
  position: absolute;
  right: 14px;
  bottom: 14px;
  width: 82px;
  height: 82px;
  display: grid;
  place-items: center;
  align-content: center;
  border: 2px solid rgba(var(--gold-rgb),.24);
  border-radius: 50%;
  color: #ba965e;
  transform: rotate(-9deg);
  background: rgba(19,16,16,.34);
  box-shadow:
    inset 0 0 0 5px rgba(var(--gold-rgb),.025),
    0 8px 26px rgba(0,0,0,.12);
  animation: bossSealIn .5s cubic-bezier(.17,.82,.27,1);
}

.boss-defeat-seal::before {
  content: "";
  position: absolute;
  inset: 7px;
  border: 1px dashed currentColor;
  border-radius: 50%;
  opacity: .7;
}

.boss-defeat-seal span,
.boss-defeat-seal b {
  position: relative;
  z-index: 1;
  line-height: 1.1;
}

.boss-defeat-seal span {
  font-size: 8px;
  font-weight: 950;
  letter-spacing: .08em;
}

.boss-defeat-seal b {
  margin-top: 3px;
  font-size: 6px;
  letter-spacing: .09em;
}

.weekly-boss-card.is-defeated .boss-visual {
  background:
    radial-gradient(circle at 50% 42%, rgba(var(--gold-rgb),.1), transparent 35%),
    rgba(255,255,255,.012);
}

.weekly-boss-card.is-defeated .boss-icon {
  box-shadow:
    0 0 0 6px rgba(var(--gold-rgb),.025),
    0 0 30px rgba(var(--gold-rgb),.08);
}

.boss-next-hit {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 10px;
  padding: 9px 10px;
  border: 1px solid rgba(181,84,72,.075);
  border-radius: 10px;
  background: rgba(181,84,72,.018);
}

.boss-next-hit > div {
  display: grid;
  gap: 2px;
}

.boss-next-hit small {
  color: #956a65;
  font-size: 6px;
  font-weight: 900;
  letter-spacing: .09em;
}

.boss-next-hit strong {
  color: #ac918b;
  font-size: 8px;
}

.boss-next-hit > a {
  flex: 0 0 auto;
  padding: 5px 7px;
  border: 1px solid rgba(181,84,72,.1);
  border-radius: 8px;
  color: #b27b73;
  font-size: 7px;
  font-weight: 850;
  text-decoration: none;
}

.adventure-stage-nav {
  display: grid;
  grid-template-columns: 72px minmax(0,1fr) 72px;
  align-items: center;
  gap: 8px;
  margin-top: 13px;
  padding-top: 11px;
  border-top: 1px solid rgba(255,255,255,.04);
}

.adventure-stage-nav button {
  min-height: 32px;
  border: 1px solid rgba(255,255,255,.05);
  border-radius: 8px;
  background: rgba(255,255,255,.014);
  color: #8b7d75;
  font: inherit;
  font-size: 8px;
  cursor: pointer;
}

.adventure-stage-nav button:not(:disabled):hover {
  border-color: rgba(var(--gold-rgb),.13);
  color: #b6976c;
}

.adventure-stage-nav button:disabled {
  opacity: .28;
  cursor: default;
}

.adventure-stage-nav > span {
  display: grid;
  justify-items: center;
  gap: 2px;
  color: #847770;
  font-size: 8px;
}

.adventure-stage-nav > span small {
  color: #665d58;
  font-size: 7px;
}

.adventure-unlock-toast {
  position: fixed;
  z-index: 126;
  top: calc(var(--topbar) + 18px);
  left: 50%;
  min-width: min(90vw,340px);
  display: grid;
  grid-template-columns: 42px minmax(0,1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 11px 13px;
  overflow: hidden;
  transform: translateX(-50%);
  border: 1px solid rgba(var(--gold-rgb),.2);
  border-radius: 14px;
  background: rgba(17,14,15,.96);
  color: #dcc08d;
  box-shadow: 0 18px 50px rgba(0,0,0,.3);
  backdrop-filter: blur(12px);
  animation: adventureUnlockIn .32s cubic-bezier(.17,.8,.24,1);
}

.adventure-unlock-toast::after {
  content: "";
  position: absolute;
  inset: 0;
  transform: translateX(-130%);
  background: linear-gradient(110deg,transparent,rgba(255,255,255,.07),transparent);
  animation: adventureUnlockShine 1.2s ease .12s 1;
  pointer-events: none;
}

.adventure-unlock-toast > span {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: rgba(var(--gold-rgb),.07);
  font-size: 21px;
}

.adventure-unlock-toast > div {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.adventure-unlock-toast small {
  color: #9d8058;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .1em;
}

.adventure-unlock-toast strong {
  overflow: hidden;
  color: #e8cf9b;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.adventure-unlock-toast em {
  color: #8c7e76;
  font-size: 7px;
  font-style: normal;
}

.adventure-unlock-toast > b {
  color: #d4ad6c;
  font-size: 15px;
}

@keyframes adventurePanelIn {
  from { opacity: .45; transform: translateY(3px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes bossSealIn {
  from { opacity: 0; transform: rotate(-18deg) scale(.82); }
  to { opacity: 1; transform: rotate(-9deg) scale(1); }
}

@keyframes adventureUnlockIn {
  from { opacity: 0; transform: translate(-50%,-10px) scale(.97); }
  to { opacity: 1; transform: translate(-50%,0) scale(1); }
}

@keyframes adventureUnlockShine {
  from { transform: translateX(-130%); }
  to { transform: translateX(130%); }
}

html[data-theme="light"] .adventure-overview > span,
html[data-theme="light"] .adventure-continue-card,
html[data-theme="light"] .story-progress-strip,
html[data-theme="light"] .boss-next-hit,
html[data-theme="light"] .adventure-stage-nav button {
  border-color: rgba(118,84,55,.08);
  background-color: rgba(255,255,255,.38);
}

html[data-theme="light"] .adventure-continue-copy strong,
html[data-theme="light"] .boss-next-hit strong {
  color: #60473e;
}

html[data-theme="light"] .passport-special-seal {
  color: rgba(129,77,34,.62);
  border-color: rgba(129,77,34,.23);
}

html[data-theme="light"] .boss-defeat-seal {
  color: #8a642f;
  border-color: rgba(138,100,47,.25);
  background: rgba(255,250,243,.68);
}

html[data-theme="light"] .adventure-unlock-toast {
  border-color: rgba(149,107,47,.17);
  background: rgba(255,250,243,.97);
  color: #76562f;
  box-shadow: 0 16px 44px rgba(74,48,33,.16);
}

html[data-theme="light"] .adventure-unlock-toast strong {
  color: #6f4a1e;
