/* === 2026-09-26 enhancement lab · Minecraft/wiki refresh === */
.wiki-enhancement-lab {
  position: relative;
  overflow: hidden;
  display: grid;
  gap: 14px;
  padding: 18px;
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 16px;
  background:
    linear-gradient(180deg, rgba(27,29,30,.96), rgba(17,18,19,.98));
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.025),
    0 18px 42px rgba(0,0,0,.18);
}

.wiki-enhancement-lab::before {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: .42;
  background-image:
    linear-gradient(rgba(255,255,255,.018) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,.018) 1px, transparent 1px);
  background-size: 18px 18px;
  mask-image: linear-gradient(to bottom, rgba(0,0,0,.6), transparent 72%);
}

.enhancement-lab-head {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 18px;
  padding-bottom: 13px;
  border-bottom: 1px solid rgba(255,255,255,.055);
}

.enhancement-lab-head > div:first-child {
  display: grid;
  gap: 4px;
}

.enhancement-lab-head p {
  margin: 0;
  color: #67c8cc;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .08em;
}

