  max-width: 670px;
  color: #938b86;
  font-size: 11px;
  line-height: 1.6;
}

.enhancement-head-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  justify-content: end;
  gap: 7px;
}

.enhancement-sim-badge,
.enhancement-head-actions button {
  min-height: 30px;
  padding: 0 10px;
  border: 1px solid rgba(255,255,255,.075);
  border-radius: 7px;
  background: rgba(0,0,0,.14);
  color: #99908b;
  font-size: 9px;
  font-weight: 800;
}

.enhancement-sim-badge {
  display: inline-flex;
  align-items: center;
  color: #70cbd0;
  border-color: rgba(84,194,200,.16);
  background: rgba(60,174,181,.045);
}

.enhancement-head-actions button {
  cursor: pointer;
}

.enhancement-head-actions button:hover,
.enhancement-head-actions button:focus-visible {
  border-color: rgba(84,194,200,.28);
  color: #d0e5e6;
}

.enhancement-main-grid {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(270px, .72fr);
  gap: 12px;
}

.enhancement-forge {
  --forge-glow: 80, 194, 199;
  position: relative;
  overflow: hidden;
  min-height: 510px;
  display: grid;
  grid-template-rows: auto 1fr auto auto;
  gap: 10px;
  padding: 17px;
  border: 1px solid rgba(255,255,255,.065);
  border-radius: 12px;
  background:
    linear-gradient(180deg, rgba(11,13,14,.9), rgba(14,14,15,.98));
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.018),
    inset 0 0 0 1px rgba(0,0,0,.22);
  isolation: isolate;
}

.enhancement-forge[data-tier="mid"] {
  --forge-glow: 76, 190, 205;
}

.enhancement-forge[data-tier="high"] {
  --forge-glow: 91, 143, 224;
}

.enhancement-forge[data-tier="extreme"] {
  --forge-glow: 174, 111, 222;
}

.enhancement-forge[data-tier="legendary"] {
  --forge-glow: 235, 190, 90;
}

.enhancement-forge[data-state="destroy"] {
  --forge-glow: 213, 86, 73;
}

.enhancement-forge-grid {
  position: absolute;
  inset: 0;
  z-index: -2;
  pointer-events: none;
  opacity: .26;
  background:
    linear-gradient(rgba(255,255,255,.015) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,.015) 1px, transparent 1px);
  background-size: 16px 16px;
}

.enhancement-level-row {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 8px;
}

.enhancement-level-label {
  color: #687174;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .06em;
}

.enhancement-level-row > strong {
  color: rgb(var(--forge-glow));
  font-size: 32px;
  line-height: 1;
  text-shadow: 0 0 18px rgba(var(--forge-glow), .16);
}

.enhancement-item-name {
  color: #a39c98;
  font-size: 10px;
  font-weight: 800;
}

.enhancement-item-stage {
  position: relative;
  min-height: 292px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 12px;
  padding: 14px 0 6px;
}

.enhancement-slot-shell {
  position: relative;
  z-index: 3;
  width: 190px;
  height: 190px;
  padding: 7px;
  border: 1px solid rgba(255,255,255,.08);
  background:
    linear-gradient(135deg, #2a2c2d, #151718);
  box-shadow:
    inset 3px 3px 0 rgba(255,255,255,.035),
    inset -3px -3px 0 rgba(0,0,0,.38),
    0 12px 28px rgba(0,0,0,.28);
  image-rendering: pixelated;
  transition:
    border-color .2s ease,
    box-shadow .2s ease,
    transform .2s ease;
}

.enhancement-slot-shell::before,
.enhancement-slot-shell::after {
  content: '';
  position: absolute;
  pointer-events: none;
}

.enhancement-slot-shell::before {
  inset: 3px;
  border-top: 2px solid rgba(255,255,255,.045);
  border-left: 2px solid rgba(255,255,255,.035);
  border-right: 2px solid rgba(0,0,0,.28);
  border-bottom: 2px solid rgba(0,0,0,.34);
}

.enhancement-slot-shell::after {
  inset: -1px;
  opacity: 0;
  box-shadow: 0 0 24px rgba(var(--forge-glow), .22);
  transition: opacity .2s ease;
}

.enhancement-slot-shell[data-enchanted="true"] {
  border-color: rgba(var(--forge-glow), .28);
  box-shadow:
    inset 3px 3px 0 rgba(255,255,255,.04),
    inset -3px -3px 0 rgba(0,0,0,.4),
    0 12px 32px rgba(0,0,0,.3),
    0 0 18px rgba(var(--forge-glow), .075);
}

.enhancement-slot-shell[data-enchanted="true"]::after {
  opacity: .72;
}

.enhancement-slot {
  width: 100%;
  height: 100%;
  padding: 6px;
  background: #080a0b;
  box-shadow:
    inset 0 0 0 1px rgba(255,255,255,.035),
    inset 0 0 20px rgba(0,0,0,.48);
}

.enhancement-slot-inner {
  position: relative;
  width: 100%;
  height: 100%;
  display: grid;
  place-items: center;
  overflow: hidden;
  background:
    linear-gradient(135deg, rgba(255,255,255,.018), transparent 38%),
    #101314;
}

.enhancement-slot-inner::before {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: .18;
  background-image:
    linear-gradient(rgba(255,255,255,.028) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,.028) 1px, transparent 1px);
  background-size: 12px 12px;
}

.enhancement-pickaxe {
  position: relative;
  z-index: 3;
  width: 154px;
  height: 154px;
  display: grid;
  place-items: center;
  transform: translateY(1px);
  filter:
    drop-shadow(0 9px 9px rgba(0,0,0,.38))
    drop-shadow(0 0 13px rgba(var(--forge-glow), .08));
  transition:
    transform .22s ease,
    filter .22s ease,
    opacity .22s ease;
}

.enhancement-pickaxe-image {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
  image-rendering: pixelated;
  user-select: none;
  pointer-events: none;
}

.enhancement-enchant-sheen {
  position: absolute;
  z-index: 4;
  inset: -40% -80%;
  pointer-events: none;
  opacity: .28;
  mix-blend-mode: screen;
  background:
    linear-gradient(
      115deg,
      transparent 34%,
      rgba(91,178,255,.1) 43%,
      rgba(211,116,255,.24) 48%,
      rgba(100,216,255,.13) 54%,
      transparent 63%
    );
  transform: translateX(-24%);
  animation: enhancementEnchantedSheen 3.8s ease-in-out infinite;
}

.enhancement-slot-level {
  position: absolute;
  z-index: 6;
  right: 8px;
  bottom: 7px;
  min-width: 35px;
  padding: 3px 6px;
  border: 1px solid rgba(var(--forge-glow), .25);
  background: rgba(5,7,8,.84);
  color: rgb(var(--forge-glow));
  font-size: 13px;
  font-weight: 950;
  line-height: 1.15;
  text-align: center;
  text-shadow: 0 1px 1px #000;
}

.enhancement-item-tooltip {
  position: relative;
  z-index: 5;
  width: min(340px, 92%);
  display: grid;
  gap: 3px;
  padding: 9px 11px;
  border: 1px solid rgba(255,255,255,.07);
  border-left: 3px solid rgb(var(--forge-glow));
  border-radius: 4px;
  background: rgba(7,8,9,.82);
  box-shadow: 0 8px 18px rgba(0,0,0,.18);
}

.enhancement-item-tooltip strong {
  color: #e3ded8;
  font-size: 10px;
}

.enhancement-item-tooltip span {
  color: #817b77;
  font-size: 8.5px;
  line-height: 1.45;
}

.enhancement-forge[data-state="charging"] .enhancement-slot-shell {
  animation: enhancementSlotCharge .92s cubic-bezier(.2,.8,.2,1);
}

.enhancement-forge[data-state="charging"] .enhancement-pickaxe {
  animation: enhancementChargeItem .92s cubic-bezier(.2,.8,.2,1);
}

.enhancement-forge[data-state="success"] .enhancement-slot-shell,
.enhancement-forge[data-state="max"] .enhancement-slot-shell {
  animation: enhancementSlotSuccess .58s cubic-bezier(.18,.8,.25,1);
}

.enhancement-forge[data-state="success"] .enhancement-pickaxe,
.enhancement-forge[data-state="max"] .enhancement-pickaxe {
  animation: enhancementSuccess .58s cubic-bezier(.18,.8,.25,1);
}

.enhancement-forge[data-state="fail"] .enhancement-pickaxe {
  animation: enhancementFail .42s ease-out;
  filter: grayscale(.28) brightness(.84);
}

.enhancement-forge[data-state="down"] .enhancement-pickaxe {
  animation: enhancementDown .5s ease-out;
}

.enhancement-forge[data-state="destroy"] .enhancement-pickaxe {
  opacity: .13;
  transform: scale(.74) rotate(4deg);
  filter: grayscale(.86) contrast(.82);
}

.enhancement-forge[data-state="destroy"] .enhancement-slot-shell {
  border-color: rgba(213,86,73,.28);
  box-shadow:
    inset 3px 3px 0 rgba(255,255,255,.025),
    inset -3px -3px 0 rgba(0,0,0,.4),
    0 0 22px rgba(213,86,73,.1);
}

.enhancement-particles {
  position: absolute;
  left: 50%;
  top: 47%;
  z-index: 8;
  width: 0;
  height: 0;
  pointer-events: none;
}

.enhancement-particles i {
  --angle: calc(var(--i) * 30deg);
  position: absolute;
  width: 5px;
  height: 5px;
  background: rgb(var(--forge-glow));
  opacity: 0;
  box-shadow: 0 0 8px rgba(var(--forge-glow), .35);
  transform:
    rotate(var(--angle))
    translateX(70px)
    rotate(calc(var(--angle) * -1));
}

.enhancement-forge[data-state="charging"] .enhancement-particles i {
  animation: enhancementParticleCharge .92s ease-out;
  animation-delay: calc(var(--i) * 16ms);
}

.enhancement-forge[data-state="success"] .enhancement-particles i,
.enhancement-forge[data-state="max"] .enhancement-particles i {
  animation: enhancementParticleBurst .7s ease-out;
  animation-delay: calc(var(--i) * 9ms);
}

.enhancement-shards {
  position: absolute;
  left: 50%;
  top: 45%;
  z-index: 9;
  width: 0;
  height: 0;
  pointer-events: none;
}

.enhancement-shards i {
  --angle: calc(var(--i) * 40deg);
  position: absolute;
  width: 10px;
  height: 7px;
  background: #52c7ca;
  box-shadow: 0 0 9px rgba(82,199,202,.3);
  animation: enhancementShard .78s cubic-bezier(.12,.78,.2,1) both;
  animation-delay: calc(var(--i) * 13ms);
}

.enhancement-result {
  min-height: 44px;
  display: grid;
  grid-template-columns: 26px minmax(0,1fr);
  align-items: center;
  gap: 8px;
  padding: 9px 11px;
  border: 1px solid rgba(255,255,255,.055);
  border-radius: 6px;
  background: rgba(255,255,255,.018);
}

.enhancement-result > span {
  display: grid;
  place-items: center;
  color: #677176;
  font-size: 17px;
}

.enhancement-result > strong {
  color: #9b918c;
  font-size: 10px;
  line-height: 1.45;
}

.enhancement-result[data-outcome="success"],
.enhancement-result[data-outcome="max"] {
  border-color: rgba(84,203,213,.18);
  background: rgba(84,203,213,.035);
}

.enhancement-result[data-outcome="success"] > span,
.enhancement-result[data-outcome="max"] > span,
.enhancement-result[data-outcome="success"] > strong,
.enhancement-result[data-outcome="max"] > strong {
  color: #8edfe5;
}

.enhancement-result[data-outcome="down"] {
  border-color: rgba(223,145,72,.15);
  background: rgba(223,145,72,.035);
}

.enhancement-result[data-outcome="down"] > span,
.enhancement-result[data-outcome="down"] > strong {
  color: #dba26e;
}

.enhancement-result[data-outcome="destroy"] {
  border-color: rgba(223,82,67,.2);
  background: rgba(223,82,67,.05);
}

.enhancement-result[data-outcome="destroy"] > span,
.enhancement-result[data-outcome="destroy"] > strong {
  color: #dd776d;
}

.enhancement-action-zone {
  display: grid;
}

.enhancement-primary {
  min-height: 60px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 3px;
  border: 1px solid rgba(85,190,196,.27);
  border-radius: 7px;
  background:
    linear-gradient(180deg, rgba(63,169,176,.12), rgba(48,130,136,.055));
  color: #c8ecee;
  font-size: 14px;
  font-weight: 900;
  cursor: pointer;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.04),
    inset 0 -2px 0 rgba(0,0,0,.2);
  transition:
    transform .12s ease,
    border-color .12s ease,
    background .12s ease;
}

.enhancement-primary:hover:not(:disabled) {
  border-color: rgba(85,190,196,.42);
  background:
    linear-gradient(180deg, rgba(63,169,176,.17), rgba(48,130,136,.075));
}

.enhancement-primary:active:not(:disabled) {
  transform: translateY(1px);
  box-shadow: inset 0 2px 0 rgba(0,0,0,.2);
}

.enhancement-primary:disabled {
  opacity: .54;
  cursor: wait;
}

.enhancement-primary span {
  color: #699da0;
  font-size: 9px;
  font-weight: 800;
}

.enhancement-primary.is-replace {
  border-color: rgba(223,82,67,.22);
  background: rgba(223,82,67,.06);
  color: #e3aaa5;
}

.enhancement-primary.is-max {
  border-color: rgba(237,188,83,.26);
  background:
    linear-gradient(180deg, rgba(237,188,83,.13), rgba(237,188,83,.045));
  color: #efd598;
}

.enhancement-side {
  display: grid;
  align-content: start;
  gap: 10px;
}

.enhancement-side > section {
  display: grid;
  gap: 10px;
  padding: 13px;
  border: 1px solid rgba(255,255,255,.06);
  border-radius: 8px;
  background: rgba(255,255,255,.014);
}

.enhancement-panel-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding-bottom: 7px;
  border-bottom: 1px solid rgba(255,255,255,.04);
}

.enhancement-panel-title > div {
  display: grid;
  gap: 1px;
}

.enhancement-panel-title small {
  color: #687073;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .07em;
}

.enhancement-panel-title strong {
  color: #bcb4af;
  font-size: 11px;
}

.enhancement-panel-title > span,
.enhancement-panel-title > b {
  padding: 4px 7px;
  border-radius: 5px;
  background: rgba(255,255,255,.03);
  color: #928a85;
  font-size: 8px;
  font-weight: 900;
}

.enhancement-panel-title > span[data-tone="safe"] {
  color: #79c6a4;
  background: rgba(80,180,130,.055);
}

.enhancement-panel-title > span[data-tone="caution"] {
  color: #d0b06f;
  background: rgba(210,170,80,.055);
}

.enhancement-panel-title > span[data-tone="danger"] {
  color: #d88f6e;
  background: rgba(210,100,70,.06);
}

.enhancement-panel-title > span[data-tone="extreme"] {
  color: #d67878;
  background: rgba(210,65,65,.065);
}

.enhancement-odds-grid,
.enhancement-record-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0,1fr));
  gap: 6px;
}

.enhancement-odds-grid > div,
.enhancement-record-grid > span {
  min-width: 0;
  display: grid;
  gap: 2px;
  padding: 9px;
  border: 1px solid rgba(255,255,255,.035);
  border-radius: 5px;
  background: rgba(0,0,0,.14);
}

.enhancement-odds-grid small,
.enhancement-record-grid small {
  color: #77706c;
  font-size: 8px;
}

.enhancement-odds-grid strong,
.enhancement-record-grid strong {
  color: #bbb2ad;
  font-size: 15px;
}

.enhancement-odds-grid [data-kind="success"] strong {
  color: #79cad1;
}

.enhancement-odds-grid [data-kind="down"] strong {
  color: #c99b6f;
}

.enhancement-odds-grid [data-kind="destroy"] strong {
  color: #c9756d;
}

.enhancement-probability > p {
  margin: 0;
  color: #746c67;
  font-size: 8.5px;
  line-height: 1.5;
}

.enhancement-probability > p strong {
  color: #a19892;
}

.enhancement-max-panel {
  display: grid;
  justify-items: center;
  gap: 3px;
  padding: 14px;
  border: 1px solid rgba(237,188,83,.13);
  border-radius: 6px;
  background: rgba(237,188,83,.035);
}

.enhancement-max-panel strong {
  color: #e2c57e;
  font-size: 18px;
}

.enhancement-max-panel span {
  color: #897b62;
  font-size: 9px;
}

.enhancement-links > div:last-child {
  display: grid;
  gap: 5px;
}

.enhancement-links a {
  min-height: 38px;
  display: grid;
  grid-template-columns: 24px minmax(0,1fr) 16px;
  align-items: center;
  gap: 6px;
  padding: 7px 8px;
  border: 1px solid rgba(255,255,255,.04);
  border-radius: 5px;
  background: rgba(0,0,0,.09);
  color: inherit;
  text-decoration: none;
}

.enhancement-links a:hover {
  border-color: rgba(70,211,222,.14);
  background: rgba(70,211,222,.022);
}

.enhancement-links a > span {
  color: #6db9c0;
  font-size: 12px;
  text-align: center;
}

.enhancement-links a strong {
  color: #a19994;
  font-size: 9px;
}

.enhancement-links a b {
  color: #697376;
  font-size: 9px;
}

html[data-theme="light"] .wiki-enhancement-lab {
  border-color: rgba(78,68,62,.1);
  background: #f4f1ec;
}

html[data-theme="light"] .enhancement-forge {
  border-color: rgba(78,68,62,.09);
  background: #ebe9e4;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.68);
}

html[data-theme="light"] .enhancement-slot-shell {
  border-color: rgba(63,58,54,.2);
  background: linear-gradient(135deg, #bbb8b2, #908d88);
}

html[data-theme="light"] .enhancement-slot {
  background: #d6d3cd;
}

html[data-theme="light"] .enhancement-slot-inner {
  background: #efede8;
}

html[data-theme="light"] .enhancement-item-tooltip {
  border-color: rgba(78,68,62,.12);
  background: rgba(255,255,255,.72);
}

html[data-theme="light"] .enhancement-item-tooltip strong,
html[data-theme="light"] .enhancement-lab-head h2,
html[data-theme="light"] .enhancement-panel-title strong,
html[data-theme="light"] .enhancement-item-name,
html[data-theme="light"] .enhancement-record-grid strong,
html[data-theme="light"] .enhancement-links a strong {
  color: #5c514c;
}

html[data-theme="light"] .enhancement-side > section,
html[data-theme="light"] .enhancement-result {
  border-color: rgba(78,68,62,.09);
  background: rgba(255,255,255,.42);
}

html[data-theme="light"] .enhancement-odds-grid > div,
html[data-theme="light"] .enhancement-record-grid > span,
html[data-theme="light"] .enhancement-links a {
  background: rgba(255,255,255,.58);
}

@keyframes enhancementEnchantedSheen {
  0%, 22% { transform: translateX(-28%); opacity: .18; }
  50% { transform: translateX(16%); opacity: .34; }
  78%, 100% { transform: translateX(34%); opacity: .16; }
}

@keyframes enhancementSlotCharge {
  0% { transform: scale(1); }
  36% { transform: scale(.975); }
  68% {
    transform: scale(1.025);
    border-color: rgba(var(--forge-glow), .48);
    box-shadow:
      inset 3px 3px 0 rgba(255,255,255,.04),
      inset -3px -3px 0 rgba(0,0,0,.4),
      0 0 28px rgba(var(--forge-glow), .2);
  }
  100% { transform: scale(1); }
}

@keyframes enhancementSlotSuccess {
  0% { transform: scale(.985); }
  38% {
    transform: scale(1.035);
    box-shadow:
      inset 3px 3px 0 rgba(255,255,255,.055),
      inset -3px -3px 0 rgba(0,0,0,.4),
      0 0 34px rgba(var(--forge-glow), .32);
  }
  100% { transform: scale(1); }
}

@keyframes enhancementChargeItem {
  0% { transform: translateY(1px) scale(1); filter: brightness(1); }
  30% { transform: translateY(3px) scale(.965); filter: brightness(.9); }
  66% {
    transform: translateY(-2px) scale(1.07);
    filter:
      brightness(1.38)
      drop-shadow(0 0 21px rgba(var(--forge-glow),.35));
  }
  100% { transform: translateY(1px) scale(1); filter: brightness(1); }
}

@keyframes enhancementSuccess {
  0% { transform: translateY(1px) scale(.96); }
  36% {
    transform: translateY(-3px) scale(1.11);
    filter:
      brightness(1.48)
      drop-shadow(0 0 28px rgba(var(--forge-glow),.42));
  }
  100% { transform: translateY(1px) scale(1); }
}

@keyframes enhancementFail {
  0%,100% { transform: translateX(0) translateY(1px); }
  22% { transform: translateX(-6px) translateY(2px); }
  44% { transform: translateX(5px) translateY(0); }
  66% { transform: translateX(-3px) translateY(2px); }
}

@keyframes enhancementDown {
  0% { transform: translateY(1px); }
  38% { transform: translateY(8px) scale(.96); filter: brightness(.72); }
  100% { transform: translateY(1px); }
}

@keyframes enhancementParticleCharge {
  0% {
    opacity: 0;
    transform: rotate(var(--angle)) translateX(105px) scale(.4);
  }
  45% { opacity: .85; }
  100% {
    opacity: 0;
    transform: rotate(var(--angle)) translateX(38px) scale(1.1);
  }
}

@keyframes enhancementParticleBurst {
  0% {
    opacity: 1;
    transform: rotate(var(--angle)) translateX(38px) scale(1.1);
  }
  100% {
    opacity: 0;
    transform: rotate(var(--angle)) translateX(126px) scale(.2);
  }
}

@keyframes enhancementShard {
  0% {
    opacity: 1;
    transform: rotate(var(--angle)) translateX(18px) rotate(0deg);
  }
  100% {
    opacity: 0;
    transform: rotate(var(--angle)) translateX(112px) rotate(160deg);
  }
}

@media (max-width: 900px) {
  .enhancement-main-grid {
    grid-template-columns: 1fr;
  }

  .enhancement-side {
    grid-template-columns: repeat(3, minmax(0,1fr));
