  position: absolute;
  z-index: 5;
  inset: 0;
  pointer-events: none;
}

.enhancement-pickaxe-runes i {
  position: absolute;
  width: 4px;
  height: 4px;
  background: rgb(var(--forge-glow));
  opacity: .45;
  box-shadow: 0 0 7px rgba(var(--forge-glow), .32);
}

.enhancement-pickaxe-runes i:nth-child(1) { left: 18%; top: 30%; }
.enhancement-pickaxe-runes i:nth-child(2) { right: 18%; top: 22%; }
.enhancement-pickaxe-runes i:nth-child(3) { right: 28%; bottom: 24%; }
.enhancement-pickaxe-runes i:nth-child(4) { left: 34%; bottom: 17%; }

.enhancement-forge[data-tier="mid"] .enhancement-pickaxe-runes i {
  opacity: .42;
}

.enhancement-forge[data-tier="high"] .enhancement-pickaxe-runes i {
  width: 5px;
  height: 5px;
  opacity: .62;
  animation: enhancementRunePulse 1.8s ease-in-out infinite alternate;
}

.enhancement-forge[data-tier="extreme"] .enhancement-pickaxe-runes i {
  width: 5px;
  height: 5px;
  opacity: .78;
  animation: enhancementRunePulse 1.15s ease-in-out infinite alternate;
}

.enhancement-forge[data-tier="legendary"] .enhancement-pickaxe-runes i {
  width: 6px;
  height: 6px;
  opacity: .92;
  animation: enhancementRunePulse .9s ease-in-out infinite alternate;
}

@keyframes enhancementRunePulse {
  from { transform: scale(.75); opacity: .35; }
  to { transform: scale(1.35); opacity: .95; }
}

/* Stage-specific pacing: early upgrades are fast; late upgrades carry more tension. */
.enhancement-forge[data-state="charging"][data-tier="base"] .enhancement-slot-shell,
.enhancement-forge[data-state="charging"][data-tier="base"] .enhancement-pickaxe,
.enhancement-forge[data-state="charging"][data-tier="base"] .enhancement-particles i {
  animation-duration: .65s;
}

.enhancement-forge[data-state="charging"][data-tier="mid"] .enhancement-slot-shell,
.enhancement-forge[data-state="charging"][data-tier="mid"] .enhancement-pickaxe,
.enhancement-forge[data-state="charging"][data-tier="mid"] .enhancement-particles i {
  animation-duration: .8s;
}

.enhancement-forge[data-state="charging"][data-tier="high"] .enhancement-slot-shell,
.enhancement-forge[data-state="charging"][data-tier="high"] .enhancement-pickaxe,
.enhancement-forge[data-state="charging"][data-tier="high"] .enhancement-particles i {
  animation-duration: .98s;
