.enhancement-forge[data-state="charging"][data-tier="extreme"] .enhancement-slot-shell,
.enhancement-forge[data-state="charging"][data-tier="extreme"] .enhancement-pickaxe,
.enhancement-forge[data-state="charging"][data-tier="extreme"] .enhancement-particles i {
  animation-duration: 1.2s;
}

.enhancement-forge[data-final-attempt="true"][data-state="charging"] .enhancement-slot-shell,
.enhancement-forge[data-final-attempt="true"][data-state="charging"] .enhancement-pickaxe,
.enhancement-forge[data-final-attempt="true"][data-state="charging"] .enhancement-particles i {
  animation-duration: 1.45s;
}

.enhancement-forge[data-final-attempt="true"][data-state="charging"]::after {
  content: '';
  position: absolute;
  z-index: -1;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 50% 47%, rgba(181,106,221,.11), transparent 34%),
    rgba(0,0,0,.12);
  animation: enhancementFinalTension 1.45s ease-in-out both;
