/* === 2026-09-26 enhancement lab forge feedback v6 === */
/*
 * v6 focuses on three things:
 * 1) no accidental vertical expansion / clipped lower controls,
 * 2) forge-like impact feedback that matches the new metal sounds,
 * 3) clearer odds and run information without adding visual noise.
 */
.wiki-enhancement-lab {
  gap: 10px;
  padding: 14px;
  overflow: visible;
}

.enhancement-lab-head {
  gap: 14px;
  padding-bottom: 9px;
}

.enhancement-lab-head > div:first-child {
  gap: 2px;
}

.enhancement-lab-head h2 {
  font-size: clamp(20px, 2.4vw, 25px);
}

.enhancement-lab-head > div:first-child > span {
  font-size: 9.5px;
  line-height: 1.45;
}

/*
 * Do not assign semantic children to numbered grid rows.
 * The mobile odds row is display:none on desktop, which previously shifted
 * every following child into the wrong explicit row and created a large
 * empty band above the action button.
 */
.enhancement-forge {
  min-height: 0;
  grid-template-rows: none;
  grid-auto-rows: auto;
  gap: 7px;
  padding: 12px;
}

.enhancement-item-stage {
  min-height: 218px;
  gap: 7px;
  padding: 3px 0 1px;
}

.enhancement-slot-shell {
  width: 156px;
  height: 156px;
  padding: 6px;
}

.enhancement-slot {
  padding: 5px;
}

.enhancement-pickaxe {
  width: 126px;
  height: 126px;
}

.enhancement-item-tooltip {
  width: min(320px, 88%);
  gap: 2px;
  padding: 6px 9px;
}

.enhancement-item-tooltip strong {
  font-size: 9px;
}

.enhancement-item-tooltip span {
  font-size: 7.5px;
  line-height: 1.35;
}

.enhancement-level-row > strong {
  font-size: 29px;
}

.enhancement-level-row {
  min-height: 32px;
