/* The post-run card lives below the fixed action button, so it can collapse safely. */
.enhancement-run-result-slot {
  height: auto;
  min-height: 0;
  overflow: visible;
}

.enhancement-run-result-placeholder {
  display: none;
}

.enhancement-run-result {
  min-height: 56px;
