/*
 * Forge visual language:
 * - warm, short sparks for physical hammer impacts
 * - magical colour only becomes a secondary layer at high enhancement
 * - effects stay attached to the pickaxe coordinate system
 */
.enhancement-pickaxe::after {
  content: '';
  position: absolute;
  z-index: 8;
  left: 50%;
  top: 48%;
  width: 62px;
  height: 62px;
  border-radius: 50%;
  pointer-events: none;
  opacity: 0;
  transform: translate(-50%, -50%) scale(.45);
  background:
    radial-gradient(
      circle,
      rgba(255,225,164,.72) 0 5%,
      rgba(235,160,73,.27) 18%,
      rgba(220,126,43,.08) 40%,
      transparent 68%
    );
}

.enhancement-particles i {
  width: 9px;
  height: 2px;
  border-radius: 1px;
  background: #e6a04d;
  box-shadow:
    0 0 4px rgba(230,160,77,.55),
    0 0 8px rgba(220,112,42,.22);
}

.enhancement-forge[data-tier="high"] .enhancement-particles i {
  background: linear-gradient(90deg, #e5a04d 0 62%, rgb(var(--forge-glow)) 63%);
}

.enhancement-forge[data-tier="extreme"] .enhancement-particles i {
  background: linear-gradient(90deg, #e2a052 0 50%, rgb(var(--forge-glow)) 51%);
}

.enhancement-forge[data-tier="legendary"] .enhancement-particles i {
  background: #edc36f;
  box-shadow:
    0 0 5px rgba(237,195,111,.68),
    0 0 10px rgba(237,188,83,.26);
}

.enhancement-forge[data-state="charging"] .enhancement-pickaxe::after {
  animation: enhancementForgeImpactFlash .52s ease-out both;
}

.enhancement-forge[data-state="success"] .enhancement-pickaxe::after,
.enhancement-forge[data-state="max"] .enhancement-pickaxe::after {
  animation: enhancementForgeResultFlash .58s ease-out both;
}

@keyframes enhancementForgeImpactFlash {
  0%, 10% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(.35);
  }
  18% {
    opacity: .88;
    transform: translate(-50%, -50%) scale(.72);
  }
  42% {
    opacity: .2;
    transform: translate(-50%, -50%) scale(1.08);
  }
  100% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(1.24);
  }
}

@keyframes enhancementForgeResultFlash {
  0% {
    opacity: .76;
    transform: translate(-50%, -50%) scale(.46);
  }
  30% {
    opacity: .5;
    transform: translate(-50%, -50%) scale(.9);
  }
  100% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(1.35);
  }
}

