const GROUPS = [
  { key: 'start', icon: '🧭', title: '시작하기', description: '처음 접속하기 전에 확인할 필수 안내' },
  { key: 'content', icon: '🎮', title: '주요 콘텐츠', description: '채광부터 도감·파쿠르·미니게임까지' },
