export function WikiHomePlayground({ pages }: { pages: PlaygroundPage[] }) {
  const [open, setOpen] = useState(false)
  const [loadExtras, setLoadExtras] = useState(false)
  const readyCount = pages.filter((page) => page.status !== 'draft').length

  useEffect(() => {
    const openFromHash = () => {
      const hash = window.location.hash
      if (
        hash === '#wiki-explore' ||
        hash === '#enhancement-lab' ||
        hash === '#wiki-survival-log-title' ||
        hash === '#reading-explorer-title' ||
        hash === '#wiki-adventure-title'
      ) {
        setOpen(true)
        if (
          hash === '#wiki-survival-log-title' ||
          hash === '#reading-explorer-title' ||
          hash === '#wiki-adventure-title'
        ) {
          setLoadExtras(true)
        }
        if (hash !== '#wiki-explore') {
          window.setTimeout(() => {
            document.querySelector(hash)?.scrollIntoView({
              behavior: 'smooth',
              block: 'start'
            })
          }, 120)
        }
      }
    }

    openFromHash()
    window.addEventListener('hashchange', openFromHash)
    return () => window.removeEventListener('hashchange', openFromHash)
  }, [])

  useEffect(() => {
    if (!open || loadExtras) return

    const timer = window.setTimeout(() => {
      setLoadExtras(true)
    }, 700)

    return () => window.clearTimeout(timer)
  }, [loadExtras, open])

  return (
    <section
      className={`home-playground ${open ? 'is-open' : ''}`}
      id="wiki-explore"
      aria-labelledby="home-playground-title"
    >
      <div className="home-playground-intro">
        <div className="home-playground-icon" aria-hidden="true">🎮</div>
        <div className="home-playground-copy">
          <p>WIKI ADVENTURE</p>
          <h2 id="home-playground-title">가이드를 읽으면서 같이 놀아보세요</h2>
          <span>
            운세·성향 테스트·미션·완독 기록·보물찾기·주간 보스를 하나의 탐험 기록으로 연결했습니다.
          </span>
          <div className="home-playground-chips" aria-label="위키 탐험 기능">
            <b>📚 {readyCount}개 공개 가이드</b>
            <b>🏆 완독·업적</b>
            <b>⚒️ 강화 체험소</b>
            <b>🎲 PLAY ZONE</b>
            <b>⚔️ 주간 보스</b>
          </div>
        </div>
        <button
          type="button"
          className="home-playground-toggle"
          aria-expanded={open}
          aria-controls="home-playground-content"
          onClick={() => setOpen((value) => !value)}
        >
          {open ? '탐험 접기' : '위키 탐험 시작'}
          <span aria-hidden="true">{open ? '↑' : '→'}</span>
        </button>
      </div>

      {open && (
        <div className="home-playground-content" id="home-playground-content">
          <WikiEnhancementLab pages={pages} />
          <WikiFunZone pages={pages} />
          {loadExtras ? (
            <>
              <WikiSurvivalLog pages={pages} />
              <WikiReadingExplorer pages={pages} />
              <WikiAdventureHub pages={pages} />
            </>
          ) : (
            <PlaygroundLoading label="추가 탐험 기능을 여유 시간에 불러오는 중" />
          )}
        </div>
      )}
    </section>
  )
}

'use client'

import Link from 'next/link'
import { useEffect, useRef } from 'react'

import { iconForTitle } from '@/lib/wiki-taxonomy'
import type { WikiContentStatus } from '@/lib/wiki-ux'
import { withBasePath } from '@/lib/url-utils'
import faqEntries from '@/data/wiki-verified-faq.json'

type QuickPage = {
  pageId: string
  title: string
  status?: WikiContentStatus
}

const QUICK_RULE_QUESTIONS = [
  '재입주할 수 있나요?',
  '강화된 아이템을 다른 사람과 주고받아도 되나요?',
  '무한용암은 몇 개까지 만들 수 있나요?',
  '호퍼·팜·주민거래 같은 자동화가 가능한가요?'
]

const QUICK_RULES = QUICK_RULE_QUESTIONS
  .map((question) =>
    faqEntries.find((entry) => entry.question === question)
  )
  .filter(Boolean)

const QUICK_TITLES = [
  '서버규칙',
  '기초설정(뉴비필독)',
  '채광',
  '땅 구매',
  '장비수리',
  '장비강화',
  '빚 갚기',
  '신용등급'
]

export function WikiMobileQuickView({
  pages,
  onClose,
  onOpenSearch
}: {
  pages: QuickPage[]
  onClose: () => void
  onOpenSearch: () => void
}) {
  const sheetRef = useRef<HTMLElement>(null)
  const closeRef = useRef<HTMLButtonElement>(null)

  const readyPages = QUICK_TITLES
    .map((title) => pages.find((page) => page.title === title))
    .filter(
      (page): page is QuickPage =>
        Boolean(page && page.status !== 'draft')
    )

  useEffect(() => {
    const previousOverflow = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    const frame = requestAnimationFrame(() => closeRef.current?.focus())

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        event.preventDefault()
        onClose()
        return
      }

      if (event.key !== 'Tab' || !sheetRef.current) return
      const focusable = Array.from(
        sheetRef.current.querySelectorAll<HTMLElement>(
          'button, a[href], [tabindex]:not([tabindex="-1"])'
        )
      ).filter((element) => !element.hasAttribute('disabled'))

      if (!focusable.length) return
      const first = focusable[0]
      const last = focusable[focusable.length - 1]

      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault()
        last.focus()
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault()
        first.focus()
      }
    }

    window.addEventListener('keydown', onKeyDown)
    return () => {
      cancelAnimationFrame(frame)
      window.removeEventListener('keydown', onKeyDown)
      document.body.style.overflow = previousOverflow
    }
  }, [onClose])

  return (
    <div
      className="mobile-quick-backdrop"
      role="presentation"
      onMouseDown={(event) => {
        if (event.currentTarget === event.target) onClose()
      }}
    >
      <section
        ref={sheetRef}
        className="mobile-quick-sheet"
        role="dialog"
        aria-modal="true"
        aria-labelledby="mobile-quick-title"
      >
        <div className="mobile-quick-handle" aria-hidden="true" />
        <header>
          <div>
            <small>QUICK INFO</small>
            <strong id="mobile-quick-title">게임 중 빠른보기</strong>
            <span>자주 찾는 핵심 가이드를 1번에 열어보세요.</span>
          </div>
          <button
            ref={closeRef}
            type="button"
            aria-label="빠른보기 닫기"
            onClick={onClose}
          >
            ×
          </button>
        </header>

        <section className="mobile-quick-rules" aria-labelledby="mobile-quick-rules-title">
          <div className="mobile-quick-rules-head">
            <strong id="mobile-quick-rules-title">지금 바로 보는 핵심 규칙</strong>
            <Link
              href={withBasePath('/guide/faq/')}
              onClick={onClose}
              data-wiki-event="wiki_mobile_quick_faq"
              data-wiki-section="mobile-quick-view"
              data-wiki-target="faq"
              data-wiki-status="verified"
            >
              전체 FAQ →
            </Link>
          </div>
          <div className="mobile-quick-rule-grid">
            {QUICK_RULES.map((entry) => (
              <article key={entry!.question}>
                <small>{entry!.question}</small>
                <strong>{entry!.answer}</strong>
              </article>
            ))}
          </div>
        </section>

        <button
          type="button"
          className="mobile-quick-search"
          onClick={() => {
            onClose()
            requestAnimationFrame(onOpenSearch)
          }}
        >
          <span aria-hidden="true">⌕</span>
          <strong>질문이나 키워드 바로 검색</strong>
          <b aria-hidden="true">→</b>
        </button>

        <nav className="mobile-quick-grid" aria-label="빠른 가이드">
          {readyPages.map((page) => (
            <Link
              key={page.pageId}
              href={withBasePath(`/page/${page.pageId}/`)}
              onClick={onClose}
              data-wiki-event="wiki_mobile_quick_navigate"
              data-wiki-section="mobile-quick-view"
              data-wiki-target={page.title}
              data-wiki-status={page.status || 'ready'}
            >
              <span aria-hidden="true">{iconForTitle(page.title)}</span>
              <strong>{page.title}</strong>
              <b aria-hidden="true">→</b>
            </Link>
          ))}
        </nav>

        {readyPages.length < 5 && (
          <p className="mobile-quick-note">
            아직 준비 중인 핵심 가이드는 내용이 보강되는 즉시 이 목록에 자동으로 추가됩니다.
          </p>
        )}
      </section>
    </div>
  )
}

'use client'

import Link from 'next/link'

import type { WikiContentStatus } from '@/lib/wiki-content-status'
import { iconForTitle } from '@/lib/wiki-taxonomy'
import { withBasePath } from '@/lib/url-utils'
import { wikiGuidePath } from '@/lib/wiki-routes'

const PREFETCH_TITLES = new Set(['서버규칙', '기초설정(뉴비필독)', '채광'])

export type WikiNavigationPage = {
  pageId: string
  title: string
  category?: string
  status?: WikiContentStatus
}

export type WikiNavigationTocItem = {
  id: string
  text: string
  level: number
}

export function WikiNavigation({
  pages,
  currentPageId,
  currentCategory,
  openMobileCategories,
  onToggleMobileCategory,
  menuOpen,
  onCloseMenu,
  home,
  toc,
  activeTocId,
  onNavigateToc,
  readingProgress,
  sidebarCollapsed,
  onToggleSidebar,
  onOpenSearch,
  categoryForPage
}: {
  pages: WikiNavigationPage[]
  currentPageId?: string | null
  currentCategory: string
  openMobileCategories: string[]
  onToggleMobileCategory: (category: string) => void
  menuOpen: boolean
  onCloseMenu: () => void
  home: boolean
  toc: WikiNavigationTocItem[]
  activeTocId: string
  onNavigateToc: (id: string) => void
  readingProgress: number
  sidebarCollapsed: boolean
  onToggleSidebar: () => void
  onOpenSearch: () => void
  categoryForPage: (page: WikiNavigationPage) => string
}) {
  return (
    <>
      <aside className={`wiki-sidebar ${menuOpen ? 'is-open' : ''}`}>
        <div className="sidebar-head">
          <strong>문서 탐색</strong>
          <span>{pages.length}개</span>
        </div>

        {!home && (
          <button
            className="wiki-search wiki-search-trigger"
            type="button"
            aria-keyshortcuts="Control+K Meta+K /"
            onClick={onOpenSearch}
          >
            <span>⌕</span>
            <span>전체 문서 검색</span>
            <kbd>⌘K</kbd>
          </button>
        )}

        <div className="sidebar-primary-links">
          <Link
            className="sidebar-home"
            href={withBasePath('/')}
            prefetch={false}
            onClick={onCloseMenu}
            data-wiki-event="wiki_sidebar_navigate"
            data-wiki-section="primary"
            data-wiki-target="home"
            data-wiki-status="ready"
          >
            <span>🏠</span>
            위키 홈
          </Link>
        </div>

        <nav className="toc-list">
          <div className="global-page-list">
            <span className="nav-section-label">전체 문서</span>
            {['시작하기', '주요 콘텐츠', '성장 · 경제'].map((group) => {
              const groupPages = pages.filter(
                (page) => categoryForPage(page) === group
              )
              const readyPages = groupPages.filter(
                (page) => page.status !== 'draft'
              )
              const draftPages = groupPages.filter(
                (page) => page.status === 'draft'
              )

              if (!groupPages.length) return null

              const pageLink = (page: WikiNavigationPage, draft = false) => {
                const current =
                  Boolean(currentPageId) &&
                  page.pageId.replaceAll('-', '') ===
                    currentPageId!.replaceAll('-', '')

                return (
                  <Link
                    key={page.pageId}
                    href={withBasePath(wikiGuidePath(page))}
                    prefetch={!draft && PREFETCH_TITLES.has(page.title)}
                    onClick={onCloseMenu}
                    className={`global-page-link ${current ? 'is-current' : ''} ${draft ? 'is-draft' : ''}`}
                    aria-current={current ? 'page' : undefined}
                    aria-label={draft ? `${page.title} — 준비 중인 문서` : undefined}
                    data-wiki-event="wiki_sidebar_navigate"
                    data-wiki-section={group}
                    data-wiki-target={page.title}
                    data-wiki-status={page.status || 'unknown'}
                  >
                    <span className="sidebar-page-icon" aria-hidden="true">
                      {iconForTitle(page.title)}
                    </span>
                    <span className="global-page-copy">
                      <strong>{page.title}</strong>
                      {draft && (
                        <em className="sidebar-draft-badge">준비 중</em>
                      )}
                    </span>
                  </Link>
                )
              }

              return (
                <section
                  className={`sidebar-category ${openMobileCategories.includes(group) ? 'is-mobile-open' : ''}`}
                  key={group}
                >
                  <div className="sidebar-category-head sidebar-category-head-static">
                    <strong>{group}</strong>
                    <span className="sidebar-category-meta">
                      <span>{readyPages.length}</span>
                    </span>
                  </div>
                  <button
                    type="button"
                    className="sidebar-category-head sidebar-category-head-toggle"
                    aria-expanded={openMobileCategories.includes(group)}
                    onClick={() => onToggleMobileCategory(group)}
                  >
                    <strong>{group}</strong>
                    <span className="sidebar-category-meta">
                      <span>{readyPages.length}</span>
                      <b aria-hidden="true">⌄</b>
                    </span>
                  </button>
                  <div className="sidebar-category-links">
                    {readyPages.map((page) => pageLink(page))}
                  </div>
                  {draftPages.length > 0 && (
                    <details className="sidebar-draft-group">
                      <summary>
                        <span>준비 중</span>
                        <b>{draftPages.length}</b>
                      </summary>
                      <div className="sidebar-category-links is-draft-list">
                        {draftPages.map((page) => pageLink(page, true))}
                      </div>
                    </details>
                  )}
                </section>
              )
            })}
          </div>

          <div className="current-toc mobile-current-toc">
            <span className="nav-section-label">
              현재 페이지{currentCategory ? ` · ${currentCategory}` : ''}
            </span>
            {toc.length ? (
              toc.map((item) => (
                <button
                  key={item.id}
                  type="button"
                  className={`toc-item level-${item.level} ${activeTocId === item.id ? 'is-active' : ''}`}
                  aria-current={activeTocId === item.id ? 'location' : undefined}
                  onClick={() => onNavigateToc(item.id)}
                >
                  <span>{iconForTitle(item.text)}</span>
                  <span>{item.text}</span>
                </button>
              ))
            ) : (
              <p className="toc-empty">현재 페이지 목차가 없습니다.</p>
            )}
