import Link from 'next/link'

import type { NotionIndexPage } from '@/lib/notion-index'
import { categoryAnchorForTitle, categoryTitleForPage } from '@/lib/wiki-taxonomy'
import { withBasePath } from '@/lib/url-utils'
import { wikiGuidePath } from '@/lib/wiki-routes'

function formatDate(value: string | null) {
  if (!value) return null
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return null
  return new Intl.DateTimeFormat('ko-KR', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).format(date)
}

export function WikiPageNavigation({
  current,
  pages,
  mode = 'context'
}: {
  current: NotionIndexPage | null
  pages: NotionIndexPage[]
  mode?: 'context' | 'siblings'
}) {
  if (!current) return null

  const currentIndex = pages.findIndex((page) => page.pageId === current.pageId)
  const previous = currentIndex > 0 ? pages[currentIndex - 1] : null
  const next =
    currentIndex >= 0 && currentIndex < pages.length - 1
      ? pages[currentIndex + 1]
      : null
  const category = categoryTitleForPage(current.title)
  const updatedAt = formatDate(current.lastEdited)

  if (mode === 'siblings') {
    if (!previous && !next) return null

    return (
      <nav className="page-siblings page-siblings-bottom" aria-label="이전 및 다음 문서">
        {previous ? (
          <Link href={withBasePath(wikiGuidePath(previous))}>
            <small>← 이전 문서</small>
            <strong>{previous.title}</strong>
          </Link>
        ) : (
          <span />
        )}

        {next ? (
          <Link
            href={withBasePath(wikiGuidePath(next))}
            className="page-sibling-next"
          >
            <small>다음 문서 →</small>
            <strong>{next.title}</strong>
          </Link>
        ) : (
          <span />
        )}
      </nav>
    )
  }

  return (
    <div className="page-context">
      <nav className="breadcrumbs" aria-label="현재 위치">
        <Link href={withBasePath('/')} prefetch={false}>위키 홈</Link>
        <span>›</span>
        <Link href={withBasePath(`/#${categoryAnchorForTitle(current.title)}`)} prefetch={false}>{category}</Link>
        <span>›</span>
        <strong>{current.title}</strong>
      </nav>
      {updatedAt && <span className="page-updated">최근 수정 {updatedAt}</span>}
    </div>
  )
}

'use client'

import Link from 'next/link'
import { track } from '@vercel/analytics'
import { useEffect, useMemo, useState } from 'react'

import {
  dailyExplorationQuest,
  readingCollectionSets,
  unreadRecommendations
} from '@/lib/wiki-reading-game'
import { iconForTitle } from '@/lib/wiki-taxonomy'
import type { WikiContentStatus } from '@/lib/wiki-ux'
import { withBasePath } from '@/lib/url-utils'
import { readWikiStringArray } from '@/lib/wiki-client-state'

type ExplorerPage = {
  pageId: string
  title: string
  category?: string
  status?: WikiContentStatus
}

function readStoredPages() {
  return readWikiStringArray('readPages')
}

function normalize(value: string) {
  return value.replaceAll('-', '')
}

export function WikiReadingExplorer({
  pages
}: {
  pages: ExplorerPage[]
}) {
  const readyPages = useMemo(
    () => pages.filter((page) => page.status !== 'draft'),
    [pages]
  )
  const [readIds, setReadIds] = useState<string[]>([])
  const [dateKey, setDateKey] = useState('')

  useEffect(() => {
    setDateKey(
      new Intl.DateTimeFormat('en-CA', {
        timeZone: 'Asia/Seoul',
        year: 'numeric',
        month: '2-digit',
        day: '2-digit'
      }).format(new Date())
    )

    const refresh = () => setReadIds(readStoredPages())
    refresh()
    window.addEventListener('storage', refresh)
    window.addEventListener('justserver3:read-pages', refresh)
    return () => {
      window.removeEventListener('storage', refresh)
      window.removeEventListener('justserver3:read-pages', refresh)
    }
  }, [])

  const readSet = useMemo(
    () => new Set(readIds.map(normalize)),
    [readIds]
  )
  const quest = dailyExplorationQuest(
    readyPages,
    dateKey || 'loading'
  )
  const questDone =
    quest.pages.length > 0 &&
    quest.pages.every((page) => readSet.has(normalize(page.pageId)))
  const recommendations = unreadRecommendations(readyPages, readIds, 3)
  const sets = readingCollectionSets(readyPages, readIds)
  const categories = ['시작하기', '주요 콘텐츠', '성장 · 경제']

  return (
    <section
      className="wiki-reading-explorer"
      aria-labelledby="reading-explorer-title"
    >
      <div className="reading-explorer-head">
        <div>
          <p>READ & EXPLORE</p>
          <h2 id="reading-explorer-title">읽을수록 열리는 위키 탐험</h2>
          <span>
            재미 기능을 실제 가이드 완독과 연결했습니다. 오늘의 의뢰부터 시작해보세요.
          </span>
        </div>
        <b>
          📚 {readyPages.filter((page) => readSet.has(normalize(page.pageId))).length}/{readyPages.length} 완독
        </b>
      </div>

      <div className="reading-explorer-top">
        <article className={`reading-daily-quest ${questDone ? 'is-complete' : ''}`}>
          <header>
            <span aria-hidden="true">{quest.icon}</span>
            <div>
              <small>DAILY EXPLORATION QUEST</small>
              <strong>{quest.title}</strong>
              <p>{quest.description}</p>
            </div>
            <b>{questDone ? '의뢰 완료 ✓' : `${quest.pages.filter((page) => readSet.has(normalize(page.pageId))).length}/${quest.pages.length}`}</b>
          </header>

          <div className="reading-quest-steps">
            {quest.pages.map((page, index) => {
              const complete = readSet.has(normalize(page.pageId))
              return (
                <Link
                  key={page.pageId}
                  href={withBasePath(`/page/${page.pageId}/`)}
                  className={complete ? 'is-complete' : ''}
                  onClick={() =>
                    track('wiki_exploration_quest_navigate', {
                      step: String(index + 1),
                      complete: complete ? 'yes' : 'no'
                    })
                  }
                >
                  <span>{complete ? '✓' : index + 1}</span>
                  <div>
                    <small>{page.category || '추천 가이드'}</small>
                    <strong>{page.title}</strong>
                  </div>
                  <b>→</b>
                </Link>
              )
            })}
          </div>
        </article>

        <article className="reading-unread-card">
          <header>
            <div>
              <small>NEXT UNREAD</small>
              <strong>아직 안 읽은 추천 가이드</strong>
            </div>
            <b>{recommendations.length ? '다음 목표' : '완독!'}</b>
          </header>

          {recommendations.length ? (
            <div className="reading-unread-list">
              {recommendations.map((page) => (
                <Link
                  key={page.pageId}
                  href={withBasePath(`/page/${page.pageId}/`)}
                  onClick={() =>
                    track('wiki_unread_recommendation_navigate', {
                      category: page.category || 'unknown'
                    })
                  }
                >
                  <span aria-hidden="true">{iconForTitle(page.title)}</span>
                  <div>
                    <small>{page.category}</small>
                    <strong>{page.title}</strong>
                  </div>
                  <b>읽기 →</b>
                </Link>
              ))}
            </div>
          ) : (
            <div className="reading-unread-complete">
              🏆 현재 준비된 가이드를 모두 완독했습니다.
            </div>
          )}
        </article>
      </div>

      <div className="reading-collection-sets">
        {sets.map((set) => (
          <article key={set.category} className={set.complete ? 'is-complete' : ''}>
            <span className="reading-set-icon" aria-hidden="true">
              {set.icon}
            </span>
            <div>
              <small>COLLECTION SET</small>
              <strong>{set.title}</strong>
              <p>{set.description}</p>
              <i aria-hidden="true">
                <i style={{ width: `${set.percent}%` }} />
              </i>
              <em>
                {set.complete
                  ? '배지 획득 ✓'
                  : `${set.count}/${set.total} 완독 · ${set.percent}%`}
              </em>
            </div>
          </article>
        ))}
      </div>

      <div className="reading-map">
        <header>
          <div>
            <small>WIKI EXPLORATION MAP</small>
            <strong>위키 탐험 지도</strong>
          </div>
          <span>밝은 노드는 완독한 문서입니다.</span>
        </header>

        <div className="reading-map-routes">
          {categories.map((category, categoryIndex) => {
            const categoryPages = readyPages.filter(
              (page) => page.category === category
            )
            if (!categoryPages.length) return null

            return (
              <div className="reading-map-route" key={category}>
                <div className="reading-map-category">
                  <span>{categoryIndex + 1}</span>
                  <strong>{category}</strong>
                </div>
                <div className="reading-map-nodes">
                  {categoryPages.map((page) => {
                    const complete = readSet.has(normalize(page.pageId))
                    return (
                      <Link
                        key={page.pageId}
                        href={withBasePath(`/page/${page.pageId}/`)}
                        className={complete ? 'is-complete' : ''}
                        title={complete ? `${page.title} · 완독` : `${page.title} · 미완독`}
                      >
                        <span aria-hidden="true">
                          {complete ? '✓' : iconForTitle(page.title)}
                        </span>
                        <strong>{page.title}</strong>
                      </Link>
                    )
                  })}
                </div>
              </div>
            )
          })}
        </div>
      </div>
    </section>
  )
}

'use client'

import Link from 'next/link'
import { track } from '@vercel/analytics'
import { useEffect, useMemo, useState } from 'react'

import type { ReadingQuiz } from '@/lib/wiki-reading-game'
import {
  normalizeSurvivalRecord,
  recordSurvivalActivity,
  seoulDateKey
} from '@/lib/wiki-survival'
import { withBasePath } from '@/lib/url-utils'
import {
  readWikiStateValue,
  readWikiStringArray,
  writeWikiStateValue
} from '@/lib/wiki-client-state'

function normalized(value: string) {
  return value.replaceAll('-', '')
}

export function WikiReadingQuiz({
  pageId,
  title,
  quiz
}: {
  pageId: string
  title: string
  quiz: ReadingQuiz | null
}) {
  const normalizedPageId = normalized(pageId)
  const [readComplete, setReadComplete] = useState(false)
  const [quizComplete, setQuizComplete] = useState(false)
  const [answer, setAnswer] = useState('')
  const [message, setMessage] = useState('')

  useEffect(() => {
    const refresh = () => {
      setReadComplete(
        readWikiStringArray('readPages').some(
          (value) => normalized(value) === normalizedPageId
        )
      )
      setQuizComplete(
        readWikiStringArray('readingQuizzes').some(
          (value) => normalized(value) === normalizedPageId
        )
      )
    }

    refresh()
    window.addEventListener('storage', refresh)
    window.addEventListener('justserver3:read-pages', refresh)
    window.addEventListener('justserver3:reading-quiz', refresh)
    return () => {
      window.removeEventListener('storage', refresh)
      window.removeEventListener('justserver3:read-pages', refresh)
      window.removeEventListener('justserver3:reading-quiz', refresh)
    }
  }, [normalizedPageId])

  if (!quiz) return null

  const submit = (option: string) => {
    setAnswer(option)

    if (option !== quiz.answer) {
      setMessage('본문에서 다시 찾아보세요. 정답은 문서 안에 있습니다.')
      track('wiki_reading_quiz_answer', {
        result: 'wrong',
        page: title
      })
      return
    }

    const completed = readWikiStringArray('readingQuizzes')
    if (!completed.some((value) => normalized(value) === normalizedPageId)) {
      writeWikiStateValue(
        'readingQuizzes',
        [...completed, normalizedPageId],
        'justserver3:reading-quiz'
      )

      let record
      try {
        record = normalizeSurvivalRecord(
          readWikiStateValue('survivalRecord', null)
        )
      } catch {
        record = normalizeSurvivalRecord(null)
      }

      const next = recordSurvivalActivity(
        record,
        seoulDateKey(),
        'reading-quiz',
        normalizedPageId
      )
      writeWikiStateValue(
        'survivalRecord',
        next,
        'justserver3:survival-record'
      )
    }

    setQuizComplete(true)
    setMessage('정답! 이 문서의 완독 배지를 획득했습니다. ✓')
    track('wiki_reading_quiz_answer', {
      result: 'correct',
      page: title
    })
  }

  return (
    <section
      className={`reading-quiz-card ${quizComplete ? 'is-complete' : ''}`}
      aria-labelledby="reading-quiz-title"
    >
      <div className="reading-quiz-head">
        <div>
          <p>ONE QUESTION</p>
          <h2 id="reading-quiz-title">📚 {title} 완독 퀴즈</h2>
          <span>
            시험이 아니라 문서를 한 번 더 훑어보는 작은 확인 문제입니다.
          </span>
        </div>
        <b>{quizComplete ? '완독 인증 ✓' : readComplete ? '퀴즈 열림' : '읽는 중'}</b>
      </div>

      {!readComplete ? (
        <div className="reading-quiz-locked">
          <span aria-hidden="true">🔒</span>
          <div>
            <strong>문서를 조금 더 읽으면 퀴즈가 열립니다.</strong>
            <small>
              본문의 절반 정도를 읽거나 일정 시간 내용을 확인하면 자동으로 완독 처리됩니다.
            </small>
          </div>
        </div>
      ) : (
        <>
          <strong className="reading-quiz-question">{quiz.prompt}</strong>
          <div className="reading-quiz-options">
            {quiz.options.map((option) => {
              const selected = answer === option
              const correct = quizComplete && option === quiz.answer
              return (
                <button
                  key={option}
                  type="button"
                  className={correct ? 'is-correct' : selected ? 'is-selected' : ''}
                  disabled={quizComplete}
                  onClick={() => submit(option)}
                >
                  <span>{option}</span>
                  <b>{correct ? '✓' : '→'}</b>
                </button>
              )
            })}
          </div>
          {message && (
            <p
              className={`reading-quiz-message ${quizComplete ? 'is-success' : ''}`}
              role="status"
            >
              {message}
            </p>
          )}
        </>
      )}
    </section>
  )
}

type NextPage = {
  pageId: string
  title: string
  category?: string | null
  image?: string | null
}

export function WikiNextExploration({
  currentTitle,
  pages
}: {
  currentTitle: string
  pages: NextPage[]
}) {
  const [readIds, setReadIds] = useState<string[]>([])

  useEffect(() => {
    const refresh = () => setReadIds(readWikiStringArray('readPages'))
    refresh()
    window.addEventListener('storage', refresh)
    window.addEventListener('justserver3:read-pages', refresh)
    return () => {
      window.removeEventListener('storage', refresh)
      window.removeEventListener('justserver3:read-pages', refresh)
    }
  }, [])

  const readSet = useMemo(
    () => new Set(readIds.map(normalized)),
    [readIds]
  )
  const ordered = useMemo(
    () =>
      [...pages].sort((left, right) => {
        const leftRead = readSet.has(normalized(left.pageId))
        const rightRead = readSet.has(normalized(right.pageId))
        if (leftRead !== rightRead) return leftRead ? 1 : -1
        return 0
      }),
    [pages, readSet]
  )

  if (!ordered.length) return null

  return (
    <section
      className="next-exploration"
      aria-labelledby="next-exploration-title"
    >
      <div className="next-exploration-head">
        <div>
          <p>NEXT EXPLORATION</p>
          <h2 id="next-exploration-title">이 문서를 읽었다면 다음은 여기</h2>
          <span>
            {currentTitle}과 연결되는 가이드 중 아직 완독하지 않은 문서를 먼저 추천합니다.
          </span>
        </div>
      </div>

      <div className="next-exploration-grid">
        {ordered.map((page, index) => {
          const completed = readSet.has(normalized(page.pageId))
          return (
            <Link
              key={page.pageId}
              href={withBasePath(`/page/${page.pageId}/`)}
              className={completed ? 'is-complete' : ''}
              data-wiki-event="wiki_next_exploration_navigate"
              data-wiki-section="next-exploration"
              data-wiki-target={page.title}
            >
              <span className="next-exploration-index">
                {completed ? '✓' : index + 1}
              </span>
              {page.image && (
                <span className="next-exploration-image" aria-hidden="true">
                  <img
                    src={page.image}
                    alt=""
                    loading="lazy"
                    decoding="async"
                    width="320"
                    height="180"
                  />
                </span>
              )}
              <span className="next-exploration-copy">
                <small>
                  {completed
                    ? '완독한 가이드'
                    : page.category || '추천 가이드'}
                </small>
                <strong>{page.title}</strong>
                <em>{completed ? '다시 보기' : '다음 탐험 시작'} →</em>
              </span>
            </Link>
          )
        })}
      </div>
    </section>
  )
}

