export function weeklyWikiBoss(
  activityByDay: Record<string, BossActivity>,
  weekKey: string
) {
  const start = dateKeyDayNumber(weekKey)
  let reads = 0
  const quizzes = new Set<string>()
  const treasures = new Set<string>()
  let fortune = 0
  let personalityQuiz = 0
  let random = 0

  for (let offset = 0; offset < 7; offset += 1) {
    const activity = activityByDay[dayNumberDateKey(start + offset)]
    if (!activity) continue

    reads += (activity.reads || []).length
    for (const id of activity.readingQuizzes || []) quizzes.add(normalizeId(id))
    for (const id of activity.treasures || []) treasures.add(normalizeId(id))
    fortune += Math.max(0, Math.floor(activity.fortune || 0))
    personalityQuiz += Math.max(0, Math.floor(activity.quiz || 0))
    random += Math.max(0, Math.floor(activity.random || 0))
  }

  const hp = 100
  const damage = Math.min(
    hp,
    reads * 12 +
      quizzes.size * 8 +
      treasures.size * 12 +
      fortune * 3 +
      personalityQuiz * 6 +
      random * 3
  )
  const boss = BOSSES[stableHash('boss:' + weekKey) % BOSSES.length]

  return {
    ...boss,
    hp,
    damage,
    remaining: Math.max(0, hp - damage),
    percent: Math.min(100, damage),
    defeated: damage >= hp,
    actions: {
      reads,
      quizzes: quizzes.size,
      treasures: treasures.size,
      fortune,
      personalityQuiz,
      random
    }
  }
}


export function nextAdventureAction(
  story: Array<StoryChapter & { unlocked: boolean; complete: boolean }>,
  buildPages: AdventurePage[],
  readIds: string[],
  allPages: AdventurePage[]
) {
  const read = new Set(readIds.map(normalizeId))
  const activeChapter = story.find(
    (chapter) => chapter.unlocked && !chapter.complete
  )

  const storyTarget =
    activeChapter?.choices.find(
      (page) => !read.has(normalizeId(page.pageId))
    ) || activeChapter?.choices[0]

  if (storyTarget) {
    return {
      kind: 'story' as const,
      eyebrow: 'STORY NEXT',
      title: storyTarget.title,
      description: activeChapter?.title || '스토리 모드 이어하기',
      page: storyTarget
    }
  }

  const buildTarget = buildPages.find(
    (page) => !read.has(normalizeId(page.pageId))
  )
  if (buildTarget) {
    return {
      kind: 'build' as const,
      eyebrow: 'BUILD NEXT',
      title: buildTarget.title,
      description: '추천 생존 빌드의 다음 단계',
      page: buildTarget
    }
  }

  const unread = allPages.find(
    (page) => !read.has(normalizeId(page.pageId))
  )
  if (unread) {
    return {
      kind: 'explore' as const,
      eyebrow: 'EXPLORE NEXT',
      title: unread.title,
      description: '아직 완독하지 않은 가이드',
      page: unread
    }
  }

  const reread = allPages[0] || null
  return reread
    ? {
        kind: 'reread' as const,
        eyebrow: 'WEEKLY BOSS',
        title: reread.title,
        description: '다시 읽고 이번 주 보스에게 피해 주기',
        page: reread
      }
    : null
}

export const WIKI_STATE_KEY = 'justserver3-state-v2'
export const WIKI_STATE_EVENT = 'justserver3:state'

export type WikiStateField =
  | 'recentPages'
  | 'visitedPages'
  | 'readPages'
  | 'readMigration'
  | 'survivalRecord'
  | 'dailyFortune'
  | 'funStats'
  | 'treasures'
  | 'seenAchievements'
  | 'seenStoryChapters'
  | 'seenBossWeeks'
  | 'readingQuizzes'
  | 'enhancementLab'

type WikiClientState = {
  version: 2
  values: Partial<Record<WikiStateField, unknown>>
}

const LEGACY_KEYS: Record<WikiStateField, string> = {
  recentPages: 'justserver3-recent-pages-v1',
  visitedPages: 'justserver3-visited-pages-v1',
  readPages: 'justserver3-read-pages-v1',
  readMigration: 'justserver3-read-pages-migrated-v1',
  survivalRecord: 'justserver3-survival-record-v1',
  dailyFortune: 'justserver3-daily-fortune-v1',
  funStats: 'justserver3-fun-stats-v1',
  treasures: 'justserver3-treasures-v1',
  seenAchievements: 'justserver3-seen-achievements-v1',
  seenStoryChapters: 'justserver3-seen-story-chapters-v1',
  seenBossWeeks: 'justserver3-seen-boss-weeks-v1',
  readingQuizzes: 'justserver3-reading-quizzes-v1',
  enhancementLab: 'justserver3-enhancement-lab-v1'
}

function parseStoredValue(raw: string) {
  try {
    return JSON.parse(raw) as unknown
  } catch {
    return raw
  }
}

function emptyState(): WikiClientState {
  return { version: 2, values: {} }
}

function loadState(): WikiClientState {
  if (typeof window === 'undefined') return emptyState()

  let state = emptyState()

  try {
    const parsed = JSON.parse(
      window.localStorage.getItem(WIKI_STATE_KEY) || 'null'
    ) as Partial<WikiClientState> | null

    if (
      parsed &&
      parsed.version === 2 &&
      parsed.values &&
      typeof parsed.values === 'object'
    ) {
      state = {
        version: 2,
        values: { ...parsed.values }
      }
    }
  } catch {}

  let migrated = false

  for (const [field, legacyKey] of Object.entries(LEGACY_KEYS) as [
    WikiStateField,
    string
  ][]) {
    if (state.values[field] !== undefined) continue
    const legacy = window.localStorage.getItem(legacyKey)
    if (legacy === null) continue
    state.values[field] = parseStoredValue(legacy)
    migrated = true
  }

  if (migrated) {
    try {
      window.localStorage.setItem(WIKI_STATE_KEY, JSON.stringify(state))
    } catch {}
  }

  return state
}

function persistState(state: WikiClientState) {
  try {
    window.localStorage.setItem(WIKI_STATE_KEY, JSON.stringify(state))
  } catch {}
}

function mirrorLegacy(field: WikiStateField, value: unknown) {
  const key = LEGACY_KEYS[field]

  try {
    window.localStorage.setItem(
      key,
      field === 'readMigration' && value
        ? '1'
        : typeof value === 'string'
          ? value
          : JSON.stringify(value)
    )
  } catch {}
}

function announce(eventName?: string) {
  window.dispatchEvent(new Event(WIKI_STATE_EVENT))
  if (eventName) window.dispatchEvent(new Event(eventName))
}

export function readWikiStateValue<T>(
  field: WikiStateField,
  fallback: T
): T {
  if (typeof window === 'undefined') return fallback
  const value = loadState().values[field]
  return value === undefined ? fallback : (value as T)
}

export function readWikiStringArray(field: WikiStateField) {
  const value = readWikiStateValue<unknown>(field, [])
  return Array.isArray(value)
    ? value.filter((item): item is string => typeof item === 'string')
    : []
}

export function writeWikiStateValue(
  field: WikiStateField,
  value: unknown,
  eventName?: string
) {
  if (typeof window === 'undefined') return

  const state = loadState()
  state.values[field] = value
  persistState(state)
  mirrorLegacy(field, value)
  announce(eventName)
}

export function removeWikiStateValue(
  field: WikiStateField,
  eventName?: string
) {
  if (typeof window === 'undefined') return

  const state = loadState()
  delete state.values[field]
  persistState(state)

  try {
    window.localStorage.removeItem(LEGACY_KEYS[field])
  } catch {}

  announce(eventName)
}

export type WikiHealthStatus = 'draft' | 'brief' | 'detailed'

export type WikiHealthPage = {
  pageId: string
  title: string
  searchText?: string | null
  status?: WikiHealthStatus | null
  lastEdited?: string | null
}

export type WikiContentHealth = {
  pageId: string
  title: string
  status: WikiHealthStatus
  score: number
  textLength: number
  stage: 'source-needed' | 'expand' | 'maintain'
  issues: string[]
  nextAction: string
}

const PLACEHOLDER_PATTERN =
  /위키\s*업데이트\s*예정|내용\s*추가\s*예정|작성\s*중/i

const CORE_BACKLOG_TITLES = new Set([
  '도감',
  '빚 갚기',
  '신용등급',
  '장비수리',
  '장비강화',
  '많이 물어보는 것'
])

function compactText(value?: string | null) {
  return (value || '').replace(/\s+/g, ' ').trim()
}

function inferStatus(page: WikiHealthPage): WikiHealthStatus {
  if (
    page.status === 'draft' ||
    page.status === 'brief' ||
    page.status === 'detailed'
  ) {
    return page.status
  }

  const text = compactText(page.searchText)
  if (PLACEHOLDER_PATTERN.test(text) || text.length < 80) return 'draft'
  if (text.length < 220) return 'brief'
  return 'detailed'
}

export function wikiContentHealth(
  page: WikiHealthPage
): WikiContentHealth {
  const text = compactText(page.searchText)
  const status = inferStatus(page)
  const placeholder = PLACEHOLDER_PATTERN.test(text)
  const issues: string[] = []
  let score = 0

  if (placeholder) {
    score += 100
    issues.push('원문이 업데이트 예정 상태')
  } else if (status === 'draft') {
    score += 82
    issues.push('본문 정보가 매우 적음')
  } else if (status === 'brief') {
    score += 48
    issues.push('핵심 설명만 있는 간단 문서')
  } else {
    score += 8
  }

  if (text.length < 120) {
    score += 14
    if (!issues.includes('본문 정보가 매우 적음')) {
      issues.push('설명 분량이 짧음')
    }
  }

  if (CORE_BACKLOG_TITLES.has(page.title) && status !== 'detailed') {
    score += 18
    issues.push('핵심 플레이 흐름과 연결되는 문서')
  }

  const stage =
    placeholder || status === 'draft'
      ? 'source-needed'
      : status === 'brief'
        ? 'expand'
        : 'maintain'

  const nextAction =
    stage === 'source-needed'
      ? '공식 원문·공지에서 사실과 수치를 확인한 뒤 본문 후보를 추가'
      : stage === 'expand'
        ? '조건·보상·주의사항·연결 문서를 보강'
        : '최근 변경 여부와 링크 정확도만 점검'

  return {
    pageId: page.pageId,
    title: page.title,
    status,
    score,
    textLength: text.length,
    stage,
    issues: [...new Set(issues)],
    nextAction
  }
}

export function buildWikiContentBacklog(
  pages: WikiHealthPage[],
  limit = pages.length
) {
  return pages
    .map(wikiContentHealth)
    .filter((item) => item.stage !== 'maintain')
    .sort(
      (a, b) =>
        b.score - a.score ||
        a.textLength - b.textLength ||
        a.title.localeCompare(b.title, 'ko')
    )
    .slice(0, Math.max(0, limit))
}

export function wikiContentReadiness(pages: WikiHealthPage[]) {
  const health = pages.map(wikiContentHealth)
  const total = health.length
  const detailed = health.filter((item) => item.status === 'detailed').length
  const brief = health.filter((item) => item.status === 'brief').length
  const draft = health.filter((item) => item.status === 'draft').length

  return {
    total,
    detailed,
    brief,
    draft,
    ready: detailed + brief,
    percent: total
      ? Math.round(((detailed + brief) / total) * 100)
      : 0
  }
}

