export function seoulDateKey(value = new Date()) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Seoul',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(value)

  const get = (type: Intl.DateTimeFormatPartTypes) =>
    parts.find((part) => part.type === type)?.value || ''

  return `${get('year')}-${get('month')}-${get('day')}`
}

export function uniqueNormalizedPageIds(values: string[]) {
  return [
    ...new Set(
      values
        .map((value) => value.replaceAll('-', '').trim())
        .filter(Boolean)
    )
  ]
}

export function wikiExplorationProgress(
  visitedIds: string[],
  availableIds: string[]
) {
  const available = uniqueNormalizedPageIds(availableIds)
  const availableSet = new Set(available)
  const visited = uniqueNormalizedPageIds(visitedIds).filter((pageId) =>
    availableSet.has(pageId)
  )

  const total = available.length
  const count = visited.length
  const percent = total ? Math.round((count / total) * 100) : 0

  return { count, total, percent, visited }
}

export function highestScoreKey<T extends string>(
  scores: Record<T, number>,
  fallback: T
) {
  const entries = Object.entries(scores) as Array<[T, number]>
  return entries.reduce(
    (best, current) => (current[1] > best[1] ? current : best),
    [fallback, scores[fallback] ?? 0] as [T, number]
  )[0]
}


export type WikiFunStats = {
  fortuneDraws: number
  quizCompletions: number
  randomRolls: number
  eggs: string[]
  lastQuizResult: string | null
}

export type WikiAchievementId =
  | 'first-step'
  | 'guide'
  | 'explorer'
  | 'conqueror'
  | 'fortune'
  | 'analyst'
  | 'randomizer'
  | 'secret-hunter'
  | 'egg-master'

export const EMPTY_WIKI_FUN_STATS: WikiFunStats = {
  fortuneDraws: 0,
  quizCompletions: 0,
  randomRolls: 0,
  eggs: [],
  lastQuizResult: null
}

function safeCount(value: unknown) {
  return typeof value === 'number' && Number.isFinite(value)
    ? Math.max(0, Math.floor(value))
    : 0
}

export function normalizeWikiFunStats(value: unknown): WikiFunStats {
  if (!value || typeof value !== 'object') {
    return { ...EMPTY_WIKI_FUN_STATS }
  }

  const candidate = value as Partial<WikiFunStats>
  const eggs = Array.isArray(candidate.eggs)
    ? [
        ...new Set(
          candidate.eggs.filter(
            (egg): egg is string => typeof egg === 'string' && Boolean(egg)
          )
        )
      ]
    : []

  return {
    fortuneDraws: safeCount(candidate.fortuneDraws),
    quizCompletions: safeCount(candidate.quizCompletions),
    randomRolls: safeCount(candidate.randomRolls),
    eggs,
    lastQuizResult:
      typeof candidate.lastQuizResult === 'string' &&
      candidate.lastQuizResult.trim()
        ? candidate.lastQuizResult
        : null
  }
}

export function unlockedWikiAchievementIds(
  progress: { count: number; total: number; percent: number },
  stats: WikiFunStats
): WikiAchievementId[] {
  const unlocked: WikiAchievementId[] = []

  if (progress.count >= 1) unlocked.push('first-step')
  if (progress.count >= 3) unlocked.push('guide')
  if (progress.percent >= 50) unlocked.push('explorer')
  if (progress.total > 0 && progress.count >= progress.total) {
    unlocked.push('conqueror')
  }
  if (stats.fortuneDraws >= 1) unlocked.push('fortune')
  if (stats.quizCompletions >= 1) unlocked.push('analyst')
  if (stats.randomRolls >= 3) unlocked.push('randomizer')
  if (stats.eggs.length >= 1) unlocked.push('secret-hunter')
  if (stats.eggs.length >= 2) unlocked.push('egg-master')

  return unlocked
}

export function wikiTitleFromAchievements(
  ids: WikiAchievementId[]
) {
  const unlocked = new Set(ids)

  if (unlocked.has('conqueror')) return '위키 정복자'
  if (unlocked.has('egg-master')) return '이스터에그 헌터'
  if (unlocked.has('explorer')) return '적자생존 탐험가'
  if (unlocked.has('guide')) return '위키 길잡이'
  if (unlocked.has('analyst')) return '성향 분석가'
  if (unlocked.has('randomizer')) return '운명 결정사'
  if (unlocked.has('fortune')) return '운세 입문자'
  if (unlocked.has('first-step')) return '첫 발자국'

  return '신입 생존자'
}

export type ReadingGamePage = {
  pageId: string
  title: string
  category?: string | null
  searchText?: string | null
}

function normalizeId(value: string) {
  return value.replaceAll('-', '').trim()
}

function stableHash(value: string) {
  let hash = 2166136261
  for (const character of value) {
    hash ^= character.charCodeAt(0)
    hash = Math.imul(hash, 16777619)
  }
  return hash >>> 0
}

export function uniqueReadingIds(values: string[]) {
  return [
    ...new Set(values.map(normalizeId).filter(Boolean))
  ]
}

export function readingCollectionSets(
  pages: ReadingGamePage[],
  readIds: string[]
) {
  const read = new Set(uniqueReadingIds(readIds))
  const definitions = [
    {
      category: '시작하기',
      icon: '🧭',
      title: '초보 생존 세트',
      description: '처음 시작할 때 필요한 핵심 문서'
    },
    {
      category: '주요 콘텐츠',
      icon: '🎮',
      title: '콘텐츠 탐험 세트',
      description: '서버에서 즐길 수 있는 주요 콘텐츠'
    },
    {
      category: '성장 · 경제',
      icon: '📈',
      title: '경제 · 성장 세트',
      description: '돈과 장비 성장에 필요한 가이드'
    }
  ]

  return definitions
    .map((definition) => {
      const targets = pages.filter(
        (page) => (page.category || '기타') === definition.category
      )
      const completed = targets.filter((page) =>
        read.has(normalizeId(page.pageId))
      ).length
      return {
        ...definition,
        count: completed,
        total: targets.length,
        percent: targets.length
          ? Math.round((completed / targets.length) * 100)
          : 0,
        complete: targets.length > 0 && completed === targets.length
      }
    })
    .filter((set) => set.total > 0)
}

export function dailyExplorationQuest(
  pages: ReadingGamePage[],
  dateKey: string
) {
  if (!pages.length) {
    return {
      id: 'empty',
      icon: '🧭',
      title: '오늘의 탐험',
      description: '준비된 가이드가 추가되면 탐험 루트가 열립니다.',
      pages: [] as ReadingGamePage[]
    }
  }

  const grouped = new Map<string, ReadingGamePage[]>()
  for (const page of pages) {
    const category = page.category || '기타'
    grouped.set(category, [...(grouped.get(category) || []), page])
  }

  const categories = [...grouped.keys()].sort()
  const category =
    categories[stableHash('quest-category:' + dateKey) % categories.length]
  const candidates = [...(grouped.get(category) || [])]
    .sort(
      (left, right) =>
        stableHash(dateKey + ':' + left.pageId) -
        stableHash(dateKey + ':' + right.pageId)
    )
    .slice(0, 3)

  const labels: Record<
    string,
    { icon: string; title: string; description: string }
  > = {
    시작하기: {
      icon: '🧭',
      title: '오늘의 의뢰 · 생존 준비',
      description: '처음 시작할 때 알아두면 좋은 문서를 차례로 확인하세요.'
    },
    '주요 콘텐츠': {
      icon: '🎮',
      title: '오늘의 의뢰 · 콘텐츠 탐험',
      description: '서버의 주요 콘텐츠를 따라가며 탐험도를 올려보세요.'
    },
    '성장 · 경제': {
      icon: '💰',
      title: '오늘의 의뢰 · 적자 탈출',
      description: '경제와 성장 문서를 읽고 생존 루트를 완성하세요.'
    }
  }

  const label = labels[category] || {
    icon: '🗺️',
    title: '오늘의 의뢰 · 위키 탐험',
    description: '추천된 문서를 읽고 오늘의 탐험을 완료하세요.'
  }

  return {
    id: category + ':' + dateKey,
    ...label,
    pages: candidates
  }
}

export function unreadRecommendations(
  pages: ReadingGamePage[],
  readIds: string[],
  limit = 3
) {
  const read = new Set(uniqueReadingIds(readIds))
  const sets = readingCollectionSets(pages, readIds)
    .filter((set) => !set.complete)
    .sort((left, right) => {
      if (right.percent !== left.percent) return right.percent - left.percent
      return left.category.localeCompare(right.category, 'ko')
    })

  const categoryPriority = new Map(
    sets.map((set, index) => [set.category, index])
  )

  return pages
    .filter((page) => !read.has(normalizeId(page.pageId)))
    .sort((left, right) => {
      const a = categoryPriority.get(left.category || '기타') ?? 99
      const b = categoryPriority.get(right.category || '기타') ?? 99
      if (a !== b) return a - b
      return left.title.localeCompare(right.title, 'ko')
    })
    .slice(0, limit)
}

