  const story = storyProgress(chapters, [])
  const action = nextAdventureAction(
    story,
    [{ pageId: 'mine', title: '채광', category: '주요 콘텐츠' }],
    [],
    pages
  )

  assert.equal(action?.kind, 'story')
  assert.equal(action?.page.pageId, chapters[0].choices[0].pageId)
})

